#[derive(Component, Clone)]
struct DisplayName {
    value: String,
    localization_key: Option<String>,
}

impl DisplayName {
    fn literal(value: impl Into<String>) -> Self {
        Self {
            value: value.into(),
            localization_key: None,
        }
    }

    fn localized(localization_key: impl Into<String>, fallback: impl Into<String>) -> Self {
        Self {
            value: fallback.into(),
            localization_key: Some(localization_key.into()),
        }
    }

    fn resolve(&self, language: LanguageCode) -> String {
        match self.localization_key.as_deref() {
            Some(key) => localized_text_or_fallback(language, key, &self.value),
            None => self.value.clone(),
        }
    }
}

