fn localized_quest_stage_copy(
    language: LanguageCode,
    quest_id: i32,
    stage: QuestStage,
    fallback_template: &QuestTemplate,
) -> QuestStageCopy {
    let fallback = match stage {
        QuestStage::Available => &fallback_template.stages.available,
        QuestStage::InProgress => &fallback_template.stages.in_progress,
        QuestStage::ReadyToTurnIn => &fallback_template.stages.ready_to_turn_in,
        QuestStage::Completed => &fallback_template.stages.completed,
    };
    let Some(base) = localized_quest_base_key(quest_id) else {
        return fallback.clone();
    };
    let stage_key = quest_stage_key(stage);
    QuestStageCopy {
        objective: localized_text_or_fallback(
            language,
            &format!("{base}.stage.{stage_key}.objective"),
            &fallback.objective,
        ),
        progress_label: localized_text_or_fallback(
            language,
            &format!("{base}.stage.{stage_key}.progressLabel"),
            &fallback.progress_label,
        ),
        tracker: localized_text_or_fallback(
            language,
            &format!("{base}.stage.{stage_key}.tracker"),
            &fallback.tracker,
        ),
    }
}

fn npc_script_for_object_id(npc_object_id: u32) -> Option<NpcScriptTemplate> {
    starter_server_data()
        .npc_scripts
        .into_iter()
        .find(|script| script.npc_object_id == npc_object_id)
}

fn equipment_slot_from_template(slot: &str) -> EquipmentSlot {
    match slot {
        "weapon" => EquipmentSlot::Weapon,
        "armour" => EquipmentSlot::Armour,
        "helmet" => EquipmentSlot::Helmet,
        "mount" => EquipmentSlot::Mount,
        "necklace" => EquipmentSlot::Necklace,
        "torch" => EquipmentSlot::Torch,
        "bracelet_left" => EquipmentSlot::BraceletLeft,
        "bracelet_right" => EquipmentSlot::BraceletRight,
        "ring_left" => EquipmentSlot::RingLeft,
        "ring_right" => EquipmentSlot::RingRight,
        "amulet" => EquipmentSlot::Amulet,
        "boots" => EquipmentSlot::Boots,
        "belt" => EquipmentSlot::Belt,
        "stone" => EquipmentSlot::Stone,
        other => panic!("unknown equipment slot template: {other}"),
    }
}

