fn runtime_map_collision_data(map_file_name: &str) -> Option<RuntimeMapCollisionData> {
    let normalized = normalize_map_file_name(map_file_name);
    static RUNTIME_MAP_COLLISION_CACHE: OnceLock<
        Mutex<BTreeMap<String, Option<RuntimeMapCollisionData>>>,
    > = OnceLock::new();
    let cache = RUNTIME_MAP_COLLISION_CACHE.get_or_init(|| Mutex::new(BTreeMap::new()));
    if let Some(cached) = cache
        .lock()
        .expect("runtime map collision cache should not be poisoned")
        .get(&normalized)
        .cloned()
    {
        return cached;
    }

    let parsed = runtime_map_collision_data_uncached(&normalized);
    cache
        .lock()
        .expect("runtime map collision cache should not be poisoned")
        .insert(normalized, parsed.clone());
    parsed
}

fn runtime_map_collision_data_uncached(normalized: &str) -> Option<RuntimeMapCollisionData> {
    if normalized == normalize_map_file_name("0") {
        return Some(runtime_map_collision_from_template(
            mir2_game_data::starter_map_collision(),
        ));
    }

    let map_path = crystal_map_path(&normalized)?;
    let bytes = fs::read(map_path).ok()?;
    let collision = parse_runtime_map_collision(&normalized, &bytes)?;
    Some(runtime_map_collision_from_template(collision))
}

fn runtime_map_collision_from_template(collision: StarterMapCollision) -> RuntimeMapCollisionData {
    let blocked_set = collision
        .blocked_cells
        .iter()
        .map(|cell| (cell.x, cell.y))
        .collect();
    let closed_door_set = collision
        .doors
        .iter()
        .filter(|door| door.closed)
        .map(|door| (door.x, door.y))
        .collect();

    RuntimeMapCollisionData {
        collision,
        blocked_set,
        closed_door_set,
    }
}

fn crystal_map_path(map_file_name: &str) -> Option<PathBuf> {
    let client_root = std::env::var("CRYSTAL_CLIENT_ROOT")
        .unwrap_or_else(|_| DEFAULT_CRYSTAL_CLIENT_ROOT.to_string());
    let normalized = normalize_map_file_name(map_file_name);
    let candidate = PathBuf::from(client_root)
        .join("Map")
        .join(format!("{normalized}.map"));
    candidate.exists().then_some(candidate)
}

impl CrystalNpcRandomState {
    fn new() -> Self {
        Self { seed: 0 }
    }

    fn next_index(&mut self, upper_bound: u32) -> Option<u32> {
        if upper_bound == 0 {
            return None;
        }

        self.seed = self
            .seed
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1);
        Some(((self.seed >> 32) as u32) % upper_bound)
    }
}

