fn ensure_account_with_password(
    config: &SimulationConfig,
    account_id: &str,
    password: &str,
) -> Vec<CharacterRecord> {
    let mut store = config
        .account_store
        .lock()
        .expect("account store mutex should not be poisoned");
    let account = store
        .accounts
        .entry(account_id.to_string())
        .or_insert_with(|| AccountRecord::new(config.default_character.clone()));
    account.password = password.to_string();
    let characters = account.characters.clone();
    drop(store);
    if let Err(error) = config.save_account_store() {
        eprintln!("failed to persist account store: {error}");
    }
    characters
}

fn login_account(
    config: &SimulationConfig,
    account_id: &str,
    password: &str,
) -> Option<Vec<CharacterRecord>> {
    let mut store = config
        .account_store
        .lock()
        .expect("account store mutex should not be poisoned");
    let account = store
        .accounts
        .entry(account_id.to_string())
        .or_insert_with(|| AccountRecord::new(config.default_character.clone()));
    (account.password == password).then(|| account.characters.clone())
}

fn change_account_password(
    config: SimulationConfig,
    account_id: &str,
    current_password: &str,
    new_password: &str,
) -> u8 {
    if account_id.trim().is_empty() {
        return 1;
    }
    if current_password.trim().is_empty() {
        return 2;
    }
    if new_password.trim().is_empty() {
        return 3;
    }

    let mut store = config
        .account_store
        .lock()
        .expect("account store mutex should not be poisoned");
    let Some(account) = store.accounts.get_mut(account_id) else {
        return 4;
    };
    if account.password != current_password {
        return 5;
    }

    account.password = new_password.to_string();
    drop(store);
    if let Err(error) = config.save_account_store() {
        eprintln!("failed to persist account store: {error}");
    }
    6
}

fn add_character_to_account(
    config: &SimulationConfig,
    account_id: &str,
    mut character: CharacterRecord,
) -> CharacterRecord {
    let mut store = config
        .account_store
        .lock()
        .expect("account store mutex should not be poisoned");
    let account = store
        .accounts
        .entry(account_id.to_string())
        .or_insert_with(|| AccountRecord::new(config.default_character.clone()));
    character.index = account
        .characters
        .iter()
        .map(|character| character.index)
        .max()
        .map(|index| index + 1)
        .unwrap_or(0);
    account.characters.push(character.clone());
    account
        .saves
        .insert(character.index, CharacterSaveRecord::new(character.clone()));
    drop(store);
    if let Err(error) = config.save_account_store() {
        eprintln!("failed to persist account store: {error}");
    }
    character
}

fn delete_character_from_account(
    config: &SimulationConfig,
    account_id: &str,
    character_index: i32,
) -> Result<String, String> {
    let mut store = config
        .account_store
        .lock()
        .expect("account store mutex should not be poisoned");
    let account = store
        .accounts
        .entry(account_id.to_string())
        .or_insert_with(|| AccountRecord::new(config.default_character.clone()));

    if account.characters.len() <= 1 {
        return Err("At least one character must remain on the account.".to_string());
    }

    let Some(existing) = account
        .characters
        .iter()
        .find(|character| character.index == character_index)
        .cloned()
    else {
        return Err("Character not found.".to_string());
    };

    account
        .characters
        .retain(|character| character.index != character_index);
    account.saves.remove(&character_index);

    drop(store);
    if let Err(error) = config.save_account_store() {
        eprintln!("failed to persist account store: {error}");
    }
    Ok(existing.name)
}

fn character_save_for_start(
    resources: &SimulationResources,
    account_id: &str,
    character_index: i32,
) -> Option<CharacterSaveRecord> {
    let mut store = resources
        .config
        .account_store
        .lock()
        .expect("account store mutex should not be poisoned");
    let account = store
        .accounts
        .entry(account_id.to_string())
        .or_insert_with(|| AccountRecord::new(resources.config.default_character.clone()));
    let character = account
        .characters
        .iter()
        .find(|character| character.index == character_index)
        .cloned()?;
    Some(
        account
            .saves
            .entry(character_index)
            .or_insert_with(|| resources.default_save_for_character(character.clone()))
            .clone(),
    )
}

fn apply_character_save(resources: &mut SimulationResources, save: &CharacterSaveRecord) {
    resources.selected_character = Some(save.character.clone());
    resources.current_map = resources.config.map.clone();
    if !save.map_file_name.is_empty() {
        resources.current_map.file_name = save.map_file_name.clone();
    }
    if !save.map_title.is_empty() {
        resources.current_map.title = save.map_title.clone();
    }
    resources.player_position = if save.position == (Point { x: 0, y: 0 }) {
        resources.config.spawn.clone()
    } else {
        save.position.clone()
    };
    resources.player_direction = save.direction;
    resources.player_vitals = PlayerVitals {
        hp: save.hp.max(1),
        max_hp: save.max_hp.max(1),
        mp: save.mp.max(0),
    };
    resources.experience = save.experience.max(0);
    resources.max_experience = save.max_experience.max(1);
    resources.gold = save.gold;
    resources.credit = save.credit;
    resources.inventory_items = if save.inventory_items_json.is_empty() {
        seed_inventory_items()
    } else {
        decode_state_vec(&save.inventory_items_json).unwrap_or_else(seed_inventory_items)
    };
    resources.belt_items = if save.belt_items_json.is_empty() {
        seed_belt_items()
    } else {
        decode_state_vec(&save.belt_items_json).unwrap_or_else(seed_belt_items)
    };
    resources.storage_items = if save.storage_items_json.is_empty() {
        seed_storage_items()
    } else {
        decode_state_vec(&save.storage_items_json).unwrap_or_else(seed_storage_items)
    };
    resources.equipment_items = if save.equipment_items_json.is_empty() {
        seed_equipment_items()
    } else {
        decode_state_vec(&save.equipment_items_json).unwrap_or_else(seed_equipment_items)
    };
    resources.quests = if save.quest_states_json.is_empty() {
        vec![QuestState::guide_training()]
    } else {
        decode_state_vec(&save.quest_states_json)
            .unwrap_or_else(|| vec![QuestState::guide_training()])
    };
    resources.skills = if save.skill_states_json.is_empty() {
        seed_skills()
    } else {
        decode_state_vec(&save.skill_states_json).unwrap_or_else(seed_skills)
    };
    resources.npc_flags = if save.npc_flag_states_json.is_empty() {
        Vec::new()
    } else {
        decode_state_vec(&save.npc_flag_states_json).unwrap_or_default()
    };
    resources.npc_saved_values = if save.npc_saved_values_json.is_empty() {
        Vec::new()
    } else {
        decode_state_vec(&save.npc_saved_values_json).unwrap_or_default()
    };
    resources.npc_buy_back_items = if save.npc_buy_back_items_json.is_empty() {
        Vec::new()
    } else {
        decode_state_vec(&save.npc_buy_back_items_json).unwrap_or_default()
    };
    resources.npc_used_goods_items = if save.npc_used_goods_items_json.is_empty() {
        Vec::new()
    } else {
        decode_state_vec(&save.npc_used_goods_items_json).unwrap_or_default()
    };
    resources.stage5_systems = save
        .stage5_systems_json
        .as_deref()
        .and_then(|state| serde_json::from_str::<Stage5SystemsState>(state).ok())
        .unwrap_or_default();
    resources.npc_variables = Vec::new();
    resources.buffs = Vec::new();
    resources.active_npc_dialog = None;
    resources.active_npc_service = None;
    resources.pending_combat_actions = Vec::new();
    resources.pending_monster_spawns = Vec::new();
    resources.tick = 0;
    resources.next_drop_object_id = 5000;
    resources.next_runtime_monster_object_id = 80_000;
}

fn build_world_snapshot(world: &World) -> WorldSnapshot {
    let resources = world.resource::<SimulationResources>();
    let language = resources.language;
    let scene_view = active_scene_view(world);
    let mut entities = collect_world_entities(
        world,
        scene_view.as_ref(),
        language,
        &resources.equipment_items,
    );
    entities.sort_by_key(|entity| entity.object_id);

    let player_object_id = current_player_object_id(world);
    let player_vitals = player_entity(world).and_then(|entity| entity_player_vitals(world, entity));

    WorldSnapshot {
        tick: resources.tick,
        map_title: resources
            .selected_character
            .as_ref()
            .map(|_| localized_map_title(language, &resources.current_map.title)),
        map_file_name: resources
            .selected_character
            .as_ref()
            .map(|_| resources.current_map.file_name.clone()),
        in_safe_zone: player_entity(world)
            .and_then(|entity| entity_position(world, entity))
            .map(|position| is_safe_zone_point(resources, &position))
            .unwrap_or(false),
        player_object_id,
        player_hp: player_vitals.map(|vitals| vitals.hp),
        player_max_hp: player_vitals.map(|vitals| vitals.max_hp),
        player_mp: player_vitals.map(|vitals| vitals.mp),
        player_experience: resources.experience,
        player_max_experience: resources.max_experience,
        gold: resources.gold,
        credit: resources.credit,
        current_weight: current_weight(&resources),
        max_weight: CRYSTAL_BAG_WEIGHT_LIMIT as u16,
        free_bag_slots: free_bag_slots(&resources),
        max_bag_slots: 80,
        storage_size: resources.storage_size,
        has_expanded_storage: resources.has_expanded_storage,
        has_storage_password: resources.storage_has_password,
        require_storage_password: storage_password_required(
            &resources.config,
            resources.storage_has_password,
            resources.storage_unlocked,
        ),
        storage_password_last_set_binary_datetime: resources
            .storage_password_last_set_binary_datetime,
        expanded_storage_expiry_time_binary_datetime: resources
            .expanded_storage_expiry_time_binary_datetime,
        scene_view: scene_view.clone(),
        terrain_patches: filter_terrain_patches(world, scene_view.as_ref()),
        decor_objects: filter_decor_objects(world, scene_view.as_ref()),
        entities,
        ground_drops: collect_ground_drops(world, scene_view.as_ref(), language),
        belt_items: resources
            .belt_items
            .iter()
            .map(|item| item.snapshot(language))
            .collect(),
        inventory_items: resources
            .inventory_items
            .iter()
            .map(|item| item.snapshot(language))
            .collect(),
        storage_items: resources
            .storage_items
            .iter()
            .map(|item| item.snapshot(language))
            .collect(),
        equipment_items: resources
            .equipment_items
            .iter()
            .map(|item| item.snapshot(language))
            .collect(),
        quest_log: resources
            .quests
            .iter()
            .map(|quest| quest.snapshot(language))
            .collect(),
        active_npc_dialog: resources
            .active_npc_dialog
            .as_ref()
            .map(|dialog| dialog.snapshot(language)),
        known_skills: resources
            .skills
            .iter()
            .map(|skill| skill.snapshot(resources.tick, language))
            .collect(),
        active_buffs: resources
            .buffs
            .iter()
            .filter(|buff| buff.expires_at_tick > resources.tick)
            .map(|buff| buff.snapshot(resources.tick, language))
            .collect(),
        stage5_systems: resources.stage5_systems.clone(),
        map_transfers: collect_map_transfer_snapshots(resources),
        interaction_hints: build_interaction_hints(&resources),
    }
}

fn collect_map_transfer_snapshots(resources: &SimulationResources) -> Vec<MapTransferSnapshot> {
    let current_map = normalize_map_file_name(&resources.current_map.file_name);
    let mut transfers: Vec<MapTransferSnapshot> = resources
        .config
        .map_transfers
        .iter()
        .filter(|transfer| normalize_map_file_name(&transfer.from_map_file_name) == current_map)
        .map(|transfer| MapTransferSnapshot {
            key: transfer.key.clone(),
            map_file_name: transfer.from_map_file_name.clone(),
            bounds: transfer.from_bounds,
            to_map_file_name: transfer.to_map_file_name.clone(),
            to_map_title: transfer.to_map_title.clone(),
            to_position: transfer.to_position.clone(),
            to_direction: transfer.to_direction,
        })
        .collect();

    transfers.extend(
        crystal_movement_transfer_records_for_map(&resources.current_map.file_name)
            .into_iter()
            .map(|transfer| MapTransferSnapshot {
                key: transfer.key,
                map_file_name: transfer.from_map_file_name,
                bounds: transfer.from_bounds,
                to_map_file_name: transfer.to_map_file_name,
                to_map_title: transfer.to_map_title,
                to_position: transfer.to_position,
                to_direction: transfer.to_direction,
            }),
    );

    transfers
}

#[allow(deprecated)]
fn collect_world_entities(
    world: &World,
    scene_view: Option<&mir2_game_data::SceneView>,
    language: LanguageCode,
    self_equipment_items: &[EquipmentState],
) -> Vec<WorldEntitySnapshot> {
    let mut result = Vec::new();
    for entity in world.iter_entities() {
        let Some(object_id) = entity.get::<ObjectId>() else {
            continue;
        };
        let Some(name) = entity.get::<DisplayName>() else {
            continue;
        };
        let Some(position) = entity.get::<Position>() else {
            continue;
        };
        let Some(facing) = entity.get::<Facing>() else {
            continue;
        };

        let body = entity.get::<CharacterBody>();
        let player_vitals = entity.get::<PlayerVitals>();
        let monster_agent = entity.get::<MonsterAgent>();
        let monster_vitals = entity.get::<MonsterVitals>();
        let self_marker = entity.get::<SelfPlayer>();
        let remote_marker = entity.get::<RemotePlayer>();
        let npc_marker = entity.get::<Npc>();

        if self_marker.is_none() && !point_visible(scene_view, &position.0) {
            continue;
        }

        let (kind, disposition, dead, hp, max_hp, level) = if self_marker.is_some() {
            (
                WorldEntityKind::SelfPlayer,
                WorldEntityDisposition::Friendly,
                false,
                player_vitals.map(|v| v.hp),
                player_vitals.map(|v| v.max_hp),
                body.map(|v| v.level),
            )
        } else if remote_marker.is_some() {
            (
                WorldEntityKind::Player,
                WorldEntityDisposition::Friendly,
                false,
                None,
                None,
                body.map(|v| v.level),
            )
        } else if let Some(agent) = monster_agent {
            (
                WorldEntityKind::Monster,
                agent.disposition,
                agent.dead,
                monster_vitals.map(|v| v.hp),
                monster_vitals.map(|v| v.max_hp),
                None,
            )
        } else if npc_marker.is_some() {
            (
                WorldEntityKind::Npc,
                WorldEntityDisposition::Neutral,
                false,
                None,
                None,
                None,
            )
        } else {
            continue;
        };

        let sprite = entity_sprite_snapshot(
            body,
            monster_agent,
            entity.get::<NpcAgent>(),
            if self_marker.is_some() {
                Some(self_equipment_items)
            } else {
                None
            },
        );

        result.push(WorldEntitySnapshot {
            object_id: object_id.0,
            kind,
            name: name.resolve(language),
            x: position.0.x,
            y: position.0.y,
            direction: facing.0,
            class: body.map(|body| body.class),
            gender: body.map(|body| body.gender),
            level,
            hp,
            max_hp,
            dead,
            disposition,
            sprite,
        });
    }

    result
}

fn entity_sprite_snapshot(
    body: Option<&CharacterBody>,
    monster_agent: Option<&MonsterAgent>,
    npc_agent: Option<&NpcAgent>,
    equipment_items: Option<&[EquipmentState]>,
) -> Option<WorldEntitySpriteSnapshot> {
    if let Some(body) = body {
        let armour_shape = equipment_shape(equipment_items, EquipmentSlot::Armour)
            .or(body.armour_shape)
            .unwrap_or(0);
        let hair_shape = 0;
        let weapon_shape =
            equipment_shape(equipment_items, EquipmentSlot::Weapon).or(body.weapon_shape);
        let uses_assassin_weapon =
            matches!(weapon_shape, Some(shape) if (100..200).contains(&shape));
        let uses_archer_weapon = matches!(weapon_shape, Some(shape) if shape >= 200);
        let body_library = format!("CArmour/{armour_shape:02}");
        let hair_library = Some(format!("CHair/{hair_shape:02}"));
        let (alt_body_library, alt_hair_library) = match body.class {
            MirClass::Assassin if uses_assassin_weapon => (
                Some(format!("AArmour/{armour_shape:02}")),
                Some(format!("AHair/{hair_shape:02}")),
            ),
            MirClass::Archer if uses_archer_weapon => (
                Some(format!("ARArmour/{armour_shape:02}")),
                Some(format!("ARHair/{hair_shape:02}")),
            ),
            _ => (None, None),
        };
        let (
            weapon_library,
            weapon_library_secondary,
            alt_weapon_library,
            alt_weapon_library_secondary,
        ) = match weapon_shape {
            Some(shape) if (100..200).contains(&shape) => {
                let index = shape - 100;
                (
                    None,
                    None,
                    Some(format!("AWeapon/{index:02} R")),
                    Some(format!("AWeapon/{index:02} L")),
                )
            }
            Some(shape) if shape >= 200 => {
                let index = shape - 200;
                (
                    Some(format!("ARWeapon/{index:02}")),
                    None,
                    Some(format!("ARWeapon/{index:02} S")),
                    None,
                )
            }
            Some(shape) => (Some(format!("CWeapon/{shape:02}")), None, None, None),
            None => (None, None, None, None),
        };
        let frame_base_offset = match body.gender {
            MirGender::Male => 0,
            MirGender::Female => 808,
        };
        let weapon_frame_offset = weapon_library.as_ref().map(|_| match body.gender {
            MirGender::Male => 0,
            MirGender::Female => 416,
        });
        let alt_frame_base_offset = match body.class {
            MirClass::Archer if uses_archer_weapon => Some(match body.gender {
                MirGender::Male => 0,
                MirGender::Female => 352,
            }),
            MirClass::Assassin if uses_assassin_weapon => Some(match body.gender {
                MirGender::Male => 0,
                MirGender::Female => 512,
            }),
            _ => None,
        };
        let alt_weapon_frame_offset = alt_frame_base_offset;

        return Some(WorldEntitySpriteSnapshot {
            body_library,
            hair_library,
            weapon_library,
            weapon_library_secondary,
            frame_base_offset,
            weapon_frame_offset,
            alt_body_library,
            alt_hair_library,
            alt_weapon_library,
            alt_weapon_library_secondary,
            alt_frame_base_offset,
            alt_weapon_frame_offset,
            frame_count: 4,
            direction_stride: 4,
        });
    }

    if let Some(monster) = monster_agent {
        return Some(WorldEntitySpriteSnapshot {
            body_library: format!("Monster/{:03}", monster.image),
            hair_library: None,
            weapon_library: None,
            weapon_library_secondary: None,
            frame_base_offset: 0,
            weapon_frame_offset: None,
            alt_body_library: None,
            alt_hair_library: None,
            alt_weapon_library: None,
            alt_weapon_library_secondary: None,
            alt_frame_base_offset: None,
            alt_weapon_frame_offset: None,
            frame_count: 4,
            direction_stride: 4,
        });
    }

    npc_agent.map(|npc| WorldEntitySpriteSnapshot {
        body_library: format!("NPC/{:02}", npc.image),
        hair_library: None,
        weapon_library: None,
        weapon_library_secondary: None,
        frame_base_offset: 0,
        weapon_frame_offset: None,
        alt_body_library: None,
        alt_hair_library: None,
        alt_weapon_library: None,
        alt_weapon_library_secondary: None,
        alt_frame_base_offset: None,
        alt_weapon_frame_offset: None,
        frame_count: 4,
        direction_stride: 4,
    })
}

#[allow(deprecated)]
fn collect_ground_drops(
    world: &World,
    scene_view: Option<&mir2_game_data::SceneView>,
    language: LanguageCode,
) -> Vec<GroundDropSnapshot> {
    let mut drops = Vec::new();

    for entity in world.iter_entities() {
        if entity.get::<GroundDrop>().is_none() {
            continue;
        }

        let object_id = entity.get::<ObjectId>().expect("drop object id").0;
        let name = entity
            .get::<DisplayName>()
            .expect("drop name")
            .resolve(language);
        let position = entity.get::<Position>().expect("drop position").0.clone();
        let payload = entity.get::<DropPayload>().expect("drop payload");
        if !point_visible(scene_view, &position) {
            continue;
        }

        drops.push(GroundDropSnapshot {
            object_id,
            name,
            name_colour_argb: crystal_drop_name_colour_argb(&payload.loot),
            x: position.x,
            y: position.y,
            quantity: payload.quantity,
            source_monster: match payload.source_monster_key.as_deref() {
                Some(key) => localized_text_or_fallback(language, key, &payload.source_monster),
                None => payload.source_monster.clone(),
            },
        });
    }

    drops.sort_by_key(|drop| drop.object_id);
    drops
}

#[allow(deprecated)]
fn collect_visible_objects(world: &World) -> BTreeMap<u32, VisibleObjectBundle> {
    let mut objects = BTreeMap::new();
    let scene_view = active_scene_view(world);
    let language = current_language(world);

    for entity in world.iter_entities() {
        let position = entity.get::<Position>().map(|value| value.0.clone());
        if let Some(position) = position.as_ref() {
            if !point_visible(scene_view.as_ref(), position) {
                continue;
            }
        }

        if entity.get::<SelfPlayer>().is_some() {
            continue;
        }

        if let Some((object_id, bundle)) =
            visible_object_bundle_for_entity(world, entity.id(), language)
        {
            objects.insert(object_id, bundle);
        }
    }

    objects
}

fn visible_object_bundle_for_entity(
    world: &World,
    entity: Entity,
    language: LanguageCode,
) -> Option<(u32, VisibleObjectBundle)> {
    let entry = world.entity(entity);
    let object_id = entry.get::<ObjectId>()?.0;

    if entry.get::<RemotePlayer>().is_some() {
        let name = entry.get::<DisplayName>()?.resolve(language);
        let position = entry.get::<Position>()?.0.clone();
        let facing = entry.get::<Facing>()?.0;
        let body = entry.get::<CharacterBody>()?;
        return Some((
            object_id,
            VisibleObjectBundle {
                spawn_packet: ServerPacket::ObjectPlayer {
                    info: ObjectPlayerInfo {
                        object_id,
                        name,
                        guild_name: String::new(),
                        guild_rank_name: String::new(),
                        name_colour_argb: -1,
                        class: body.class,
                        gender: body.gender,
                        level: body.level,
                        location: position,
                        direction: facing,
                        hair: 0,
                        light: 0,
                        weapon: 0,
                        weapon_effect: 0,
                        armour: 0,
                        poison: 0,
                        dead: false,
                        hidden: false,
                        effect: 0,
                        wing_effect: 0,
                        extra: false,
                        mount_type: 0,
                        riding_mount: false,
                        fishing: false,
                        transform_type: 0,
                        element_orb_effect: 0,
                        element_orb_level: 0,
                        element_orb_max: 0,
                        buffs: Vec::new(),
                        level_effects: 0,
                    },
                },
                health_packet: None,
            },
        ));
    }

    if entry.get::<Monster>().is_some() {
        let name = entry.get::<DisplayName>()?.resolve(language);
        let effect = crystal_monster_effect_for_name(&name);
        let position = entry.get::<Position>()?.0.clone();
        let facing = entry.get::<Facing>()?.0;
        let monster = entry.get::<MonsterAgent>()?;
        let ai_state = entry.get::<MonsterAiState>().copied().unwrap_or_default();
        let harvested = entry
            .get::<HarvestMonsterState>()
            .map(|state| state.harvested)
            .unwrap_or(false);
        if ai_state.hidden {
            return None;
        }
        let summoned = entry.get::<SummonedMonster>().copied();
        let tick = world.resource::<SimulationResources>().tick;
        let buffs = if monster.ai == 123
            && entry
                .get::<GeneralMeowMeowState>()
                .map(|state| state.shield_until_tick > tick)
                .unwrap_or(false)
        {
            vec![BUFF_GENERAL_MEOW_MEOW_SHIELD]
        } else {
            Vec::new()
        };
        let spawn_packet = ServerPacket::ObjectMonster {
            info: MonsterInfo {
                object_id,
                name,
                name_colour_argb: -1,
                location: position,
                image: monster.image,
                direction: facing,
                effect,
                ai: monster.ai,
                light: 0,
                dead: monster.dead,
                skeleton: harvested,
                poison: 0,
                hidden: false,
                shock_time: 0,
                binding_shot_center: false,
                extra: ai_state.extra || summoned.map(|value| value.visible_extra).unwrap_or(false),
                extra_byte: ai_state.extra_byte,
                master_object_id: summoned
                    .map(|summoned| summoned.summoner_object_id)
                    .unwrap_or(0),
                rarity: 0,
                buffs,
            },
        };

        return Some((
            object_id,
            VisibleObjectBundle {
                spawn_packet,
                health_packet: object_health_info_for_entity(world, entity, 0)
                    .map(|info| ServerPacket::ObjectHealth { info }),
            },
        ));
    }

    if entry.get::<Npc>().is_some() {
        let name = entry.get::<DisplayName>()?.resolve(language);
        let position = entry.get::<Position>()?.0.clone();
        let facing = entry.get::<Facing>()?.0;
        let npc = entry.get::<NpcAgent>()?;
        return Some((
            object_id,
            VisibleObjectBundle {
                spawn_packet: ServerPacket::ObjectNpc {
                    info: NpcInfo {
                        object_id,
                        name,
                        name_colour_argb: -1,
                        image: npc.image,
                        colour_argb: npc.colour_argb,
                        location: position,
                        direction: facing,
                        quest_ids: npc.quest_ids.clone(),
                    },
                },
                health_packet: None,
            },
        ));
    }

    if entry.get::<GroundDrop>().is_some() {
        let position = entry.get::<Position>()?.0.clone();
        let payload = entry.get::<DropPayload>()?;
        let spawn_packet = match &payload.loot {
            DropLoot::Gold(amount) => ServerPacket::ObjectGold {
                info: ObjectGoldInfo {
                    object_id,
                    gold: *amount,
                    location: position,
                },
            },
            DropLoot::InventoryItem {
                key,
                added_attack,
                added_defence,
                added_stats,
                socket_slots,
                ..
            } => ServerPacket::ObjectItem {
                info: ObjectItemInfo {
                    object_id,
                    name: entry.get::<DisplayName>()?.resolve(language),
                    name_colour_argb: crystal_item_name_colour_argb_for_drop(
                        key,
                        *added_attack,
                        *added_defence,
                        added_stats,
                        *socket_slots,
                    ),
                    location: position,
                    image: item_icon_for_key(key),
                    grade: crystal_item_grade_for_key(key),
                },
            },
        };

        return Some((
            object_id,
            VisibleObjectBundle {
                spawn_packet,
                health_packet: None,
            },
        ));
    }

    None
}

fn build_spawn_table(config: &SimulationConfig) -> MonsterSpawnTable {
    match config.monster_spawn_source {
        MonsterSpawnSource::StarterScenario => build_starter_spawn_table(config),
        MonsterSpawnSource::CrystalStarterRegion => {
            build_crystal_starter_region_spawn_table(config)
        }
    }
}

fn build_crystal_current_map_spawn_table(
    config: &SimulationConfig,
    map_file_name: &str,
) -> MonsterSpawnTable {
    let mut next_object_id = 60_000_u32;
    let rules = crystal_map_respawns_by_file_name(map_file_name)
        .map(|map| map.respawns)
        .unwrap_or_default()
        .into_iter()
        .take(96)
        .enumerate()
        .map(|(rule_index, respawn)| {
            let route = normalized_route_steps_for_map(config, map_file_name, &respawn.route);
            let slot_positions = spawn_positions_for_rule_on_map(
                config,
                map_file_name,
                &respawn.location,
                respawn.spread.min(16),
                usize::from(respawn.count.min(4)),
                rule_index,
            );
            let slots = slot_positions
                .into_iter()
                .map(|spawn_position| {
                    let object_id = next_object_id;
                    next_object_id += 1;
                    MonsterSpawnSlot {
                        entity: None,
                        object_id,
                        spawn_position,
                        next_respawn_tick: None,
                    }
                })
                .collect();

            MonsterSpawnRule {
                name: respawn.monster_name,
                image: respawn.monster_image,
                direction: respawn.direction,
                respawn_schedule: MonsterRespawnSchedule::CrystalMinutes {
                    delay_minutes: respawn.delay_minutes,
                    random_delay_minutes: respawn.random_delay_minutes,
                },
                ai: respawn.monster_ai,
                disposition: monster_disposition_for_ai(respawn.monster_ai),
                hostile_to_player: monster_targets_players(respawn.monster_ai),
                view_range: i32::from(respawn.monster_view_range),
                can_wander: crystal_respawn_can_wander(respawn.monster_hp),
                move_interval_ticks: crystal_speed_to_ticks(respawn.monster_move_speed),
                attack_interval_ticks: crystal_speed_to_ticks(respawn.monster_attack_speed),
                max_hp: respawn.monster_hp.max(1),
                route,
                slots,
            }
        })
        .collect();

    MonsterSpawnTable { rules }
}

fn build_starter_spawn_table(config: &SimulationConfig) -> MonsterSpawnTable {
    let rules = starter_server_data()
        .monster_spawns
        .iter()
        .enumerate()
        .map(|(rule_index, spawn)| {
            let slot_positions = spawn_positions_for_rule(
                config,
                &spawn.position,
                spawn.spread,
                usize::from(spawn.count),
                rule_index,
            );
            let slots = slot_positions
                .into_iter()
                .enumerate()
                .map(|(slot_index, spawn_position)| MonsterSpawnSlot {
                    entity: None,
                    object_id: spawn.object_id + u32::try_from(slot_index).expect("slot id fits"),
                    spawn_position,
                    next_respawn_tick: None,
                })
                .collect();

            MonsterSpawnRule {
                name: spawn.name.clone(),
                image: spawn.image,
                direction: spawn.direction,
                respawn_schedule: MonsterRespawnSchedule::FixedTicks {
                    delay_ticks: spawn.respawn_delay_ticks,
                    random_delay_ticks: spawn.random_delay_ticks,
                },
                ai: 0,
                disposition: if spawn.can_wander {
                    WorldEntityDisposition::Hostile
                } else {
                    WorldEntityDisposition::Neutral
                },
                hostile_to_player: spawn.can_wander,
                view_range: if spawn.can_wander { 4 } else { 0 },
                can_wander: spawn.can_wander,
                move_interval_ticks: 1,
                attack_interval_ticks: 1,
                max_hp: spawn.max_hp,
                route: Vec::new(),
                slots,
            }
        })
        .collect();

    MonsterSpawnTable { rules }
}

