fn parse_runtime_map_collision_fixed(
    map_file_name: &str,
    bytes: &[u8],
    start_offset: usize,
    stride: usize,
    _map_type: u8,
) -> Option<StarterMapCollision> {
    let width = u16::try_from(read_i16_le(bytes, 0)?).ok()?;
    let height = u16::try_from(read_i16_le(bytes, 2)?).ok()?;
    let mut offset = start_offset;
    let mut blocked_cells = Vec::new();
    let mut doors = Vec::new();

    for x in 0..i32::from(width) {
        for y in 0..i32::from(height) {
            let high_wall = (read_i16_le(bytes, offset)? & i16::MIN) != 0;
            let low_wall = (read_i16_le(bytes, offset + 2)? & i16::MIN) != 0;
            let no_floor = (read_i16_le(bytes, offset + 4)? & i16::MIN) != 0;
            let door_offset = match stride {
                12 => offset + 8,
                14 => offset + 6,
                36 => offset + 6,
                _ => offset + 6,
            };
            let door = *bytes.get(door_offset)?;
            if high_wall || low_wall || no_floor {
                blocked_cells.push(BlockedMapCellTemplate {
                    x,
                    y,
                    attribute: if low_wall {
                        MapCellAttribute::LowWall
                    } else {
                        MapCellAttribute::HighWall
                    },
                });
            }
            if door > 0 {
                doors.push(DoorMapCellTemplate {
                    x,
                    y,
                    index: door & 0x7F,
                    closed: true,
                });
            }
            offset += stride;
        }
    }

    Some(build_runtime_collision_output(
        map_file_name,
        width,
        height,
        blocked_cells,
        doors,
    ))
}

fn build_runtime_collision_output(
    map_file_name: &str,
    map_width: u16,
    map_height: u16,
    blocked_cells: Vec<BlockedMapCellTemplate>,
    doors: Vec<DoorMapCellTemplate>,
) -> StarterMapCollision {
    StarterMapCollision {
        map_file_name: format!("{}.map", normalize_map_file_name(map_file_name)),
        map_width,
        map_height,
        region_bounds: MapBounds {
            min_x: 0,
            max_x: i32::from(map_width.saturating_sub(1)),
            min_y: 0,
            max_y: i32::from(map_height.saturating_sub(1)),
        },
        play_bounds: MapBounds {
            min_x: 0,
            max_x: i32::from(map_width.saturating_sub(1)),
            min_y: 0,
            max_y: i32::from(map_height.saturating_sub(1)),
        },
        blocked_cells,
        doors,
    }
}

fn read_i16_le(bytes: &[u8], offset: usize) -> Option<i16> {
    let slice = bytes.get(offset..offset + 2)?;
    Some(i16::from_le_bytes([slice[0], slice[1]]))
}

fn read_i32_le(bytes: &[u8], offset: usize) -> Option<i32> {
    let slice = bytes.get(offset..offset + 4)?;
    Some(i32::from_le_bytes([slice[0], slice[1], slice[2], slice[3]]))
}

fn active_scene_view(world: &World) -> Option<mir2_game_data::SceneView> {
    let resources = world.resource::<SimulationResources>();
    let Some(player) = player_entity(world) else {
        return Some(resources.config.scene_view.clone());
    };
    let position = entity_position(world, player)?;
    Some(mir2_game_data::SceneView {
        center: position,
        width: resources.config.scene_view.width,
        height: resources.config.scene_view.height,
    })
}

fn point_visible(scene_view: Option<&mir2_game_data::SceneView>, point: &Point) -> bool {
    let Some(scene_view) = scene_view else {
        return true;
    };
    let half_width = i32::from(scene_view.width / 2);
    let half_height = i32::from(scene_view.height / 2);
    point.x >= scene_view.center.x - half_width
        && point.x <= scene_view.center.x + half_width
        && point.y >= scene_view.center.y - half_height
        && point.y <= scene_view.center.y + half_height
}

fn rect_visible(
    scene_view: Option<&mir2_game_data::SceneView>,
    x: i32,
    y: i32,
    width: u16,
    height: u16,
) -> bool {
    let Some(scene_view) = scene_view else {
        return true;
    };
    let half_width = i32::from(scene_view.width / 2);
    let half_height = i32::from(scene_view.height / 2);
    let view_min_x = scene_view.center.x - half_width;
    let view_max_x = scene_view.center.x + half_width;
    let view_min_y = scene_view.center.y - half_height;
    let view_max_y = scene_view.center.y + half_height;
    let rect_max_x = x + i32::from(width) - 1;
    let rect_max_y = y + i32::from(height) - 1;

    x <= view_max_x && rect_max_x >= view_min_x && y <= view_max_y && rect_max_y >= view_min_y
}

fn filter_terrain_patches(
    world: &World,
    scene_view: Option<&mir2_game_data::SceneView>,
) -> Vec<mir2_game_data::TerrainPatchTemplate> {
    world
        .resource::<SimulationResources>()
        .config
        .terrain_patches
        .iter()
        .filter(|patch| rect_visible(scene_view, patch.x, patch.y, patch.width, patch.height))
        .cloned()
        .collect()
}

fn filter_decor_objects(
    world: &World,
    scene_view: Option<&mir2_game_data::SceneView>,
) -> Vec<mir2_game_data::DecorObjectTemplate> {
    world
        .resource::<SimulationResources>()
        .config
        .decor_objects
        .iter()
        .filter(|decor| {
            point_visible(
                scene_view,
                &Point {
                    x: decor.x,
                    y: decor.y,
                },
            )
        })
        .cloned()
        .collect()
}

fn current_weight(resources: &SimulationResources) -> u16 {
    let total = resources
        .inventory_items
        .iter()
        .chain(resources.belt_items.iter())
        .map(ItemState::total_weight)
        .sum::<u32>();
    total.min(u32::from(u16::MAX)) as u16
}

fn free_bag_slots(resources: &SimulationResources) -> u16 {
    let used = resources
        .inventory_items
        .iter()
        .filter(|item| matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2))
        .count() as u16;
    80u16.saturating_sub(used)
}

fn item_containers_stack_together(existing: ItemContainer, target: ItemContainer) -> bool {
    match (existing, target) {
        (ItemContainer::Bag1, ItemContainer::Bag2) | (ItemContainer::Bag2, ItemContainer::Bag1) => {
            true
        }
        _ => existing == target,
    }
}

fn empty_slots_for_inventory_container(
    items: &[ItemState],
    container: ItemContainer,
) -> Vec<(ItemContainer, u8)> {
    match container {
        ItemContainer::Bag1 | ItemContainer::Bag2 => [ItemContainer::Bag1, ItemContainer::Bag2]
            .into_iter()
            .flat_map(|container| {
                (0..40).filter_map(move |slot| {
                    let slot = u8::try_from(slot).expect("bag slot count should fit in u8");
                    let occupied = items
                        .iter()
                        .any(|item| item.container == container && item.slot == slot);
                    (!occupied).then_some((container, slot))
                })
            })
            .collect(),
        other => {
            let max_slots = match other {
                ItemContainer::Quest => 40,
                ItemContainer::Storage => BASE_STORAGE_SLOTS,
                ItemContainer::Belt => 6,
                ItemContainer::Bag1 | ItemContainer::Bag2 => unreachable!(),
            };
            (0..max_slots)
                .filter_map(|slot| {
                    let slot = u8::try_from(slot).expect("slot count should fit in u8");
                    let occupied = items
                        .iter()
                        .any(|item| item.container == other && item.slot == slot);
                    (!occupied).then_some((other, slot))
                })
                .collect()
        }
    }
}

fn find_empty_inventory_item_slot(
    items: &[ItemState],
    container: ItemContainer,
) -> Option<(ItemContainer, u8)> {
    empty_slots_for_inventory_container(items, container)
        .into_iter()
        .next()
}

fn additional_slots_needed_for_item_quantity(
    resources: &SimulationResources,
    container: ItemContainer,
    key: &str,
    quantity: u32,
) -> u32 {
    let max_stack = crystal_stack_size_for_item_key(key);
    let mut remaining = quantity.max(1);
    if max_stack > 1 {
        if matches!(container, ItemContainer::Bag1 | ItemContainer::Bag2) {
            for item in resources
                .belt_items
                .iter()
                .filter(|item| item.key == key && item.quantity < max_stack)
            {
                let available = max_stack.saturating_sub(item.quantity);
                remaining = remaining.saturating_sub(available);
                if remaining == 0 {
                    return 0;
                }
            }
        }
        for item in resources.inventory_items.iter().filter(|item| {
            item.key == key && item_containers_stack_together(item.container, container)
        }) {
            let available = max_stack.saturating_sub(item.quantity);
            remaining = remaining.saturating_sub(available);
            if remaining == 0 {
                return 0;
            }
        }
    }

    remaining.div_ceil(max_stack)
}

fn can_gain_item_quantity(
    resources: &SimulationResources,
    container: ItemContainer,
    key: &str,
    quantity: u32,
) -> bool {
    let needed_slots =
        additional_slots_needed_for_item_quantity(resources, container, key, quantity);
    let free_slots = crystal_empty_add_item_slots(resources, container, key).len();
    needed_slots <= u32::try_from(free_slots).unwrap_or(u32::MAX)
}

fn crystal_empty_add_item_slots(
    resources: &SimulationResources,
    container: ItemContainer,
    key: &str,
) -> Vec<(ItemContainer, u8)> {
    let mut slots = Vec::new();
    match container {
        ItemContainer::Bag1 | ItemContainer::Bag2 => {
            if let Some((start, end)) = crystal_belt_slot_range_for_item_key(key) {
                slots.extend((start..end).filter_map(|slot| {
                    let occupied = resources
                        .belt_items
                        .iter()
                        .any(|item| item.container == ItemContainer::Belt && item.slot == slot);
                    (!occupied).then_some((ItemContainer::Belt, slot))
                }));
            }
            slots.extend(empty_slots_for_inventory_container(
                &resources.inventory_items,
                container,
            ));
        }
        ItemContainer::Belt => {
            slots.extend(empty_slots_for_inventory_container(
                &resources.belt_items,
                container,
            ));
        }
        other => {
            slots.extend(empty_slots_for_inventory_container(
                &resources.inventory_items,
                other,
            ));
        }
    }
    slots
}

fn build_interaction_hints(resources: &SimulationResources) -> Vec<String> {
    let language = resources.language;
    let mut hints = vec![
        localized_text_or_fallback(
            language,
            "custom.interaction.primaryControls",
            "Left click walks, right click runs, and clicking a target focuses it.",
        ),
        localized_text_or_fallback(
            language,
            "custom.interaction.targetHelp",
            "Target monsters or NPCs in-scene, then attack or talk from range 1.",
        ),
    ];

    if let Some(quest) = resources.quests.first() {
        hints.push(format_localized_text(
            language,
            "sim.questHint",
            [quest.tracker(language)],
        ));
    }

    if resources.active_npc_dialog.is_some() {
        hints.push(localized_text_or_fallback(
            language,
            "custom.interaction.npcDialogLive",
            "NPC dialog is live; review it, then continue field progression.",
        ));
    }

    hints
}

