fn monster_ai_state_for_ai(ai: u8) -> MonsterAiState {
    match ai {
        5 | 14 => MonsterAiState {
            hidden: true,
            extra: false,
            extra_byte: 0,
            mode: false,
            next_state_tick: 0,
        },
        47 => MonsterAiState {
            hidden: true,
            extra: false,
            extra_byte: 0,
            mode: true,
            next_state_tick: 0,
        },
        48 => MonsterAiState {
            hidden: false,
            extra: false,
            extra_byte: 0,
            mode: true,
            next_state_tick: 0,
        },
        15 | 16 | 173 | 174 => MonsterAiState {
            hidden: false,
            extra: true,
            extra_byte: 0,
            mode: false,
            next_state_tick: 0,
        },
        17 => MonsterAiState {
            hidden: false,
            extra: true,
            extra_byte: ZUMA_TAURUS_STAGE_COUNT,
            mode: false,
            next_state_tick: 0,
        },
        18 => MonsterAiState {
            hidden: true,
            extra: false,
            extra_byte: 0,
            mode: false,
            next_state_tick: 0,
        },
        24 | 124 | 125 => MonsterAiState {
            hidden: true,
            extra: false,
            extra_byte: 0,
            mode: false,
            next_state_tick: 0,
        },
        30 => MonsterAiState {
            hidden: false,
            extra: false,
            extra_byte: BONE_LORD_STAGE_COUNT,
            mode: false,
            next_state_tick: 0,
        },
        38 => MonsterAiState {
            hidden: false,
            extra: true,
            extra_byte: 0,
            mode: false,
            next_state_tick: 0,
        },
        97 => MonsterAiState {
            hidden: false,
            extra: true,
            extra_byte: 0,
            mode: false,
            next_state_tick: 0,
        },
        _ => MonsterAiState::default(),
    }
}

fn initial_monster_ai_state(ai: u8, tick: u64) -> MonsterAiState {
    let mut state = monster_ai_state_for_ai(ai);
    if ai == 40 {
        state.next_state_tick = tick + BOMB_SPIDER_EXPLOSION_LIFETIME_TICKS;
    }
    if ai == 47 {
        state.next_state_tick = tick + 2;
    }
    if ai == 34 {
        state.next_state_tick = tick + FROST_TIGER_SIT_DOWN_MAX_DELAY_TICKS;
    }
    if ai == 99 {
        state.next_state_tick = tick + HELL_BOMB_EXPLOSION_LIFETIME_TICKS;
    }
    state
}

fn initial_monster_ai_state_for_object(ai: u8, tick: u64, object_id: u32) -> MonsterAiState {
    let mut state = initial_monster_ai_state(ai, tick);
    if ai == 2 {
        state.mode = deterministic_chance_roll(tick, object_id, 2, 7);
    }
    state
}

fn initial_harvest_monster_state(ai: u8) -> Option<HarvestMonsterState> {
    let remaining_skin_count = match ai {
        2 => DEER_SKIN_COUNT,
        1 | 7 | 9 | 28 | 35 => HARVEST_MONSTER_SKIN_COUNT,
        _ => return None,
    };
    Some(HarvestMonsterState {
        remaining_skin_count,
        drops_ready: false,
        harvested: false,
    })
}

fn initial_wooma_taurus_state(
    tick: u64,
    base_move_interval_ticks: u64,
    base_attack_interval_ticks: u64,
) -> WoomaTaurusState {
    WoomaTaurusState {
        stage: WOOMA_TAURUS_STAGE_COUNT,
        mad_until_tick: 0,
        next_teleport_tick: tick + WOOMA_TAURUS_TELEPORT_DELAY_TICKS,
        base_move_interval_ticks: base_move_interval_ticks.max(1),
        base_attack_interval_ticks: base_attack_interval_ticks.max(1),
    }
}

fn initial_general_meow_meow_state(tick: u64) -> GeneralMeowMeowState {
    GeneralMeowMeowState {
        shield_until_tick: 0,
        next_thunder_tick: 0,
        next_slave_spawn_tick: tick + GENERAL_MEOW_MEOW_SLAVE_SPAWN_INTERVAL_TICKS,
    }
}

fn initial_yimoogi_state(tick: u64) -> YimoogiState {
    YimoogiState {
        spawn_tick: tick + YIMOOGI_CHILD_SPAWN_DELAY_TICKS,
        child_spawned: false,
        is_child: false,
        final_teleport: false,
        sister_object_id: None,
    }
}

fn monster_disposition_for_ai(ai: u8) -> WorldEntityDisposition {
    match ai {
        1 | 2 | 3 | 6 | 34 | 56 | 57 | 58 | 113 => WorldEntityDisposition::Neutral,
        _ => WorldEntityDisposition::Hostile,
    }
}

fn monster_targets_players(ai: u8) -> bool {
    !matches!(ai, 1 | 2 | 3 | 6 | 34 | 56 | 57 | 58 | 113)
}

fn monster_uses_zuma_stone_state(ai: u8) -> bool {
    matches!(ai, 15 | 16 | 17 | 173 | 174)
}

fn monster_is_stoned_zuma(agent: &MonsterAgent, ai_state: &MonsterAiState) -> bool {
    monster_uses_zuma_stone_state(agent.ai) && ai_state.extra
}

fn queue_pending_monster_spawn(world: &mut World, action: PendingMonsterSpawnAction) {
    world
        .resource_mut::<SimulationResources>()
        .pending_monster_spawns
        .push(action);
}

fn allocate_runtime_monster_object_id(world: &mut World) -> u32 {
    let mut resources = world.resource_mut::<SimulationResources>();
    let object_id = resources.next_runtime_monster_object_id;
    resources.next_runtime_monster_object_id += 1;
    object_id
}

fn active_summoned_monster_count(world: &World, summoner_object_id: u32) -> usize {
    #[allow(deprecated)]
    world
        .iter_entities()
        .filter(|entity| {
            entity
                .get::<SummonedMonster>()
                .map(|summoned| summoned.summoner_object_id == summoner_object_id)
                .unwrap_or(false)
                && entity
                    .get::<MonsterAgent>()
                    .map(|agent| !agent.dead)
                    .unwrap_or(false)
        })
        .count()
}

fn active_summoned_monster_count_by_ai(world: &World, summoner_object_id: u32, ai: u8) -> usize {
    #[allow(deprecated)]
    world
        .iter_entities()
        .filter(|entity| {
            entity
                .get::<SummonedMonster>()
                .map(|summoned| summoned.summoner_object_id == summoner_object_id)
                .unwrap_or(false)
                && entity
                    .get::<MonsterAgent>()
                    .map(|agent| !agent.dead && agent.ai == ai)
                    .unwrap_or(false)
        })
        .count()
}

#[allow(deprecated)]
fn summoned_owner_state(world: &World, owner_object_id: u32) -> Option<(Point, bool)> {
    world.iter_entities().find_map(|entity| {
        let object_id = entity.get::<ObjectId>()?;
        if object_id.0 != owner_object_id {
            return None;
        }

        let position = entity.get::<Position>()?.0.clone();
        let dead = entity
            .get::<MonsterAgent>()
            .map(|agent| agent.dead)
            .unwrap_or(false);
        Some((position, dead))
    })
}

fn summoned_monster_defaults(
    summoner_ai: u8,
    template: &CrystalRespawnTemplate,
) -> SummonedMonster {
    let mut summoned = SummonedMonster {
        summoner_object_id: 0,
        visible_extra: false,
        expire_tick: None,
        require_summoner_within: None,
        despawn_tick_after_death: None,
        totem_master_object_id: None,
        max_minions: None,
    };

    match (summoner_ai, template.monster_ai) {
        (12, _) | (39, _) => {}
        (62, 63) => {
            summoned.visible_extra = true;
            summoned.require_summoner_within = Some(15);
            summoned.totem_master_object_id = Some(0);
        }
        _ => {}
    }

    summoned
}

#[allow(deprecated)]
fn runtime_position_exists(world: &World, point: &Point) -> bool {
    world.iter_entities().any(|entity| {
        entity
            .get::<Position>()
            .map(|position| position.0 == *point)
            .unwrap_or(false)
    })
}

fn spawn_runtime_monster(
    world: &mut World,
    template: &CrystalRespawnTemplate,
    position: Point,
    direction: MirDirection,
    target_entity: Option<Entity>,
    summoned: Option<SummonedMonster>,
    hostile_to_player_override: Option<bool>,
    disposition_override: Option<WorldEntityDisposition>,
    activation_delay_ticks: u64,
) -> Option<Entity> {
    let (config, current_map_file_name) = {
        let resources = world.resource::<SimulationResources>();
        (
            resources.config.clone(),
            resources.current_map.file_name.clone(),
        )
    };
    let valid_spawn_point =
        is_static_spawnable_point_on_map(&config, &current_map_file_name, &position)
            || (summoned.is_some() && runtime_position_exists(world, &position));
    if !valid_spawn_point {
        return None;
    }

    let tick = world.resource::<SimulationResources>().tick;
    let route = normalized_route_steps(&config, &template.route);
    let mut agent = MonsterAgent {
        image: template.monster_image,
        dead: false,
        patrol_origin: position.clone(),
        ai: template.monster_ai,
        disposition: disposition_override
            .unwrap_or_else(|| monster_disposition_for_ai(template.monster_ai)),
        hostile_to_player: hostile_to_player_override
            .unwrap_or_else(|| monster_targets_players(template.monster_ai)),
        tracking_player: false,
        view_range: i32::from(template.monster_view_range),
        can_wander: crystal_respawn_can_wander(template.monster_hp),
        move_interval_ticks: crystal_speed_to_ticks(template.monster_move_speed),
        attack_interval_ticks: crystal_speed_to_ticks(template.monster_attack_speed),
        next_move_tick: tick + activation_delay_ticks,
        next_attack_tick: tick + activation_delay_ticks,
        route,
        route_index: 0,
        route_waiting: false,
        next_route_tick: tick + activation_delay_ticks,
    };
    if target_entity.is_some() && agent.hostile_to_player {
        agent.tracking_player = true;
    }

    let object_id = allocate_runtime_monster_object_id(world);
    let facing = if template.monster_ai == 3 {
        MirDirection::Up
    } else {
        direction
    };
    let mut entity = world.spawn((
        WorldObject,
        Monster,
        ObjectId(object_id),
        DisplayName::literal(template.monster_name.clone()),
        Position(position.clone()),
        Facing(facing),
        agent,
        initial_monster_ai_state_for_object(
            template.monster_ai,
            tick + activation_delay_ticks,
            object_id,
        ),
        MonsterVitals {
            hp: template.monster_hp.max(1),
            max_hp: template.monster_hp.max(1),
        },
    ));
    if let Some(summoned) = summoned {
        entity.insert(summoned);
    }
    if template.monster_ai == 123 {
        entity.insert(initial_general_meow_meow_state(
            tick + activation_delay_ticks,
        ));
    }
    if template.monster_ai == 36 {
        entity.insert(initial_yimoogi_state(tick + activation_delay_ticks));
    }
    Some(entity.id())
}

fn resolve_pending_monster_spawns(world: &mut World, current_tick: u64) {
    let due_actions = {
        let mut resources = world.resource_mut::<SimulationResources>();
        let mut due = Vec::new();
        let mut pending = Vec::with_capacity(resources.pending_monster_spawns.len());

        for action in resources.pending_monster_spawns.drain(..) {
            if action.due_tick <= current_tick {
                due.push(action);
            } else {
                pending.push(action);
            }
        }

        resources.pending_monster_spawns = pending;
        due
    };

    for action in due_actions {
        let Ok(summoner_entry) = world.get_entity(action.summoner_entity) else {
            continue;
        };
        let Some(summoner_position) = summoner_entry
            .get::<Position>()
            .map(|value| value.0.clone())
        else {
            continue;
        };
        let Some(summoner_object_id) = summoner_entry.get::<ObjectId>().map(|value| value.0) else {
            continue;
        };
        let summoner_ai = summoner_entry
            .get::<MonsterAgent>()
            .map(|agent| agent.ai)
            .unwrap_or_default();
        let summoner_dead = summoner_entry
            .get::<MonsterAgent>()
            .map(|agent| agent.dead)
            .unwrap_or(false);

        let spawns_regular_monster =
            matches!(summoner_ai, 119 | 128) && action.summon_metadata.is_none();
        let summon_cap = action
            .summon_metadata
            .and_then(|summoned| summoned.max_minions)
            .unwrap_or(20);
        if (!spawns_regular_monster && summoner_dead)
            || (!spawns_regular_monster
                && active_summoned_monster_count(world, summoner_object_id) >= summon_cap)
        {
            continue;
        }

        let target_entity = action.target_entity.filter(|entity| {
            world
                .get_entity(*entity)
                .map(|entry| {
                    entry.get::<PlayerVitals>().is_some()
                        || entry
                            .get::<MonsterAgent>()
                            .map(|agent| !agent.dead)
                            .unwrap_or(false)
                })
                .unwrap_or(false)
        });

        let spawn_position = if action.template.location == (Point { x: 0, y: 0 }) {
            summoner_position
        } else {
            action.template.location.clone()
        };

        let summon_metadata = if spawns_regular_monster {
            None
        } else {
            let mut summon_metadata = action
                .summon_metadata
                .unwrap_or_else(|| summoned_monster_defaults(summoner_ai, &action.template));
            summon_metadata.summoner_object_id = summoner_object_id;
            if summon_metadata.totem_master_object_id.is_some() {
                summon_metadata.totem_master_object_id = Some(summoner_object_id);
            }
            Some(summon_metadata)
        };

        let _ = spawn_runtime_monster(
            world,
            &action.template,
            spawn_position,
            MirDirection::Up,
            target_entity,
            summon_metadata,
            action.hostile_to_player_override,
            action.hostile_to_player_override.map(|hostile| {
                if hostile {
                    WorldEntityDisposition::Hostile
                } else {
                    WorldEntityDisposition::Friendly
                }
            }),
            1,
        );
    }
}

fn crystal_speed_to_ticks(speed_ms: u16) -> u64 {
    u64::from(speed_ms.max(400)).div_ceil(1_000)
}

fn respawn_tick_for_schedule(
    schedule: &MonsterRespawnSchedule,
    current_tick: u64,
    rule_index: usize,
    slot_index: usize,
) -> u64 {
    match schedule {
        MonsterRespawnSchedule::FixedTicks {
            delay_ticks,
            random_delay_ticks,
        } => {
            let extra_delay = if *random_delay_ticks == 0 {
                0
            } else {
                deterministic_roll(current_tick, rule_index, slot_index, random_delay_ticks + 1)
            };
            current_tick + delay_ticks + extra_delay
        }
        MonsterRespawnSchedule::CrystalMinutes {
            delay_minutes,
            random_delay_minutes,
        } => {
            const SIMULATION_TICKS_PER_CRYSTAL_MINUTE: u64 = 60;
            let delay_minutes = i64::from(*delay_minutes);
            let random_delay_minutes = i64::from(*random_delay_minutes);
            let roll = if random_delay_minutes == 0 {
                0
            } else {
                deterministic_roll(
                    current_tick,
                    rule_index,
                    slot_index,
                    u64::try_from(random_delay_minutes * 2)
                        .expect("random delay minutes window should fit u64"),
                ) as i64
            };
            let scheduled_minutes = (delay_minutes - random_delay_minutes + roll).max(1) as u64;
            current_tick + scheduled_minutes * SIMULATION_TICKS_PER_CRYSTAL_MINUTE
        }
    }
}

fn deterministic_roll(current_tick: u64, rule_index: usize, slot_index: usize, modulo: u64) -> u64 {
    if modulo == 0 {
        return 0;
    }

    let salt = current_tick
        .wrapping_mul(1_103_515_245)
        .wrapping_add((rule_index as u64).wrapping_mul(97_651))
        .wrapping_add((slot_index as u64).wrapping_mul(12_347))
        .wrapping_add(0x9E37_79B9);
    salt % modulo
}

fn clamp_to_map_region(world: &World, point: Point) -> Point {
    let resources = world.resource::<SimulationResources>();
    let bounds = resources.map_region_bounds;

    Point {
        x: point.x.clamp(bounds.min_x, bounds.max_x),
        y: point.y.clamp(bounds.min_y, bounds.max_y),
    }
}

fn step_player(world: &mut World, amount: i32) -> bool {
    if player_is_paralyzed(world) {
        return false;
    }

    if let Some(player) = player_entity(world) {
        let (direction, position) = {
            let entity = world.entity(player);
            (
                entity.get::<Facing>().expect("player facing").0,
                entity.get::<Position>().expect("player position").0.clone(),
            )
        };
        if let Some(destination) =
            directional_destination(world, &position, direction, amount, Some(player))
        {
            world.entity_mut(player).insert(Position(destination));
            return true;
        }
    }

    false
}

fn player_is_paralyzed(world: &World) -> bool {
    let tick = world.resource::<SimulationResources>().tick;
    world
        .resource::<SimulationResources>()
        .buffs
        .iter()
        .any(|buff| buff.key == CAVE_MAGGOT_PARALYSIS_BUFF_KEY && buff.expires_at_tick > tick)
}

fn persist_monster_runtime_state(
    world: &mut World,
    entity: Entity,
    original_agent: &MonsterAgent,
    agent: &MonsterAgent,
    original_ai_state: MonsterAiState,
    ai_state: MonsterAiState,
) {
    if agent == original_agent && ai_state == original_ai_state {
        return;
    }

    let mut entry = world.entity_mut(entity);
    if agent != original_agent {
        entry.insert(agent.clone());
    }
    if ai_state != original_ai_state {
        entry.insert(ai_state);
    }
}

fn update_special_monster_state(
    world: &mut World,
    entity: Entity,
    agent: &mut MonsterAgent,
    ai_state: &mut MonsterAiState,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if update_summoned_monster_state(world, entity, agent, position, tick, packets) {
        return true;
    }

    if agent.ai == 2
        && update_deer_run_away_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        )
    {
        return true;
    }

    if agent.ai == 50
        && update_great_fox_spirit_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        )
    {
        return true;
    }

    if agent.ai == 17 {
        update_zuma_taurus_stage_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
        );
    }

    if agent.ai == 49
        && update_thunder_element_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        )
    {
        return true;
    }

    if agent.ai == 36
        && update_yimoogi_state(
            world,
            entity,
            agent,
            position,
            player_position,
            tick,
            packets,
        )
    {
        return true;
    }

    if agent.ai == 123 {
        update_general_meow_meow_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        );
    }

    if agent.ai == 54
        && update_dragon_statue_sleep_state(world, entity, agent, ai_state, tick, packets)
    {
        return true;
    }

    if agent.ai == 34
        && update_frost_tiger_sitting_state(world, entity, agent, ai_state, position, tick, packets)
    {
        return true;
    }

    if agent.ai == 8
        && update_axe_skeleton_fear_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        )
    {
        return true;
    }

    if matches!(agent.ai, 45 | 46)
        && update_foxman_fear_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        )
    {
        return true;
    }

    if agent.ai == 38
        && update_holy_deva_fear_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        )
    {
        return true;
    }

    if agent.ai == 186
        && update_kirin_ice_thrust_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        )
    {
        return true;
    }

    match agent.ai {
        14 => update_evil_centipede_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        ),
        5 => update_cannibal_plant_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        ),
        11 => update_wooma_taurus_state(world, entity, agent, position, tick, packets),
        40 => update_bomb_spider_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        ),
        47 => update_trap_rock_state(
            world,
            entity,
            agent,
            ai_state,
            player_position,
            tick,
            packets,
        ),
        15 | 16 | 17 | 173 | 174 => update_zuma_monster_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        ),
        18 => update_shinsu_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        ),
        24 => update_dig_out_zombie_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        ),
        124 | 125 => update_armadillo_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        ),
        25 => update_reviving_zombie_state(world, entity, agent, ai_state, tick, packets),
        30 => update_bone_lord_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        ),
        42 => update_yin_devil_node_state(agent, tick),
        60 => update_vampire_spider_state(world, entity, agent, position, tick, packets),
        61 => update_spitting_toad_state(world, entity, agent, position, tick, packets),
        62 => update_snake_totem_state(world, entity, agent, position, tick, packets),
        131 => update_tucson_general_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        ),
        98 => update_hell_lord_state(
            world,
            entity,
            agent,
            ai_state,
            position,
            player_position,
            tick,
            packets,
        ),
        99 => update_hell_bomb_state(world, entity, agent, ai_state, position, tick, packets),
        255 => update_stone_trap_state(world, entity, agent, position, tick),
        _ => false,
    }
}

fn update_great_fox_spirit_state(
    world: &mut World,
    entity: Entity,
    agent: &MonsterAgent,
    ai_state: &mut MonsterAiState,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if !ai_state.mode {
        set_guardian_rocks_active_near(world, position, true);
        ai_state.mode = true;
        world.entity_mut(entity).insert(*ai_state);
    }

    let Some(vitals) = world.entity(entity).get::<MonsterVitals>() else {
        return false;
    };
    if vitals.max_hp < 4 {
        return false;
    }

    let stage_size = (vitals.max_hp / 4).max(1);
    let stage = (4 - (vitals.hp.max(0) / stage_size)).clamp(0, 4) as u8;
    if stage > ai_state.extra_byte {
        ai_state.extra_byte = stage;
        world.entity_mut(entity).insert(*ai_state);
        if let Some((_, bundle)) =
            visible_object_bundle_for_entity(world, entity, current_language(world))
        {
            if matches!(bundle.spawn_packet, ServerPacket::ObjectMonster { .. }) {
                packets.push(bundle.spawn_packet);
            }
        }
    }

    try_great_fox_spirit_recall(
        world,
        entity,
        agent,
        ai_state,
        position,
        player_position,
        tick,
        packets,
    )
}

fn try_great_fox_spirit_recall(
    world: &mut World,
    entity: Entity,
    agent: &MonsterAgent,
    ai_state: &mut MonsterAiState,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if agent.dead || !monster_can_attack(agent, ai_state) {
        return false;
    }
    if tile_distance(position, player_position) <= 3
        || tile_distance(position, player_position) > 30
        || ai_state.next_state_tick > tick
        || (!agent.tracking_player && !agent.hostile_to_player)
    {
        return false;
    }

    let Some(attacker_id) = entity_object_id(world, entity) else {
        return false;
    };
    if !deterministic_chance_roll(tick, attacker_id, 502, 10) {
        return false;
    }

    ai_state.next_state_tick = tick + GREAT_FOX_SPIRIT_RECALL_COOLDOWN_TICKS;
    world.entity_mut(entity).insert(*ai_state);
    if deterministic_chance_roll(tick, attacker_id, 503, 4) {
        return false;
    }

    let Some(player) = player_entity(world) else {
        return false;
    };
    let Some(player_object_id) = current_player_object_id(world) else {
        return false;
    };
    let direction = rotated_direction(
        MirDirection::Up,
        deterministic_roll(tick, entity.index() as usize, 50, 7) as i32,
    );
    let candidate = offset_point(position, direction, 1);
    let destination = if can_occupy(world, candidate.clone(), Some(player)) {
        candidate
    } else {
        position.clone()
    };
    let facing = entity_facing(world, player).unwrap_or(MirDirection::Down);

    world
        .entity_mut(player)
        .insert((Position(destination.clone()), Facing(facing)));
    packets.push(ServerPacket::ObjectTeleportOut {
        object_id: player_object_id,
        effect_type: GREAT_FOX_SPIRIT_RECALL_TELEPORT_EFFECT,
    });
    packets.push(ServerPacket::ObjectWalk {
        movement: ObjectMovement {
            object_id: player_object_id,
            position: destination,
            direction: facing,
        },
    });
    packets.push(ServerPacket::ObjectTeleportIn {
        object_id: player_object_id,
        effect_type: GREAT_FOX_SPIRIT_RECALL_TELEPORT_EFFECT,
    });
    true
}

#[allow(deprecated)]
fn set_guardian_rocks_active_near(world: &mut World, origin: &Point, active: bool) -> bool {
    let rocks = world
        .iter_entities()
        .filter_map(|entity| {
            let agent = entity.get::<MonsterAgent>()?;
            let position = entity.get::<Position>()?;
            (agent.ai == 48 && tile_distance(origin, &position.0) <= 20).then_some(entity.id())
        })
        .collect::<Vec<_>>();

    let mut changed = false;
    for rock in rocks {
        let mut ai_state = world
            .entity(rock)
            .get::<MonsterAiState>()
            .copied()
            .unwrap_or_default();
        if ai_state.mode != active {
            ai_state.mode = active;
            world.entity_mut(rock).insert(ai_state);
            changed = true;
        }
    }

    changed
}

fn update_thunder_element_state(
    world: &mut World,
    entity: Entity,
    agent: &mut MonsterAgent,
    ai_state: &MonsterAiState,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if agent.dead || !monster_can_attack(agent, ai_state) {
        return false;
    }
    if !monster_in_attack_range(agent, position, player_position) {
        return false;
    }
    if !agent.tracking_player
        && !(agent.hostile_to_player
            && tile_distance(position, player_position) <= agent.view_range.max(1))
    {
        return false;
    }
    if tick < agent.next_attack_tick {
        return false;
    }

    let Some(attacker_id) = entity_object_id(world, entity) else {
        return false;
    };
    let monster_name = entity_name(world, entity).unwrap_or_else(|| "ThunderElement".to_string());
    let mut attack_position = position.clone();
    if deterministic_chance_roll(tick, attacker_id, 490, 3) {
        let target_x_offset = deterministic_roll(tick, entity.index() as usize, 491, 3) as i32 - 1;
        let target_y_offset = deterministic_roll(tick, entity.index() as usize, 492, 3) as i32 - 1;
        let move_target = Point {
            x: player_position.x + target_x_offset,
            y: player_position.y + target_y_offset,
        };
        if let Some((destination, movement_direction)) =
            monster_step_toward_with_fallback(world, entity, position, &move_target, tick, 49)
        {
            attack_position = destination.clone();
            agent.next_move_tick = tick + agent.move_interval_ticks.max(1);
            world.entity_mut(entity).insert((
                Position(destination.clone()),
                Facing(movement_direction),
                agent.clone(),
            ));
            packets.push(ServerPacket::ObjectWalk {
                movement: ObjectMovement {
                    object_id: attacker_id,
                    position: destination,
                    direction: movement_direction,
                },
            });
        }
    }

    let attack_direction = direction_toward(&attack_position, player_position)
        .or_else(|| entity_facing(world, entity))
        .unwrap_or(MirDirection::Up);
    agent.tracking_player = true;
    agent.next_attack_tick = tick + agent.attack_interval_ticks.max(1);
    world
        .entity_mut(entity)
        .insert((Facing(attack_direction), agent.clone()));

    let damage = monster_player_attack_damage(
        world,
        &monster_name,
        agent,
        &attack_position,
        player_position,
    );
    if damage <= 0 {
        return true;
    }

    let due_tick = tick + monster_attack_delay_ticks(agent, &attack_position, player_position);
    let due_packet =
        monster_typed_attack_packet(world, entity, &attack_position, attack_direction, 0);
    schedule_damage_to_player_with_effect_and_due_packet(
        world,
        due_tick,
        attacker_id,
        monster_name,
        damage,
        None,
        due_packet,
    );

    #[allow(deprecated)]
    let monster_entities: Vec<Entity> = world
        .iter_entities()
        .filter_map(|entity| entity.contains::<Monster>().then_some(entity.id()))
        .collect();
    for area_target in nearby_opposing_monster_targets(
        world,
        &monster_entities,
        entity,
        &attack_position,
        agent,
        2,
    ) {
        schedule_damage_to_monster(
            world,
            due_tick,
            attacker_id,
            area_target,
            damage,
            None,
            None,
        );
    }

    true
}

fn update_yimoogi_state(
    world: &mut World,
    entity: Entity,
    agent: &mut MonsterAgent,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if agent.dead {
        return false;
    }

    let mut state = world
        .entity(entity)
        .get::<YimoogiState>()
        .copied()
        .unwrap_or_else(|| initial_yimoogi_state(tick));
    let original_state = state;
    let has_player_target = agent.tracking_player
        || (agent.hostile_to_player
            && tile_distance(position, player_position) <= agent.view_range.max(1));

    if !state.is_child && !state.final_teleport && yimoogi_should_final_teleport(world, entity) {
        if let Some(destination) = yimoogi_final_teleport_destination(world, entity, position, tick)
        {
            let old_position = position.clone();
            let direction = entity_facing(world, entity).unwrap_or(MirDirection::Down);
            state.final_teleport = true;
            agent.tracking_player = false;
            agent.next_move_tick = tick + 1;
            agent.next_attack_tick = tick + 1;
            world.entity_mut(entity).insert((
                Position(destination.clone()),
                Facing(direction),
                state,
            ));

            if let Some(object_id) = entity_object_id(world, entity) {
                packets.push(ServerPacket::ObjectWalk {
                    movement: ObjectMovement {
                        object_id,
                        position: destination,
                        direction,
                    },
                });
            }

            spawn_yimoogi_white_serpents(
                world,
                &old_position,
                direction,
                has_player_target.then(|| player_entity(world)).flatten(),
                agent,
                tick,
            );
            return true;
        }
    }

    if !state.is_child && !state.child_spawned && tick > state.spawn_tick {
        let direction = entity_facing(world, entity).unwrap_or(MirDirection::Down);
        if let Some(packet) = monster_typed_attack_packet(world, entity, position, direction, 2) {
            packets.push(packet);
        }
        if let Some(child_object_id) = spawn_yimoogi_child(
            world,
            entity,
            position,
            direction,
            has_player_target.then(|| player_entity(world)).flatten(),
            agent,
            tick,
        ) {
            state.child_spawned = true;
            state.sister_object_id = Some(child_object_id);
        }
        agent.next_move_tick = tick + 1;
        agent.next_attack_tick = tick + agent.attack_interval_ticks.max(1);
        world.entity_mut(entity).insert(state);
        return true;
    }

    if state != original_state {
        world.entity_mut(entity).insert(state);
    }
    false
}

fn yimoogi_should_final_teleport(world: &World, entity: Entity) -> bool {
    let Some(vitals) = world.entity(entity).get::<MonsterVitals>() else {
        return false;
    };
    vitals.hp <= vitals.max_hp / 10
}

fn yimoogi_final_teleport_destination(
    world: &World,
    entity: Entity,
    position: &Point,
    tick: u64,
) -> Option<Point> {
    let bounds = world.resource::<SimulationResources>().map_region_bounds;
    let width = u64::try_from(bounds.max_x - bounds.min_x + 1).ok()?;
    let height = u64::try_from(bounds.max_y - bounds.min_y + 1).ok()?;

    for attempt in 0..YIMOOGI_FINAL_TELEPORT_ATTEMPTS {
        let x = bounds.min_x
            + i32::try_from(deterministic_roll(
                tick + attempt as u64,
                entity.index() as usize,
                attempt * 2,
                width,
            ))
            .ok()?;
        let y = bounds.min_y
            + i32::try_from(deterministic_roll(
                tick + attempt as u64,
                entity.index() as usize,
                attempt * 2 + 1,
                height,
            ))
            .ok()?;
        let candidate = Point { x, y };
        if candidate != *position && can_occupy(world, candidate.clone(), Some(entity)) {
            return Some(candidate);
        }
    }

    None
}

fn spawn_yimoogi_child(
    world: &mut World,
    parent_entity: Entity,
    position: &Point,
    direction: MirDirection,
    target_entity: Option<Entity>,
    agent: &MonsterAgent,
    tick: u64,
) -> Option<u32> {
    let parent_object_id = entity_object_id(world, parent_entity)?;
    let name = entity_name(world, parent_entity).unwrap_or_else(|| "Yimoogi".to_string());
    let template = crystal_dynamic_monster_template(&name)?;
    let front = offset_point(position, direction, 1);
    let spawn_position = if can_occupy(world, front.clone(), Some(parent_entity)) {
        front
    } else {
        position.clone()
    };
    let child = spawn_yimoogi_runtime_monster(
        world,
        &template,
        spawn_position,
        direction,
        target_entity,
        agent,
        YIMOOGI_CHILD_ACTIVATION_DELAY_TICKS,
    )?;
    let child_object_id = entity_object_id(world, child)?;
    let mut entry = world.entity_mut(child);
    entry.insert(YimoogiState {
        spawn_tick: tick + YIMOOGI_CHILD_SPAWN_DELAY_TICKS,
        child_spawned: true,
        is_child: true,
        final_teleport: false,
        sister_object_id: Some(parent_object_id),
    });
    Some(child_object_id)
}

fn spawn_yimoogi_runtime_monster(
    world: &mut World,
    template: &CrystalRespawnTemplate,
    position: Point,
    direction: MirDirection,
    target_entity: Option<Entity>,
    parent_agent: &MonsterAgent,
    activation_delay_ticks: u64,
) -> Option<Entity> {
    let tick = world.resource::<SimulationResources>().tick;
    let mut agent = MonsterAgent {
        image: template.monster_image,
        dead: false,
        patrol_origin: position.clone(),
        ai: template.monster_ai,
        disposition: parent_agent.disposition,
        hostile_to_player: parent_agent.hostile_to_player,
        tracking_player: false,
        view_range: i32::from(template.monster_view_range),
        can_wander: crystal_respawn_can_wander(template.monster_hp),
        move_interval_ticks: crystal_speed_to_ticks(template.monster_move_speed),
        attack_interval_ticks: crystal_speed_to_ticks(template.monster_attack_speed),
        next_move_tick: tick + activation_delay_ticks,
        next_attack_tick: tick + activation_delay_ticks,
        route: Vec::new(),
        route_index: 0,
        route_waiting: false,
        next_route_tick: tick + activation_delay_ticks,
    };
    if target_entity.is_some() && agent.hostile_to_player {
        agent.tracking_player = true;
    }

    let object_id = allocate_runtime_monster_object_id(world);
    let mut entity = world.spawn((
        WorldObject,
        Monster,
        ObjectId(object_id),
        DisplayName::literal(template.monster_name.clone()),
        Position(position.clone()),
        Facing(direction),
        agent,
        initial_monster_ai_state_for_object(
            template.monster_ai,
            tick + activation_delay_ticks,
            object_id,
        ),
        MonsterVitals {
            hp: template.monster_hp.max(1),
            max_hp: template.monster_hp.max(1),
        },
    ));
    if template.monster_ai == 36 {
        entity.insert(initial_yimoogi_state(tick + activation_delay_ticks));
    }
    Some(entity.id())
}

fn spawn_yimoogi_white_serpents(
    world: &mut World,
    position: &Point,
    direction: MirDirection,
    target_entity: Option<Entity>,
    agent: &MonsterAgent,
    _tick: u64,
) {
    let Some(template) = crystal_dynamic_monster_template(YIMOOGI_WHITE_SERPENT_NAME) else {
        return;
    };

    for _ in 0..YIMOOGI_FINAL_WHITE_SERPENT_COUNT {
        let _ = spawn_yimoogi_runtime_monster(
            world,
            &template,
            position.clone(),
            direction,
            target_entity,
            agent,
            YIMOOGI_CHILD_ACTIVATION_DELAY_TICKS,
        );
    }
}

fn update_dragon_statue_sleep_state(
    world: &mut World,
    entity: Entity,
    agent: &mut MonsterAgent,
    ai_state: &mut MonsterAiState,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if agent.dead || !ai_state.mode {
        return false;
    }

    agent.tracking_player = false;
    agent.next_attack_tick = tick + 1;
    agent.next_move_tick = tick + 1;
    if tick < ai_state.next_state_tick {
        return true;
    }

    ai_state.mode = false;
    let max_hp = world
        .entity(entity)
        .get::<MonsterVitals>()
        .map(|vitals| vitals.max_hp)
        .unwrap_or(1);
    world
        .entity_mut(entity)
        .insert(MonsterVitals { hp: max_hp, max_hp });
    if let Some(info) = object_health_info_for_entity(world, entity, 0) {
        packets.push(ServerPacket::ObjectHealth { info });
    }
    true
}

fn update_frost_tiger_sitting_state(
    world: &mut World,
    entity: Entity,
    agent: &mut MonsterAgent,
    ai_state: &mut MonsterAiState,
    position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if agent.dead {
        return false;
    }

    if ai_state.extra {
        if agent.tracking_player {
            ai_state.extra = false;
            ai_state.next_state_tick = tick + FROST_TIGER_SIT_DOWN_MAX_DELAY_TICKS;
            if let Some(packet) = object_sit_down_packet(world, entity, position, false) {
                packets.push(packet);
            }
            return false;
        }
        agent.next_attack_tick = tick + 1;
        agent.next_move_tick = tick + 1;
        return true;
    }

    if !agent.tracking_player && tick >= ai_state.next_state_tick {
        ai_state.extra = true;
        agent.tracking_player = false;
        agent.next_attack_tick = tick + 1;
        agent.next_move_tick = tick + 1;
        if let Some(packet) = object_sit_down_packet(world, entity, position, true) {
            packets.push(packet);
        }
        return true;
    }

    false
}

fn object_sit_down_packet(
    world: &World,
    entity: Entity,
    position: &Point,
    sitting: bool,
) -> Option<ServerPacket> {
    let object_id = entity_object_id(world, entity)?;
    let direction = world.entity(entity).get::<Facing>()?.0;
    Some(ServerPacket::ObjectSitDown {
        movement: ObjectMovement {
            object_id,
            position: position.clone(),
            direction,
        },
        sitting,
    })
}

fn update_foxman_fear_state(
    world: &mut World,
    entity: Entity,
    agent: &mut MonsterAgent,
    ai_state: &mut MonsterAiState,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if agent.dead || !agent.tracking_player {
        return false;
    }

    let distance = tile_distance(position, player_position);
    if agent.ai == 45
        && distance <= 1
        && tick < ai_state.next_state_tick
        && tick >= agent.next_route_tick
    {
        if let Some(destination) = foxman_teleport_destination(world, entity, position, tick) {
            let direction = direction_toward(&destination, player_position).unwrap_or_else(|| {
                world
                    .entity(entity)
                    .get::<Facing>()
                    .map(|facing| facing.0)
                    .unwrap_or(MirDirection::Down)
            });
            agent.next_route_tick = tick + RED_FOXMAN_TELEPORT_COOLDOWN_TICKS;
            agent.next_move_tick = tick + 1;
            agent.next_attack_tick = tick + 1;
            world.entity_mut(entity).insert((
                Position(destination.clone()),
                Facing(direction),
                agent.clone(),
            ));
            if let Some(object_id) = entity_object_id(world, entity) {
                packets.push(ServerPacket::ObjectTeleportOut {
                    object_id,
                    effect_type: RED_FOXMAN_TELEPORT_EFFECT,
                });
                packets.push(ServerPacket::ObjectWalk {
                    movement: ObjectMovement {
                        object_id,
                        position: destination,
                        direction,
                    },
                });
                packets.push(ServerPacket::ObjectTeleportIn {
                    object_id,
                    effect_type: RED_FOXMAN_TELEPORT_EFFECT,
                });
            }
            return true;
        }
    }

    if tick < ai_state.next_state_tick {
        return false;
    }

    ai_state.next_state_tick = tick + FOXMAN_FEAR_DURATION_TICKS;
    if tick < agent.next_move_tick {
        return true;
    }

    let attack_range = monster_attack_range(agent);
    let preferred_direction = if distance >= attack_range {
        direction_toward(position, player_position)
    } else {
        direction_toward(player_position, position)
    };
    let Some(preferred_direction) = preferred_direction else {
        return true;
    };
    let object_id = entity_object_id(world, entity).unwrap_or_default();
    let prefer_next = deterministic_chance_roll(tick, object_id, 450, 2);
    let offsets: [i32; 8] = if prefer_next {
        [0, 1, 2, 3, 4, 5, 6, 7]
    } else {
        [0, -1, -2, -3, -4, -5, -6, -7]
    };

    for offset in offsets {
        let direction = rotated_direction(preferred_direction, offset);
        let next = offset_point(position, direction, 1);
        if !can_occupy(world, next.clone(), Some(entity)) {
            continue;
        }

        agent.next_move_tick = tick + agent.move_interval_ticks.max(1);
        world
            .entity_mut(entity)
            .insert((Position(next.clone()), Facing(direction), agent.clone()));
        packets.push(ServerPacket::ObjectWalk {
            movement: ObjectMovement {
                object_id,
                position: next,
                direction,
            },
        });
        return true;
    }

    true
}

fn foxman_teleport_destination(
    world: &World,
    entity: Entity,
    position: &Point,
    tick: u64,
) -> Option<Point> {
    let object_id = entity_object_id(world, entity).unwrap_or_default();
    let side = RED_FOXMAN_TELEPORT_RADIUS * 2 + 1;
    let area = side * side;
    let start = ((tick as i32)
        .wrapping_add((object_id as i32).wrapping_mul(31))
        .rem_euclid(area)) as i32;

    for offset in 0..area {
        let index = (start + offset).rem_euclid(area);
        let dx = index.rem_euclid(side) - RED_FOXMAN_TELEPORT_RADIUS;
        let dy = index.div_euclid(side) - RED_FOXMAN_TELEPORT_RADIUS;
        let candidate = Point {
            x: position.x + dx,
            y: position.y + dy,
        };
        if candidate == *position || tile_distance(position, &candidate) <= 1 {
            continue;
        }
        if can_occupy(world, candidate.clone(), Some(entity)) {
            return Some(candidate);
        }
    }

    None
}

fn update_deer_run_away_state(
    world: &mut World,
    entity: Entity,
    agent: &mut MonsterAgent,
    ai_state: &mut MonsterAiState,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if agent.dead || !ai_state.mode || !agent.can_wander {
        return false;
    }

    let distance = tile_distance(position, player_position);
    if !agent.tracking_player && distance > agent.view_range.max(1) {
        return false;
    }
    agent.tracking_player = true;

    if tick < agent.next_move_tick {
        return true;
    }

    let Some(away_direction) = direction_toward(player_position, position) else {
        return true;
    };
    let object_id = entity_object_id(world, entity).unwrap_or_default();
    let prefer_next = deterministic_chance_roll(tick, object_id, 20, 2);
    let offsets: [i32; 8] = if prefer_next {
        [0, 1, 2, 3, 4, 5, 6, 7]
    } else {
        [0, -1, -2, -3, -4, -5, -6, -7]
    };

    for offset in offsets {
        let direction = rotated_direction(away_direction, offset);
        let next = offset_point(position, direction, 1);
        if !can_occupy(world, next.clone(), Some(entity)) {
            continue;
        }

        agent.next_move_tick = tick + agent.move_interval_ticks.max(1);
        world
            .entity_mut(entity)
            .insert((Position(next.clone()), Facing(direction), agent.clone()));
        packets.push(ServerPacket::ObjectWalk {
            movement: ObjectMovement {
                object_id,
                position: next,
                direction,
            },
        });
        return true;
    }

    true
}

fn update_axe_skeleton_fear_state(
    world: &mut World,
    entity: Entity,
    agent: &mut MonsterAgent,
    ai_state: &mut MonsterAiState,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if agent.dead || !agent.tracking_player {
        return false;
    }

    if tick < ai_state.next_state_tick {
        return false;
    }

    ai_state.next_state_tick = tick + FOXMAN_FEAR_DURATION_TICKS;
    if tick < agent.next_move_tick {
        return true;
    }

    let next_step = if tile_distance(position, player_position) >= monster_attack_range(agent) {
        monster_step_toward_with_fallback(world, entity, position, player_position, tick, 8)
    } else {
        let away_direction = direction_toward(player_position, position);
        let object_id = entity_object_id(world, entity).unwrap_or_default();
        let prefer_next = deterministic_chance_roll(tick, object_id, 80, 2);
        let offsets: [i32; 8] = if prefer_next {
            [0, 1, 2, 3, 4, 5, 6, 7]
        } else {
            [0, -1, -2, -3, -4, -5, -6, -7]
        };
        away_direction.and_then(|direction| {
            offsets.into_iter().find_map(|offset| {
                let direction = rotated_direction(direction, offset);
                let next = offset_point(position, direction, 1);
                can_occupy(world, next.clone(), Some(entity)).then_some((next, direction))
            })
        })
    };

    if let Some((next, direction)) = next_step {
        let object_id = entity_object_id(world, entity).unwrap_or_default();
        agent.next_move_tick = tick + agent.move_interval_ticks.max(1);
        world
            .entity_mut(entity)
            .insert((Position(next.clone()), Facing(direction), agent.clone()));
        packets.push(ServerPacket::ObjectWalk {
            movement: ObjectMovement {
                object_id,
                position: next,
                direction,
            },
        });
    }

    true
}

fn update_holy_deva_fear_state(
    world: &mut World,
    entity: Entity,
    agent: &mut MonsterAgent,
    ai_state: &mut MonsterAiState,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if agent.dead
        || !agent.tracking_player
        || world.entity(entity).get::<SummonedMonster>().is_some()
    {
        return false;
    }

    if tick < ai_state.next_state_tick {
        return false;
    }

    ai_state.next_state_tick = tick + FOXMAN_FEAR_DURATION_TICKS;
    if tile_distance(position, player_position) >= monster_attack_range(agent) {
        return true;
    }
    if tick < agent.next_move_tick {
        return true;
    }

    let Some(away_direction) = direction_toward(player_position, position) else {
        return true;
    };
    let object_id = entity_object_id(world, entity).unwrap_or_default();
    let prefer_next = deterministic_chance_roll(tick, object_id, 380, 2);
    let offsets: [i32; 8] = if prefer_next {
        [0, 1, 2, 3, 4, 5, 6, 7]
    } else {
        [0, -1, -2, -3, -4, -5, -6, -7]
    };

    for offset in offsets {
        let direction = rotated_direction(away_direction, offset);
        let next = offset_point(position, direction, 1);
        if !can_occupy(world, next.clone(), Some(entity)) {
            continue;
        }

        agent.next_move_tick = tick + agent.move_interval_ticks.max(1);
        world
            .entity_mut(entity)
            .insert((Position(next.clone()), Facing(direction), agent.clone()));
        packets.push(ServerPacket::ObjectWalk {
            movement: ObjectMovement {
                object_id,
                position: next,
                direction,
            },
        });
        return true;
    }

    true
}

fn update_kirin_ice_thrust_state(
    world: &mut World,
    entity: Entity,
    agent: &mut MonsterAgent,
    ai_state: &MonsterAiState,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if agent.dead || !monster_can_attack(agent, ai_state) {
        return false;
    }
    let distance = tile_distance(position, player_position);
    if distance != 3 {
        return false;
    }
    if !agent.tracking_player && !(agent.hostile_to_player && distance <= agent.view_range.max(1)) {
        return false;
    }
    if tick < agent.next_attack_tick || tick % 5 != 0 {
        return false;
    }

    let Some(attacker_id) = entity_object_id(world, entity) else {
        return false;
    };
    let monster_name = entity_name(world, entity).unwrap_or_else(|| "Lamia".to_string());
    let base_damage = crystal_monster_raw_magic_damage(&monster_name);
    if base_damage <= 0 {
        return false;
    }
    let Some(attack_direction) = direction_toward(position, player_position) else {
        return false;
    };
    let mitigation = total_defence_bonus(world.resource::<SimulationResources>());
    let damage = (base_damage - mitigation).max(1);
    let due_tick = tick + combat_delay_ticks(500);

    agent.tracking_player = true;
    agent.next_attack_tick = tick + agent.attack_interval_ticks.max(1);
    world
        .entity_mut(entity)
        .insert((Facing(attack_direction), agent.clone()));
    if let Some(packet) = monster_typed_attack_packet(world, entity, position, attack_direction, 2)
    {
        packets.push(packet);
    }

    schedule_damage_to_player_with_effect(
        world,
        due_tick,
        attacker_id,
        monster_name.clone(),
        damage,
        Some(PendingPlayerStatusEffect::SlowPoison {
            chance_denominator: KIRIN_SLOW_CHANCE_DENOMINATOR,
            duration_ticks: KIRIN_SLOW_DURATION_TICKS,
            salt: 186,
        }),
    );

    #[allow(deprecated)]
    let monster_entities: Vec<Entity> = world
        .iter_entities()
        .filter_map(|entity| entity.contains::<Monster>().then_some(entity.id()))
        .collect();
    for target in manectric_claw_cone_opposing_monster_targets(
        world,
        &monster_entities,
        entity,
        position,
        attack_direction,
        agent,
    ) {
        schedule_damage_to_monster(world, due_tick, attacker_id, target, damage, None, None);
    }

    true
}

fn update_general_meow_meow_state(
    world: &mut World,
    entity: Entity,
    agent: &MonsterAgent,
    ai_state: &mut MonsterAiState,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) {
    if agent.dead {
        return;
    }

    let mut state = world
        .entity(entity)
        .get::<GeneralMeowMeowState>()
        .copied()
        .unwrap_or_else(|| initial_general_meow_meow_state(tick));
    let original_state = state;
    let was_shield_active = ai_state.mode;
    let has_player_target = agent.tracking_player
        || (agent.hostile_to_player
            && tile_distance(position, player_position) <= agent.view_range.max(1));

    if has_player_target && tick > state.next_slave_spawn_tick {
        if let Some(object_id) = entity_object_id(world, entity) {
            let target_entity = player_entity(world);
            let direction = direction_toward(position, player_position)
                .or_else(|| entity_facing(world, entity))
                .unwrap_or(MirDirection::Up);
            spawn_monster_slave_wave(
                world,
                entity,
                object_id,
                position,
                direction,
                target_entity,
                agent,
                tick,
                &GENERAL_MEOW_MEOW_SLAVE_NAMES,
                GENERAL_MEOW_MEOW_MAX_SLAVES,
                GENERAL_MEOW_MEOW_SLAVE_SPAWN_COUNT,
            );
        }
        state.next_slave_spawn_tick = tick + GENERAL_MEOW_MEOW_SLAVE_SPAWN_INTERVAL_TICKS;
    }

    let can_use_shield = has_player_target
        && monster_can_attack(agent, ai_state)
        && monster_in_attack_range(agent, position, player_position);
    let in_shield_phase = can_use_shield
        && world
            .entity(entity)
            .get::<MonsterVitals>()
            .map(|vitals| general_meow_meow_shield_phase(vitals.hp, vitals.max_hp))
            .unwrap_or(false);

    if in_shield_phase {
        state.shield_until_tick = tick + GENERAL_MEOW_MEOW_SHIELD_DURATION_TICKS;
        if state.next_thunder_tick == 0 || tick > state.next_thunder_tick {
            if cast_general_meow_meow_mass_thunder(
                world,
                entity,
                agent,
                position,
                player_position,
                tick,
                packets,
            ) {
                state.next_thunder_tick = tick
                    + GENERAL_MEOW_MEOW_THUNDER_MIN_COOLDOWN_TICKS
                    + deterministic_roll(
                        tick,
                        entity.index() as usize,
                        1230,
                        GENERAL_MEOW_MEOW_THUNDER_RANDOM_COOLDOWN_TICKS,
                    );
            }
        }
    }

    ai_state.mode = state.shield_until_tick > tick;
    if state != original_state {
        world.entity_mut(entity).insert(state);
    }
    if ai_state.mode != was_shield_active {
        if let Some((_, bundle)) =
            visible_object_bundle_for_entity(world, entity, current_language(world))
        {
            if matches!(bundle.spawn_packet, ServerPacket::ObjectMonster { .. }) {
                packets.push(bundle.spawn_packet);
            }
        }
    }
}

fn general_meow_meow_shield_phase(hp: i32, max_hp: i32) -> bool {
    let percent = hp.max(0) * 100 / max_hp.max(1);
    (70..=80).contains(&percent) || (40..=50).contains(&percent) || percent <= 20
}

fn cast_general_meow_meow_mass_thunder(
    world: &mut World,
    entity: Entity,
    agent: &MonsterAgent,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    let Some(attacker_id) = entity_object_id(world, entity) else {
        return false;
    };
    let monster_name = entity_name(world, entity).unwrap_or_else(|| "GeneralMeowMeow".to_string());
    let base_damage = crystal_monster_raw_magic_damage(&monster_name);
    let damage = if base_damage > 0 {
        let mitigation = total_defence_bonus(world.resource::<SimulationResources>());
        (base_damage - mitigation).max(1)
    } else {
        0
    };
    let due_tick = tick + GENERAL_MEOW_MEOW_THUNDER_SPAWN_DELAY_TICKS;
    let mut cast_count = 0;

    if agent.hostile_to_player {
        if player_entity(world).is_some() {
            let spell_packet = general_meow_meow_thunder_spell_packet(
                world,
                player_position.clone(),
                MirDirection::Up,
            );
            schedule_damage_to_player_with_effect_and_due_packet(
                world,
                due_tick,
                attacker_id,
                monster_name.clone(),
                damage,
                None,
                Some(spell_packet),
            );
            cast_count += 1;
        }
    }

    let monster_entities: Vec<Entity> = world
        .query_filtered::<Entity, bevy_ecs::query::With<Monster>>()
        .iter(world)
        .collect();
    let targets = nearby_opposing_monster_targets(
        world,
        &monster_entities,
        entity,
        player_position,
        agent,
        12,
    );
    for target in targets {
        let Some(target_position) = entity_position(world, target) else {
            continue;
        };
        let spell_packet =
            general_meow_meow_thunder_spell_packet(world, target_position, MirDirection::Up);
        schedule_damage_to_monster_with_due_packet(
            world,
            due_tick,
            attacker_id,
            target,
            damage,
            None,
            None,
            Some(spell_packet),
        );
        cast_count += 1;
    }

    let _ = position;
    let _ = packets;
    cast_count > 0
}

fn update_bone_lord_state(
    world: &mut World,
    entity: Entity,
    agent: &mut MonsterAgent,
    ai_state: &mut MonsterAiState,
    position: &Point,
    player_position: &Point,
    tick: u64,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    if agent.dead || !monster_can_attack(agent, ai_state) {
        return false;
    }
    if !agent.tracking_player
        && !(agent.hostile_to_player
            && tile_distance(position, player_position) <= agent.view_range.max(1))
    {
        return false;
    }

    let Some(vitals) = world.entity(entity).get::<MonsterVitals>().copied() else {
        return false;
    };
    if vitals.max_hp < i32::from(BONE_LORD_STAGE_COUNT) {
        return false;
    }

    let stage_size = (vitals.max_hp / i32::from(BONE_LORD_STAGE_COUNT)).max(1);
    let stage = (vitals.hp.max(0) / stage_size).clamp(0, i32::from(BONE_LORD_STAGE_COUNT)) as u8;
    if stage >= ai_state.extra_byte {
        return false;
    }

    let Some(object_id) = entity_object_id(world, entity) else {
        return false;
    };
    let Some(player) = player_entity(world) else {
        return false;
    };
    let direction = direction_toward(position, player_position)
        .or_else(|| entity_facing(world, entity))
        .unwrap_or(MirDirection::Up);

    ai_state.extra_byte = stage;
    agent.tracking_player = true;
    agent.next_attack_tick = tick + agent.attack_interval_ticks.max(1);
    world.entity_mut(entity).insert(Facing(direction));
    if let Some(packet) = monster_typed_attack_packet(world, entity, position, direction, 1) {
        packets.push(packet);
    }

    spawn_monster_slave_wave(
        world,
        entity,
        object_id,
        position,
        direction,
        Some(player),
        agent,
        tick,
        &BONE_LORD_SLAVE_NAMES,
        BONE_LORD_MAX_SLAVES,
        BONE_LORD_SPAWN_BATCH_SIZE,
    );
    true
}

