fn rotated_direction(direction: MirDirection, offset: i32) -> MirDirection {
    const DIRECTIONS: [MirDirection; 8] = [
        MirDirection::Up,
        MirDirection::UpRight,
        MirDirection::Right,
        MirDirection::DownRight,
        MirDirection::Down,
        MirDirection::DownLeft,
        MirDirection::Left,
        MirDirection::UpLeft,
    ];

    let index = (direction as i32 + offset).rem_euclid(8) as usize;
    DIRECTIONS[index]
}

fn tucson_mage_wide_line_points(attacker_position: &Point, direction: MirDirection) -> Vec<Point> {
    let forward = offset_point(attacker_position, direction, 1);
    let mut points = vec![forward.clone()];

    for offset in -1..=1 {
        let line_direction = rotated_direction(direction, offset);
        for amount in 1..=2 {
            points.push(offset_point(&forward, line_direction, amount));
        }
    }

    points
}

