fn record_crystal_npc_script_diagnostic(
    world: &mut World,
    execution_state: &CrystalNpcExecutionState,
    command: impl Into<String>,
    message: impl Into<String>,
) {
    let diagnostic = CrystalNpcScriptDiagnostic {
        script_key: execution_state
            .script_key
            .clone()
            .unwrap_or_else(|| "<inline>".to_string()),
        label: execution_state
            .section_label
            .clone()
            .unwrap_or_else(|| "<inline>".to_string()),
        line_number: execution_state.line_number,
        command: command.into(),
        message: message.into(),
    };
    world
        .resource_mut::<SimulationResources>()
        .npc_script_diagnostics
        .push(diagnostic);
}

fn crystal_npc_compare_numeric(_world: &World, left: i32, parts: &[&str]) -> bool {
    let [operator, right] = parts else {
        return false;
    };
    let Ok(right) = right.parse::<i32>() else {
        return false;
    };

    match *operator {
        ">" => left > right,
        "<" => left < right,
        ">=" => left >= right,
        "<=" => left <= right,
        "=" | "==" => left == right,
        "<>" | "!=" => left != right,
        _ => false,
    }
}

