#[allow(deprecated)]
fn crystal_npc_group_member_entities(world: &World) -> Vec<Entity> {
    let resources = world.resource::<SimulationResources>();
    let mut members = Vec::new();

    if let Some(player) = player_entity(world) {
        members.push(player);
    }

    for object_id in &resources.group_member_object_ids {
        if let Some(entity) = entity_by_object_id(world, *object_id) {
            if !members.contains(&entity) {
                members.push(entity);
            }
        }
    }

    members
}

