fn crystal_npc_check_mon(world: &World, parts: &[&str]) -> bool {
    let [operator, count, map_file_name, instance] = parts else {
        return false;
    };
    let Ok(count) = count.parse::<i32>() else {
        return false;
    };
    let Ok(instance) = instance.parse::<i32>() else {
        return false;
    };

    let current_map = world
        .resource::<SimulationResources>()
        .current_map
        .file_name
        .clone();
    if instance != 1
        || normalize_map_file_name(&current_map) != normalize_map_file_name(map_file_name)
    {
        return false;
    }

    let current_count = crystal_npc_current_map_monster_count(world);
    match *operator {
        ">" => current_count > count,
        "<" => current_count < count,
        ">=" => current_count >= count,
        "<=" => current_count <= count,
        "=" | "==" => current_count == count,
        "<>" | "!=" => current_count != count,
        _ => false,
    }
}

fn crystal_npc_check_exact_mon(world: &World, parts: &[&str]) -> bool {
    let [monster_name, operator, count, map_file_name, instance] = parts else {
        return false;
    };
    let Ok(count) = count.parse::<i32>() else {
        return false;
    };
    let Ok(instance) = instance.parse::<i32>() else {
        return false;
    };
    if crystal_dynamic_monster_template(monster_name).is_none() {
        return false;
    }

    let current_map = world
        .resource::<SimulationResources>()
        .current_map
        .file_name
        .clone();
    if instance != 1
        || normalize_map_file_name(&current_map) != normalize_map_file_name(map_file_name)
    {
        return false;
    }

    let current_count = crystal_npc_current_map_monster_count_by_name(world, monster_name);
    match *operator {
        ">" => current_count > count,
        "<" => current_count < count,
        ">=" => current_count >= count,
        "<=" => current_count <= count,
        "=" | "==" => current_count == count,
        "<>" | "!=" => current_count != count,
        _ => false,
    }
}

fn crystal_npc_check_map(world: &World, parts: &[&str]) -> bool {
    let [map_file_name] = parts else {
        return false;
    };
    let current_map = world
        .resource::<SimulationResources>()
        .current_map
        .file_name
        .clone();
    normalize_map_file_name(&current_map) == normalize_map_file_name(map_file_name)
}

fn crystal_npc_check_range(world: &World, parts: &[&str]) -> bool {
    let [x, y, radius] = parts else {
        return false;
    };
    let (Ok(x), Ok(y), Ok(radius)) = (x.parse::<i32>(), y.parse::<i32>(), radius.parse::<i32>())
    else {
        return false;
    };
    let Some(player) = player_entity(world) else {
        return false;
    };
    let Some(position) = entity_position(world, player) else {
        return false;
    };
    (position.x - x).abs() <= radius && (position.y - y).abs() <= radius
}

fn crystal_npc_check_hum(world: &World, parts: &[&str]) -> bool {
    match parts {
        [operator, count, map_file_name] => {
            if !crystal_npc_check_map(world, &[*map_file_name]) {
                return false;
            }
            crystal_npc_compare_numeric(world, 1, &[*operator, *count])
        }
        [count, map_file_name] => {
            if !crystal_npc_check_map(world, &[*map_file_name]) {
                return false;
            }
            count.parse::<i32>().is_ok_and(|expected| expected <= 1)
        }
        _ => false,
    }
}

