fn crystal_skill_state(spell_name: &str, level: u8) -> Option<SkillState> {
    if let Some(skill) = starter_server_data().skills.into_iter().find(|skill| {
        skill
            .crystal_spell
            .as_deref()
            .is_some_and(|spell| spell.eq_ignore_ascii_case(spell_name))
    }) {
        return Some(SkillState {
            key: skill.key,
            name: skill.name,
            description: skill.description,
            level,
            cooldown_ticks: skill.cooldown_ticks,
            cooldown_ends_at: 0,
        });
    }

    let magic = crystal_magic_by_spell(spell_name)?;
    Some(SkillState {
        key: normalize_crystal_skill_key(&magic.spell),
        name: magic.name,
        description: format!("Crystal NPC granted skill {}.", magic.spell),
        level,
        cooldown_ticks: magic.delay_base.max(1),
        cooldown_ends_at: 0,
    })
}

fn normalize_crystal_skill_key(spell_name: &str) -> String {
    spell_name
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() {
                ch.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect::<String>()
        .trim_matches('-')
        .to_string()
}

fn crystal_npc_message_packet(line: &str, default_chat_type: ChatType) -> Option<ServerPacket> {
    let start = line.find('"')?;
    let end_offset = line[start + 1..].find('"')?;
    let message = line[start + 1..start + 1 + end_offset].to_string();
    let remainder = line[start + 1 + end_offset + 1..].trim();
    let chat_type = match remainder.to_ascii_uppercase().as_str() {
        "HINT" => ChatType::Hint,
        "ANNOUNCEMENT" => ChatType::Announcement,
        "GUILD" => ChatType::Guild,
        "GROUP" => ChatType::Group,
        "SHOUT" => ChatType::Shout,
        "SYSTEM" => ChatType::System,
        _ => default_chat_type,
    };
    Some(ServerPacket::Chat { message, chat_type })
}

