fn crystal_npc_take_conquest_gold(world: &mut World, parts: &[&str]) {
    let amount = parts
        .get(1)
        .or_else(|| parts.first())
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or(0);
    let mut resources = world.resource_mut::<SimulationResources>();
    if resources.stage5_systems.conquest.gold >= amount {
        resources.stage5_systems.conquest.gold -= amount;
    } else {
        resources.gold = resources.gold.saturating_sub(amount);
    }
}

