fn add_or_increment_item_with_durability_and_stats(
    world: &mut World,
    container: ItemContainer,
    key: &str,
    name: &str,
    description: &str,
    preferred_slot: u8,
    quantity: u32,
    weight: u16,
    durability_current: Option<u16>,
    durability_max: Option<u16>,
    added_attack: i32,
    added_defence: i32,
) -> ItemState {
    add_or_increment_item_with_random_metadata(
        world,
        container,
        key,
        name,
        description,
        preferred_slot,
        quantity,
        weight,
        durability_current,
        durability_max,
        added_attack,
        added_defence,
        Vec::new(),
        false,
        0,
    )
}

fn add_or_increment_item_with_random_metadata(
    world: &mut World,
    container: ItemContainer,
    key: &str,
    name: &str,
    description: &str,
    preferred_slot: u8,
    quantity: u32,
    weight: u16,
    durability_current: Option<u16>,
    durability_max: Option<u16>,
    added_attack: i32,
    added_defence: i32,
    added_stats: Vec<UserItemStat>,
    cursed: bool,
    socket_slots: u8,
) -> ItemState {
    let max_stack = crystal_stack_size_for_item_key(key);
    let mut remaining = quantity.max(1);
    let mut resources = world.resource_mut::<SimulationResources>();
    let mut last_changed = None;
    let has_per_item_metadata = durability_current.is_some()
        || durability_max.is_some()
        || added_attack != 0
        || added_defence != 0
        || !added_stats.is_empty()
        || cursed
        || socket_slots != 0;
    if max_stack > 1 && !has_per_item_metadata {
        if matches!(container, ItemContainer::Bag1 | ItemContainer::Bag2) {
            for existing in resources
                .belt_items
                .iter_mut()
                .filter(|item| item.key == key && item.quantity < max_stack)
            {
                let added = remaining.min(max_stack - existing.quantity);
                if added == 0 {
                    continue;
                }
                existing.quantity += added;
                remaining -= added;
                last_changed = Some(existing.clone());
                if remaining == 0 {
                    return last_changed.expect("changed stack should exist");
                }
            }
        }
        for existing in resources.inventory_items.iter_mut().filter(|item| {
            item.key == key
                && item_containers_stack_together(item.container, container)
                && item.quantity < max_stack
        }) {
            let added = remaining.min(max_stack - existing.quantity);
            if added == 0 {
                continue;
            }
            existing.quantity += added;
            remaining -= added;
            last_changed = Some(existing.clone());
            if remaining == 0 {
                return last_changed.expect("changed stack should exist");
            }
        }
    }

    while remaining > 0 || last_changed.is_none() {
        let stack_quantity = remaining.min(max_stack);
        let (item_container, slot) = match crystal_empty_add_item_slots(&resources, container, key)
            .into_iter()
            .next()
        {
            Some(slot) => slot,
            None if last_changed.is_some() => break,
            None => match find_empty_inventory_item_slot(&resources.inventory_items, container) {
                Some(slot) => slot,
                None if last_changed.is_some() => break,
                None => (container, preferred_slot),
            },
        };
        let item = ItemState {
            key: key.to_string(),
            name: name.to_string(),
            icon: item_icon_for_key(key),
            slot,
            container: item_container,
            quantity: stack_quantity,
            description: description.to_string(),
            durability_current,
            durability_max,
            weight,
            equip_slot: None,
            grade: ItemGrade::None,
            added_attack,
            added_defence,
            added_stats: added_stats.clone(),
            cursed,
            socket_slots,
            sealed_expiry_time_binary_datetime: 0,
            sealed_next_time_binary_datetime: 0,
            attack: 0,
            defence: 0,
            heal_hp: 0,
            heal_mp: 0,
        };
        if item_container == ItemContainer::Belt {
            resources.belt_items.push(item.clone());
        } else {
            resources.inventory_items.push(item.clone());
        }
        last_changed = Some(item);
        if remaining <= stack_quantity {
            break;
        }
        remaining -= stack_quantity;
    }

    last_changed.expect("added item should exist")
}

fn replace_equipment(world: &mut World, next: EquipmentState) {
    let mut resources = world.resource_mut::<SimulationResources>();
    if let Some(existing) = resources
        .equipment_items
        .iter_mut()
        .find(|item| item.slot == next.slot)
    {
        *existing = next;
    } else {
        resources.equipment_items.push(next);
    }
}

fn spawn_ground_drop(
    world: &mut World,
    position: Point,
    source_monster: &str,
    source_monster_key: Option<String>,
    loot: DropLoot,
    quantity: u32,
    display_name: String,
) -> SpawnedDrop {
    spawn_ground_drop_with_ownership(
        world,
        position,
        source_monster,
        source_monster_key,
        loot,
        quantity,
        display_name,
        None,
    )
}

fn spawn_ground_drop_with_ownership(
    world: &mut World,
    position: Point,
    source_monster: &str,
    source_monster_key: Option<String>,
    loot: DropLoot,
    quantity: u32,
    display_name: String,
    ownership: Option<DropOwnership>,
) -> SpawnedDrop {
    let object_id = {
        let mut resources = world.resource_mut::<SimulationResources>();
        let object_id = resources.next_drop_object_id;
        resources.next_drop_object_id += 1;
        object_id
    };
    let expires_at_tick = world
        .resource::<SimulationResources>()
        .tick
        .saturating_add(CRYSTAL_DROP_EXPIRE_TICKS);

    let mut entity = world.spawn((
        WorldObject,
        GroundDrop,
        DropExpiry { expires_at_tick },
        ObjectId(object_id),
        localized_drop_name_key(&display_name)
            .map(|key| DisplayName::localized(key, display_name.clone()))
            .unwrap_or_else(|| DisplayName::literal(display_name)),
        Position(position.clone()),
        DropPayload {
            quantity,
            source_monster: source_monster.to_string(),
            source_monster_key,
            loot,
        },
    ));
    if let Some(ownership) = ownership {
        entity.insert(ownership);
    }
    SpawnedDrop {
        object_id,
        position,
    }
}

fn drop_ground_drop(
    world: &mut World,
    origin: Point,
    distance: i32,
    source_monster: &str,
    source_monster_key: Option<String>,
    loot: DropLoot,
    quantity: u32,
    display_name: String,
) -> Option<SpawnedDrop> {
    drop_ground_drop_with_ownership(
        world,
        origin,
        distance,
        source_monster,
        source_monster_key,
        loot,
        quantity,
        display_name,
        None,
    )
}

fn drop_ground_drop_with_ownership(
    world: &mut World,
    origin: Point,
    distance: i32,
    source_monster: &str,
    source_monster_key: Option<String>,
    loot: DropLoot,
    quantity: u32,
    display_name: String,
    ownership: Option<DropOwnership>,
) -> Option<SpawnedDrop> {
    let position = crystal_ground_drop_position(world, &origin, distance)?;
    Some(spawn_ground_drop_with_ownership(
        world,
        position,
        source_monster,
        source_monster_key,
        loot,
        quantity,
        display_name,
        ownership,
    ))
}

#[allow(deprecated)]
fn crystal_ground_drop_position(world: &World, origin: &Point, distance: i32) -> Option<Point> {
    let distance = distance.max(0);
    let mut best: Option<(Point, usize)> = None;

    for d in 0..=distance {
        for y in (origin.y - d)..=(origin.y + d) {
            let mut x = origin.x - d;
            let step = if (y - origin.y).abs() == d {
                1
            } else {
                (d * 2).max(1)
            };
            while x <= origin.x + d {
                let point = Point { x, y };
                x += step;

                if !crystal_ground_drop_point_is_valid(world, &point) {
                    continue;
                }

                let count = ground_drop_count_at(world, &point);
                if count >= CRYSTAL_DROP_STACK_SIZE {
                    continue;
                }
                if count == 0 {
                    return Some(point);
                }
                if best
                    .as_ref()
                    .map(|(_, best_count)| count < *best_count)
                    .unwrap_or(true)
                {
                    best = Some((point, count));
                }
            }
        }
    }

    best.map(|(point, _)| point)
}

fn crystal_ground_drop_point_is_valid(world: &World, point: &Point) -> bool {
    !is_blocked_tile(world, point)
        && !has_blocking_entity(world, point, None)
        && !is_current_map_transfer_source(world, point)
}

#[allow(deprecated)]
fn ground_drop_count_at(world: &World, point: &Point) -> usize {
    world
        .iter_entities()
        .filter(|entity| {
            entity.get::<GroundDrop>().is_some()
                && entity
                    .get::<Position>()
                    .map(|position| &position.0 == point)
                    .unwrap_or(false)
        })
        .count()
}

fn is_current_map_transfer_source(world: &World, point: &Point) -> bool {
    let resources = world.resource::<SimulationResources>();
    let current_map = normalize_map_file_name(&resources.current_map.file_name);
    resources
        .config
        .map_transfers
        .iter()
        .filter(|transfer| normalize_map_file_name(&transfer.from_map_file_name) == current_map)
        .any(|transfer| point_in_bounds(&transfer.from_bounds, point))
        || crystal_movement_transfer_records_for_map(&resources.current_map.file_name)
            .iter()
            .any(|transfer| {
                normalize_map_file_name(&transfer.from_map_file_name) == current_map
                    && point_in_bounds(&transfer.from_bounds, point)
            })
}

fn resolved_monster_drop_templates(
    world: &World,
    monster_object_id: u32,
    monster_name: &str,
) -> Vec<ResolvedDropTemplate> {
    let current_tick = world.resource::<SimulationResources>().tick;
    let crystal_drops =
        crystal_monster_drop_templates(monster_name, monster_object_id, current_tick);
    if !crystal_drops.is_empty() {
        return crystal_drops;
    }

    starter_server_data()
        .monster_drops
        .into_iter()
        .find(|table| table.monster_object_id == monster_object_id)
        .map(|table| {
            table
                .drops
                .into_iter()
                .map(resolved_drop_template_from_starter)
                .collect()
        })
        .unwrap_or_default()
}

fn resolved_drop_template_from_starter(drop: DropTemplate) -> ResolvedDropTemplate {
    match drop {
        DropTemplate::Gold {
            name,
            amount,
            quantity,
        } => ResolvedDropTemplate::Gold {
            name,
            amount,
            quantity,
        },
        DropTemplate::Item {
            key,
            name,
            description,
            weight,
            quantity,
        } => ResolvedDropTemplate::Item {
            key,
            name,
            description,
            weight,
            quantity,
            durability_current: None,
            durability_max: None,
            added_attack: 0,
            added_defence: 0,
            added_stats: Vec::new(),
            cursed: false,
            socket_slots: 0,
            item_type: 0,
            show_group_pickup: false,
            quest_required: false,
        },
    }
}

fn crystal_monster_drop_templates(
    monster_name: &str,
    monster_object_id: u32,
    current_tick: u64,
) -> Vec<ResolvedDropTemplate> {
    let Some(drop_table) = crystal_drop_table_for_monster_name(monster_name) else {
        return Vec::new();
    };

    let mut drops = Vec::new();
    let mut entry_salt = 0_usize;
    for entry in drop_table
        .sections
        .into_iter()
        .flat_map(|section| section.entries)
    {
        if let Some(mut resolved) =
            crystal_attempt_drop_entry(&entry, current_tick, monster_object_id, entry_salt)
        {
            drops.append(&mut resolved);
        }
        entry_salt = entry_salt.saturating_add(1);
    }
    drops
}

fn crystal_group_child_drop_salt(parent_salt: usize, child_index: usize) -> usize {
    1_000_000_usize
        .saturating_add(parent_salt.saturating_mul(10_000))
        .saturating_add(child_index)
}

fn crystal_attempt_drop_entry(
    entry: &CrystalDropEntry,
    current_tick: u64,
    monster_object_id: u32,
    entry_salt: usize,
) -> Option<Vec<ResolvedDropTemplate>> {
    if !crystal_drop_entry_should_drop(entry, current_tick, monster_object_id, entry_salt) {
        return None;
    }

    if let Some(group) = &entry.group {
        return Some(crystal_resolve_group_drop(
            group,
            current_tick,
            monster_object_id,
            entry_salt,
        ));
    }

    resolved_drop_template_from_crystal_entry(entry, current_tick, monster_object_id, entry_salt)
        .map(|drop| vec![drop])
}

fn crystal_resolve_group_drop(
    group: &mir2_game_data::CrystalDropGroup,
    current_tick: u64,
    monster_object_id: u32,
    entry_salt: usize,
) -> Vec<ResolvedDropTemplate> {
    let mut gold_drops = Vec::new();
    let mut item_drops = Vec::new();

    for (child_index, child) in group.entries.iter().enumerate() {
        let child_salt = crystal_group_child_drop_salt(entry_salt, child_index);
        let Some(resolved) =
            crystal_attempt_drop_entry(child, current_tick, monster_object_id, child_salt)
        else {
            continue;
        };

        for drop in resolved {
            match drop {
                ResolvedDropTemplate::Gold { .. } => gold_drops.push(drop),
                ResolvedDropTemplate::Item { .. } => item_drops.push(drop),
            }
        }

        if group.first {
            break;
        }
    }

    if group.random && !item_drops.is_empty() {
        let selected_index = usize::try_from(deterministic_roll(
            current_tick,
            usize::try_from(monster_object_id).expect("monster object id should fit usize"),
            entry_salt + 700_000,
            u64::try_from(item_drops.len()).expect("item drop count should fit u64"),
        ))
        .expect("random group item index should fit usize");
        gold_drops.push(item_drops.remove(selected_index));
    } else {
        gold_drops.extend(item_drops);
    }

    gold_drops
}

fn crystal_drop_entry_should_drop(
    entry: &CrystalDropEntry,
    current_tick: u64,
    monster_object_id: u32,
    entry_index: usize,
) -> bool {
    match (entry.chance_numerator, entry.chance_denominator) {
        (Some(numerator), Some(denominator)) => deterministic_drop_ratio_roll(
            current_tick,
            monster_object_id,
            u64::try_from(entry_index).expect("entry index should fit u64"),
            numerator,
            denominator,
        ),
        _ => entry.chance_raw == "0",
    }
}

fn deterministic_drop_ratio_roll(
    current_tick: u64,
    object_id: u32,
    salt: u64,
    numerator: u32,
    denominator: u32,
) -> bool {
    if numerator == 0 {
        return false;
    }
    if denominator <= numerator {
        return true;
    }

    deterministic_roll(
        current_tick,
        usize::try_from(object_id).expect("object id should fit usize"),
        usize::try_from(salt).expect("drop salt should fit usize"),
        u64::from(denominator),
    ) < u64::from(numerator)
}

fn crystal_drop_gold_amount(
    base_amount: u32,
    current_tick: u64,
    monster_object_id: u32,
    entry_index: usize,
) -> u32 {
    let lower = base_amount / 2;
    let upper = base_amount.saturating_add(base_amount / 2);
    if upper <= lower {
        return lower;
    }

    lower
        + u32::try_from(deterministic_roll(
            current_tick,
            usize::try_from(monster_object_id).expect("monster object id should fit usize"),
            entry_index + 100_000,
            u64::from(upper - lower),
        ))
        .expect("gold amount roll should fit u32")
}

fn crystal_ground_gold_chunks(gold: u32) -> Vec<u32> {
    let count = if gold / CRYSTAL_MAX_DROP_GOLD == 0 {
        1
    } else {
        gold / CRYSTAL_MAX_DROP_GOLD + 1
    };

    (0..count)
        .map(|index| {
            if index != count - 1 {
                CRYSTAL_MAX_DROP_GOLD
            } else {
                gold % CRYSTAL_MAX_DROP_GOLD
            }
        })
        .collect()
}

fn crystal_drop_item_current_durability(
    max_durability: u16,
    current_tick: u64,
    monster_object_id: u32,
    entry_index: usize,
) -> u16 {
    if max_durability == 0 {
        return 0;
    }

    let roll = deterministic_roll(
        current_tick,
        usize::try_from(monster_object_id).expect("monster object id should fit usize"),
        entry_index + 300_000,
        u64::from(max_durability),
    );
    let current = u32::try_from(roll)
        .expect("item durability roll should fit u32")
        .saturating_add(1000);
    current.min(u32::from(max_durability)) as u16
}

fn crystal_random_item_stat_profile(random_stats_id: u8) -> Option<CrystalRandomItemStatProfile> {
    if random_stats_id == 0 {
        return None;
    }

    mir2_game_data::crystal_random_item_stat_profile(random_stats_id)
}

fn crystal_randomom_range(
    count: u8,
    rate: u8,
    current_tick: u64,
    monster_object_id: u32,
    entry_index: usize,
    salt: usize,
) -> u16 {
    if count == 0 || rate == 0 {
        return 0;
    }

    (0..count)
        .filter(|index| {
            deterministic_roll(
                current_tick,
                usize::try_from(monster_object_id).expect("monster object id should fit usize"),
                entry_index + salt + usize::from(*index),
                u64::from(rate),
            ) == 0
        })
        .count()
        .try_into()
        .expect("random stat roll count should fit u16")
}

fn crystal_roll_random_stat_value(
    roll: CrystalRandomStatRoll,
    current_tick: u64,
    monster_object_id: u32,
    entry_index: usize,
    chance_salt: usize,
    value_salt: usize,
    add_one: bool,
) -> u16 {
    if roll.chance == 0
        || deterministic_roll(
            current_tick,
            usize::try_from(monster_object_id).expect("monster object id should fit usize"),
            entry_index + chance_salt,
            u64::from(roll.chance),
        ) != 0
    {
        return 0;
    }

    let count = if add_one {
        roll.max_stat.saturating_sub(1)
    } else {
        roll.max_stat
    };
    let value = crystal_randomom_range(
        count,
        roll.stat_chance,
        current_tick,
        monster_object_id,
        entry_index,
        value_salt,
    );
    if add_one {
        value.saturating_add(1)
    } else {
        value
    }
}

fn crystal_roll_added_stat(
    stats: &mut Vec<UserItemStat>,
    stat: u8,
    roll: CrystalRandomStatRoll,
    current_tick: u64,
    monster_object_id: u32,
    entry_index: usize,
    chance_salt: usize,
    value_salt: usize,
) {
    let value = crystal_roll_random_stat_value(
        roll,
        current_tick,
        monster_object_id,
        entry_index,
        chance_salt,
        value_salt,
        true,
    );
    if value != 0 {
        stats.push(UserItemStat {
            stat,
            value: i32::from(value),
        });
    }
}

fn crystal_random_drop_stats(
    template: &CrystalItemTemplate,
    current_tick: u64,
    monster_object_id: u32,
    entry_index: usize,
) -> CrystalRandomDropStats {
    let Some(profile) = crystal_random_item_stat_profile(template.random_stats_id) else {
        return CrystalRandomDropStats::default();
    };

    let durability_steps = crystal_roll_random_stat_value(
        profile.max_dura,
        current_tick,
        monster_object_id,
        entry_index,
        400_000,
        410_000,
        false,
    );
    let mut added_stats = Vec::new();
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_MAX_AC,
        profile.max_ac,
        current_tick,
        monster_object_id,
        entry_index,
        420_000,
        430_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_MAX_MAC,
        profile.max_mac,
        current_tick,
        monster_object_id,
        entry_index,
        432_000,
        434_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_MAX_DC,
        profile.max_dc,
        current_tick,
        monster_object_id,
        entry_index,
        440_000,
        450_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_MAX_MC,
        profile.max_mc,
        current_tick,
        monster_object_id,
        entry_index,
        452_000,
        454_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_MAX_SC,
        profile.max_sc,
        current_tick,
        monster_object_id,
        entry_index,
        456_000,
        458_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_ACCURACY,
        profile.accuracy,
        current_tick,
        monster_object_id,
        entry_index,
        460_000,
        462_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_AGILITY,
        profile.agility,
        current_tick,
        monster_object_id,
        entry_index,
        464_000,
        466_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_HP,
        profile.hp,
        current_tick,
        monster_object_id,
        entry_index,
        468_000,
        470_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_MP,
        profile.mp,
        current_tick,
        monster_object_id,
        entry_index,
        472_000,
        474_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_STRONG,
        profile.strong,
        current_tick,
        monster_object_id,
        entry_index,
        476_000,
        478_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_MAGIC_RESIST,
        profile.magic_resist,
        current_tick,
        monster_object_id,
        entry_index,
        480_000,
        482_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_POISON_RESIST,
        profile.poison_resist,
        current_tick,
        monster_object_id,
        entry_index,
        484_000,
        486_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_HEALTH_RECOVERY,
        profile.hp_recovery,
        current_tick,
        monster_object_id,
        entry_index,
        488_000,
        490_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_SPELL_RECOVERY,
        profile.mp_recovery,
        current_tick,
        monster_object_id,
        entry_index,
        492_000,
        494_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_POISON_RECOVERY,
        profile.poison_recovery,
        current_tick,
        monster_object_id,
        entry_index,
        496_000,
        498_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_CRITICAL_RATE,
        profile.critical_rate,
        current_tick,
        monster_object_id,
        entry_index,
        500_000,
        502_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_CRITICAL_DAMAGE,
        profile.critical_damage,
        current_tick,
        monster_object_id,
        entry_index,
        504_000,
        506_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_FREEZING,
        profile.freezing,
        current_tick,
        monster_object_id,
        entry_index,
        508_000,
        510_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_POISON_ATTACK,
        profile.poison_attack,
        current_tick,
        monster_object_id,
        entry_index,
        512_000,
        514_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_ATTACK_SPEED,
        profile.attack_speed,
        current_tick,
        monster_object_id,
        entry_index,
        516_000,
        518_000,
    );
    crystal_roll_added_stat(
        &mut added_stats,
        CRYSTAL_STAT_LUCK,
        profile.luck,
        current_tick,
        monster_object_id,
        entry_index,
        520_000,
        522_000,
    );
    let cursed = profile.curse_chance > 0
        && deterministic_roll(
            current_tick,
            usize::try_from(monster_object_id).expect("monster object id should fit usize"),
            entry_index + 524_000,
            100,
        ) <= u64::from(profile.curse_chance);
    let socket_slots = crystal_roll_random_stat_value(
        profile.slot,
        current_tick,
        monster_object_id,
        entry_index,
        526_000,
        528_000,
        true,
    )
    .max(u16::from(template.slots));

    let added_defence = added_stats
        .iter()
        .find(|stat| stat.stat == CRYSTAL_STAT_MAX_AC)
        .map(|stat| stat.value)
        .unwrap_or_default();
    let added_attack = added_stats
        .iter()
        .find(|stat| stat.stat == CRYSTAL_STAT_MAX_DC)
        .map(|stat| stat.value)
        .unwrap_or_default();

    CrystalRandomDropStats {
        durability_bonus: durability_steps.saturating_mul(1000),
        added_attack,
        added_defence,
        added_stats,
        cursed,
        socket_slots: u8::try_from(socket_slots).expect("socket slot count should fit in u8"),
    }
}

fn resolved_drop_template_from_crystal_entry(
    entry: &CrystalDropEntry,
    current_tick: u64,
    monster_object_id: u32,
    entry_index: usize,
) -> Option<ResolvedDropTemplate> {
    let item_name = entry.item_name.trim();
    let quantity = entry.amount.unwrap_or(1).max(1);
    if item_name.eq_ignore_ascii_case("Gold") {
        return Some(ResolvedDropTemplate::Gold {
            name: "Gold".to_string(),
            amount: crystal_drop_gold_amount(
                quantity,
                current_tick,
                monster_object_id,
                entry_index,
            ),
            quantity: 1,
        });
    }

    let template = crystal_item_by_name(item_name)?;
    let random_stats =
        crystal_random_drop_stats(&template, current_tick, monster_object_id, entry_index);
    let durability_max = template
        .durability
        .saturating_add(random_stats.durability_bonus);
    let current_durability = if durability_max > 0 {
        Some(
            crystal_drop_item_current_durability(
                template.durability,
                current_tick,
                monster_object_id,
                entry_index,
            )
            .saturating_add(random_stats.durability_bonus),
        )
    } else {
        None
    };
    Some(ResolvedDropTemplate::Item {
        key: crystal_item_key_for_template(&template),
        name: template.name,
        description: template
            .tooltip
            .unwrap_or_else(|| "Crystal drop item.".to_string()),
        weight: u16::from(template.weight.max(1)),
        quantity,
        durability_current: current_durability,
        durability_max: (durability_max > 0).then_some(durability_max),
        added_attack: random_stats.added_attack,
        added_defence: random_stats.added_defence,
        added_stats: random_stats.added_stats,
        cursed: random_stats.cursed,
        socket_slots: random_stats.socket_slots,
        item_type: template.item_type,
        show_group_pickup: template.show_group_pickup,
        quest_required: entry
            .modifiers
            .iter()
            .any(|modifier| modifier.eq_ignore_ascii_case("Q")),
    })
}

fn quest_template_matches_drop_item(quest: &QuestTemplate, key: &str, name: &str) -> bool {
    let item = &quest.quest_item;
    item.key.eq_ignore_ascii_case(key)
        || item.name.eq_ignore_ascii_case(name.trim())
        || normalize_crystal_item_key(&item.name).eq_ignore_ascii_case(key)
}

fn try_gain_crystal_quest_drop(
    world: &mut World,
    key: &str,
    name: &str,
    quantity: u32,
    durability_current: Option<u16>,
    durability_max: Option<u16>,
    packets: &mut Vec<ServerPacket>,
) -> bool {
    let quantity = quantity.max(1);
    let mut matched_but_full = false;
    let quest_match = {
        let resources = world.resource::<SimulationResources>();
        resources.quests.iter().find_map(|state| {
            if state.stage != QuestStage::InProgress || state.current >= state.required {
                return None;
            }
            let template = quest_template_by_id(state.quest_id)?;
            if !quest_template_matches_drop_item(&template, key, name) {
                return None;
            }
            if !can_gain_item_quantity(
                resources,
                ItemContainer::Quest,
                &template.quest_item.key,
                quantity,
            ) {
                matched_but_full = true;
                return None;
            }
            Some(template)
        })
    };

    let Some(quest_template) = quest_match else {
        if matched_but_full {
            packets.push(system_message_key(
                world,
                "server.CannotCarryMoreQuestItems",
            ));
        }
        return false;
    };

    let gained_item = add_or_increment_item_with_durability(
        world,
        ItemContainer::Quest,
        &quest_template.quest_item.key,
        &quest_template.quest_item.name,
        &quest_template.quest_item.description,
        quest_template.quest_item.preferred_slot,
        quantity,
        quest_template.quest_item.weight,
        durability_current,
        durability_max,
    );
    packets.push(ServerPacket::GainedItem {
        item: user_item_from_item_state(&gained_item),
    });
    packets.push(system_message_key_args(
        world,
        "sim.youSecuredQuestItem",
        [localized_item_name(
            current_language(world),
            &quest_template.quest_item.key,
            &quest_template.quest_item.name,
        )],
    ));

    let mut progress_update = None;
    {
        let mut resources = world.resource_mut::<SimulationResources>();
        if let Some(quest) = resources
            .quests
            .iter_mut()
            .find(|quest| quest.quest_id == quest_template.quest_id)
        {
            quest.current = quest.current.saturating_add(quantity).min(quest.required);
            if quest.current >= quest.required {
                quest.stage = QuestStage::ReadyToTurnIn;
                progress_update = Some((true, quest.current, quest.required));
            } else {
                progress_update = Some((false, quest.current, quest.required));
            }
        }
    }

    if let Some((ready, current, required)) = progress_update {
        if ready {
            packets.push(system_message_key(world, "sim.questReturnForReward"));
        } else if quest_template.quest_id == GUIDE_QUEST_ID {
            packets.push(system_message_key_args(
                world,
                "sim.questProgressWasps",
                [current.to_string(), required.to_string()],
            ));
        }
    }

    true
}

fn current_player_drop_ownership(world: &World) -> Option<DropOwnership> {
    let player = player_entity(world)?;
    let owner_object_id = entity_object_id(world, player)?;
    let current_tick = world.resource::<SimulationResources>().tick;
    Some(DropOwnership {
        owner_object_id,
        expires_at_tick: current_tick + CRYSTAL_DROP_OWNER_WINDOW_TICKS,
    })
}

fn spawn_configured_monster_drops(
    world: &mut World,
    monster_object_id: u32,
    position: &Point,
    monster_name: &str,
    packets: &mut Vec<ServerPacket>,
) {
    let drops = resolved_monster_drop_templates(world, monster_object_id, monster_name);
    if drops.is_empty() {
        return;
    }

    let ownership = current_player_drop_ownership(world);
    for drop in drops {
        match drop {
            ResolvedDropTemplate::Gold {
                name,
                amount,
                quantity,
            } => {
                let mut dropped_any = false;
                for gold_chunk in crystal_ground_gold_chunks(amount) {
                    if drop_ground_drop_with_ownership(
                        world,
                        position.clone(),
                        CRYSTAL_DROP_RANGE,
                        monster_name,
                        localized_monster_name_key(monster_object_id).map(str::to_string),
                        DropLoot::Gold(gold_chunk),
                        quantity,
                        name.clone(),
                        ownership,
                    )
                    .is_some()
                    {
                        dropped_any = true;
                    }
                }
                if dropped_any {
                    packets.push(system_message_key_args(
                        world,
                        "sim.monsterDroppedGoldOnGround",
                        [
                            monster_name.to_string(),
                            localized_drop_name_key(&name)
                                .map(|key| {
                                    localized_text_or_fallback(current_language(world), key, &name)
                                })
                                .unwrap_or_else(|| name.clone()),
                        ],
                    ));
                }
            }
            ResolvedDropTemplate::Item {
                key,
                name,
                description,
                weight,
                quantity,
                durability_current,
                durability_max,
                added_attack,
                added_defence,
                added_stats,
                cursed,
                socket_slots,
                item_type: _,
                show_group_pickup,
                quest_required,
            } => {
                if quest_required {
                    let _ = try_gain_crystal_quest_drop(
                        world,
                        &key,
                        &name,
                        quantity,
                        durability_current,
                        durability_max,
                        packets,
                    );
                    continue;
                }
                if drop_ground_drop_with_ownership(
                    world,
                    position.clone(),
                    CRYSTAL_DROP_RANGE,
                    monster_name,
                    localized_monster_name_key(monster_object_id).map(str::to_string),
                    DropLoot::InventoryItem {
                        key: key.clone(),
                        name: name.clone(),
                        description: description.clone(),
                        weight,
                        durability_current,
                        durability_max,
                        added_attack,
                        added_defence,
                        added_stats,
                        cursed,
                        socket_slots,
                        show_group_pickup,
                    },
                    quantity,
                    name.clone(),
                    ownership,
                )
                .is_none()
                {
                    return;
                }
                packets.push(system_message_key_args(
                    world,
                    "sim.monsterDroppedItem",
                    [
                        monster_name.to_string(),
                        localized_item_name(current_language(world), &key, &name),
                    ],
                ));
            }
        }
    }
}

fn drop_ownership_allows_pickup(world: &World, drop_entity: Entity, picker_object_id: u32) -> bool {
    let Some(ownership) = world.entity(drop_entity).get::<DropOwnership>() else {
        return true;
    };
    let current_tick = world.resource::<SimulationResources>().tick;
    if current_tick > ownership.expires_at_tick {
        return true;
    }
    if ownership.owner_object_id == picker_object_id {
        return true;
    }
    world
        .resource::<SimulationResources>()
        .group_member_object_ids
        .contains(&ownership.owner_object_id)
}

fn can_gain_gold(resources: &SimulationResources, gold: u32) -> bool {
    u64::from(resources.gold).saturating_add(u64::from(gold)) <= u64::from(u32::MAX)
}

fn pick_up_current_cell_ground_drop(world: &mut World) -> Vec<ServerPacket> {
    if !is_in_world(world) {
        return vec![system_message_key(
            world,
            "sim.joinWorldBeforePickingUpItems",
        )];
    }

    let Some(player) = player_entity(world) else {
        return vec![system_message_key(
            world,
            "sim.joinWorldBeforePickingUpItems",
        )];
    };
    let picker_object_id = entity_object_id(world, player).expect("player object id");
    let candidates = current_cell_ground_drop_candidates(world);
    let mut owner_blocked = false;
    let mut fallback_status = None;

    for (object_id, drop_entity) in candidates {
        match drop_pickup_candidate_status(world, drop_entity, picker_object_id) {
            DropPickupCandidateStatus::Pickable => return pick_up_ground_drop(world, object_id),
            DropPickupCandidateStatus::OwnerBlocked => owner_blocked = true,
            status => {
                fallback_status.get_or_insert(status);
            }
        }
    }

    if owner_blocked {
        return vec![system_message(
            "You cannot pickup items belonging to another player.",
        )];
    }

    match fallback_status {
        Some(DropPickupCandidateStatus::NoFreeSlot | DropPickupCandidateStatus::GoldCapBlocked) => {
            Vec::new()
        }
        Some(DropPickupCandidateStatus::Pickable | DropPickupCandidateStatus::OwnerBlocked)
        | None => Vec::new(),
    }
}

fn pick_up_ground_drop(world: &mut World, object_id: u32) -> Vec<ServerPacket> {
    let Some(drop_entity) = entity_by_object_id(world, object_id) else {
        return vec![system_message_key(world, "sim.itemNoLongerOnGround")];
    };

    if world.entity(drop_entity).get::<GroundDrop>().is_none() {
        return vec![system_message_key(world, "sim.targetNotGroundDrop")];
    }

    let player = player_entity(world).expect("player should exist");
    let player_object_id = entity_object_id(world, player).expect("player object id");
    let player_position = entity_position(world, player).expect("player position");
    let drop_position = entity_position(world, drop_entity).expect("drop position");
    if player_position != drop_position {
        return vec![system_message_key(world, "sim.moveCloserToPickItem")];
    }
    if !drop_ownership_allows_pickup(world, drop_entity, player_object_id) {
        return vec![system_message(
            "You cannot pickup items belonging to another player.",
        )];
    }

    let (display_name, payload) = {
        let entity = world.entity(drop_entity);
        (
            entity
                .get::<DisplayName>()
                .expect("drop name")
                .resolve(current_language(world)),
            entity.get::<DropPayload>().expect("drop payload").clone(),
        )
    };
    let player_name = world
        .entity(player)
        .get::<DisplayName>()
        .map(|name| name.resolve(current_language(world)))
        .unwrap_or_else(|| "Player".to_string());

    match payload.loot {
        DropLoot::Gold(amount) => {
            if !can_gain_gold(world.resource::<SimulationResources>(), amount) {
                return Vec::new();
            }
            world.resource_mut::<SimulationResources>().gold += amount;
            let _ = world.despawn(drop_entity);
            vec![
                ServerPacket::GainedGold { gold: amount },
                system_message_key_args(world, "sim.pickedUpItem", [display_name]),
            ]
        }
        DropLoot::InventoryItem {
            key,
            name,
            description,
            weight,
            durability_current,
            durability_max,
            added_attack,
            added_defence,
            added_stats,
            cursed,
            socket_slots,
            show_group_pickup,
        } => {
            {
                let resources = world.resource::<SimulationResources>();
                if !can_gain_item_quantity(&resources, ItemContainer::Bag1, &key, payload.quantity)
                {
                    return vec![system_message("No free bag slot.")];
                }
            }
            let gained_item = add_or_increment_item_with_random_metadata(
                world,
                ItemContainer::Bag1,
                &key,
                &name,
                &description,
                8,
                payload.quantity,
                weight,
                durability_current,
                durability_max,
                added_attack,
                added_defence,
                added_stats,
                cursed,
                socket_slots,
            );
            let _ = world.despawn(drop_entity);
            let mut packets = vec![ServerPacket::GainedItem {
                item: user_item_from_item_state(&gained_item),
            }];
            if show_group_pickup
                && !world
                    .resource::<SimulationResources>()
                    .group_member_object_ids
                    .is_empty()
            {
                packets.push(ServerPacket::Chat {
                    message: format!("{player_name} Picked up: {{{display_name}}}"),
                    chat_type: ChatType::System,
                });
            }
            packets.push(system_message_key_args(
                world,
                "sim.pickedUpItem",
                [display_name],
            ));
            packets
        }
    }
}

fn find_empty_slot(items: &[ItemState], container: ItemContainer) -> Option<u8> {
    let max_slots = match container {
        ItemContainer::Bag1 | ItemContainer::Bag2 | ItemContainer::Quest => 40,
        ItemContainer::Storage => BASE_STORAGE_SLOTS,
        ItemContainer::Belt => 6,
    };

    (0..max_slots)
        .map(|slot| u8::try_from(slot).expect("slot count should fit in u8"))
        .find(|slot| {
            !items
                .iter()
                .any(|item| item.container == container && item.slot == *slot)
        })
}

fn find_empty_storage_slot(items: &[ItemState], max_slots: u16) -> Option<u8> {
    (0..max_slots)
        .map(|slot| u8::try_from(slot).expect("storage slot count should fit in u8"))
        .find(|slot| !items.iter().any(|item| item.slot == *slot))
}

fn storage_locked(world: &World) -> bool {
    let resources = world.resource::<SimulationResources>();
    storage_password_required(
        &resources.config,
        resources.storage_has_password,
        resources.storage_unlocked,
    )
}

fn active_crystal_storage_service(resources: &SimulationResources) -> bool {
    resources
        .active_npc_service
        .as_ref()
        .is_some_and(|service| service.label_key == "STORAGE")
}

fn is_valid_inventory_slot(slot: u8) -> bool {
    slot < 40
}

fn store_item_impl(world: &mut World, from: i32, to: i32) -> Vec<ServerPacket> {
    let failed_packet = ServerPacket::StoreItem {
        from,
        to,
        success: false,
    };

    {
        let resources = world.resource::<SimulationResources>();
        if !active_crystal_storage_service(&resources) {
            return vec![failed_packet];
        }
    }

    if storage_locked(world) {
        return vec![failed_packet];
    }
    let Some(from_slot) = u8::try_from(from).ok() else {
        return vec![failed_packet];
    };
    let Some(to_slot) = u8::try_from(to).ok() else {
        return vec![failed_packet];
    };

    {
        let mut resources = world.resource_mut::<SimulationResources>();
        if !is_valid_inventory_slot(from_slot) || !is_valid_storage_slot(&resources, to_slot) {
            return vec![failed_packet];
        }
        let Some(index) = resources.inventory_items.iter().position(|item| {
            item.slot == from_slot
                && matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2)
        }) else {
            return vec![failed_packet];
        };

        if crystal_item_has_bind_flag(
            &resources.inventory_items[index].key,
            CRYSTAL_BIND_DONT_STORE,
        ) {
            return vec![failed_packet];
        }

        if resources
            .storage_items
            .iter()
            .any(|item| item.slot == to_slot)
        {
            return vec![failed_packet];
        }

        let mut item = resources.inventory_items.remove(index);
        item.slot = to_slot;
        item.container = ItemContainer::Storage;
        resources.storage_items.push(item);
    }

    vec![ServerPacket::StoreItem {
        from,
        to,
        success: true,
    }]
}

fn take_back_item_impl(world: &mut World, from: i32, to: i32) -> Vec<ServerPacket> {
    let failed_packet = ServerPacket::TakeBackItem {
        from,
        to,
        success: false,
    };

    {
        let resources = world.resource::<SimulationResources>();
        if !active_crystal_storage_service(&resources) {
            return vec![failed_packet];
        }
    }

    if storage_locked(world) {
        return vec![failed_packet];
    }
    let Some(from_slot) = u8::try_from(from).ok() else {
        return vec![failed_packet];
    };
    let Some(to_slot) = u8::try_from(to).ok() else {
        return vec![failed_packet];
    };

    {
        let mut resources = world.resource_mut::<SimulationResources>();
        if !is_valid_storage_slot(&resources, from_slot) || !is_valid_inventory_slot(to_slot) {
            return vec![failed_packet];
        }
        let Some(index) = resources
            .storage_items
            .iter()
            .position(|item| item.slot == from_slot)
        else {
            return vec![failed_packet];
        };

        if resources
            .inventory_items
            .iter()
            .any(|item| item.slot == to_slot && item.container == ItemContainer::Bag1)
        {
            return vec![failed_packet];
        }

        let mut item = resources.storage_items.remove(index);
        item.slot = to_slot;
        item.container = ItemContainer::Bag1;
        resources.inventory_items.push(item);
    }

    vec![ServerPacket::TakeBackItem {
        from,
        to,
        success: true,
    }]
}

enum CombineItemOutcome {
    AckOnlyFailure,
    FailureHint {
        key: &'static str,
        args: Vec<String>,
    },
    SocketSuccess {
        unique_id: u64,
        slot_size: i32,
    },
    SealSuccess {
        unique_id: u64,
        expiry_date_binary_datetime: i64,
        minutes: u64,
    },
}

fn combine_item_impl(
    world: &mut World,
    grid: MirGridType,
    id_from: u64,
    id_to: u64,
) -> Vec<ServerPacket> {
    let failed_packet = ServerPacket::CombineItem {
        grid,
        id_from,
        id_to,
        success: false,
        destroy: false,
    };

    if grid != MirGridType::Inventory {
        return vec![failed_packet];
    }

    let Some(from_slot) = u8::try_from(id_from).ok() else {
        return vec![failed_packet];
    };
    let Some(to_slot) = u8::try_from(id_to).ok() else {
        return vec![failed_packet];
    };

    let now_binary_datetime = current_binary_datetime();
    let now_ticks = binary_datetime_ticks(now_binary_datetime);
    let outcome = {
        let mut resources = world.resource_mut::<SimulationResources>();
        let Some(from_index) = resources.inventory_items.iter().position(|item| {
            item.slot == from_slot
                && matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2)
        }) else {
            return vec![failed_packet];
        };
        let Some(to_index) = resources.inventory_items.iter().position(|item| {
            item.slot == to_slot
                && matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2)
        }) else {
            return vec![failed_packet];
        };
        if from_index == to_index {
            return vec![failed_packet];
        }

        let source_item = resources.inventory_items[from_index].clone();
        let target_key = resources.inventory_items[to_index].key.clone();
        let Some(target_template) = crystal_item_template_for_item_key(&target_key) else {
            return vec![failed_packet];
        };

        let source_shape = if source_item.key == "stage5-socket-source" {
            Some(CRYSTAL_GEM_SHAPE_SOCKET)
        } else if source_item.key == "stage5-seal-source" {
            Some(CRYSTAL_GEM_SHAPE_SEAL)
        } else {
            crystal_item_template_for_item_key(&source_item.key).and_then(|template| {
                (template.item_type == CRYSTAL_ITEM_TYPE_GEM
                    && (template.shape == CRYSTAL_GEM_SHAPE_SOCKET
                        || template.shape == CRYSTAL_GEM_SHAPE_SEAL))
                    .then_some(template.shape)
            })
        };

        match source_shape {
            Some(CRYSTAL_GEM_SHAPE_SOCKET) => {
                if crystal_item_has_bind_flag(&target_key, CRYSTAL_BIND_DONT_UPGRADE)
                    || target_template.unique != 0
                {
                    CombineItemOutcome::AckOnlyFailure
                } else if !crystal_socket_source_valid_for_item(&source_item, &target_key) {
                    CombineItemOutcome::FailureHint {
                        key: "server.InvalidCombination",
                        args: Vec::new(),
                    }
                } else if target_template.slots == 0
                    || resources.inventory_items[to_index].socket_slots >= target_template.slots
                {
                    CombineItemOutcome::FailureHint {
                        key: "server.ItemMaxSockets",
                        args: Vec::new(),
                    }
                } else {
                    resources.inventory_items[to_index].socket_slots = resources.inventory_items
                        [to_index]
                        .socket_slots
                        .saturating_add(1);
                    let unique_id = u64::from(resources.inventory_items[to_index].slot);
                    let slot_size = i32::from(resources.inventory_items[to_index].socket_slots);
                    if resources.inventory_items[from_index].quantity > 1 {
                        resources.inventory_items[from_index].quantity -= 1;
                    } else {
                        resources.inventory_items.remove(from_index);
                    }
                    CombineItemOutcome::SocketSuccess {
                        unique_id,
                        slot_size,
                    }
                }
            }
            Some(CRYSTAL_GEM_SHAPE_SEAL) => {
                if crystal_item_has_bind_flag(&target_key, CRYSTAL_BIND_DONT_UPGRADE)
                    || target_template.unique != 0
                {
                    CombineItemOutcome::AckOnlyFailure
                } else if resources.inventory_items[to_index].sealed_expiry_time_binary_datetime
                    != 0
                    && binary_datetime_ticks(
                        resources.inventory_items[to_index].sealed_expiry_time_binary_datetime,
                    ) > now_ticks
                {
                    CombineItemOutcome::FailureHint {
                        key: "server.ItemAlreadySealed",
                        args: Vec::new(),
                    }
                } else if resources.inventory_items[to_index].sealed_next_time_binary_datetime != 0
                    && binary_datetime_ticks(
                        resources.inventory_items[to_index].sealed_next_time_binary_datetime,
                    ) > now_ticks
                {
                    let remaining_ticks = binary_datetime_ticks(
                        resources.inventory_items[to_index].sealed_next_time_binary_datetime,
                    ) - now_ticks;
                    let remaining_seconds =
                        u64::try_from((remaining_ticks + 9_999_999) / 10_000_000).unwrap_or(1);
                    CombineItemOutcome::FailureHint {
                        key: "server.ItemCannotBeResealedFor",
                        args: vec![crystal_duration_label_from_seconds(
                            remaining_seconds.max(1),
                        )],
                    }
                } else {
                    let Some(minutes) = crystal_seal_minutes_for_source_item(&source_item, 1)
                    else {
                        return vec![failed_packet];
                    };
                    let expiry_date_binary_datetime = future_binary_datetime_minutes(minutes);
                    let next_seal_binary_datetime = add_minutes_to_binary_datetime(
                        expiry_date_binary_datetime,
                        CRYSTAL_ITEM_SEAL_DELAY_MINUTES,
                    );
                    resources.inventory_items[to_index].sealed_expiry_time_binary_datetime =
                        expiry_date_binary_datetime;
                    resources.inventory_items[to_index].sealed_next_time_binary_datetime =
                        next_seal_binary_datetime;
                    let unique_id = u64::from(resources.inventory_items[to_index].slot);
                    if resources.inventory_items[from_index].quantity > 1 {
                        resources.inventory_items[from_index].quantity -= 1;
                    } else {
                        resources.inventory_items.remove(from_index);
                    }
                    CombineItemOutcome::SealSuccess {
                        unique_id,
                        expiry_date_binary_datetime,
                        minutes,
                    }
                }
            }
            _ => CombineItemOutcome::AckOnlyFailure,
        }
    };

    match outcome {
        CombineItemOutcome::AckOnlyFailure => vec![failed_packet],
        CombineItemOutcome::FailureHint { key, args } => {
            let message = if args.is_empty() {
                hint_chat_key(world, key)
            } else {
                hint_chat_key_args(world, key, args)
            };
            vec![message, failed_packet]
        }
        CombineItemOutcome::SocketSuccess {
            unique_id,
            slot_size,
        } => vec![
            hint_chat_key(world, "server.ItemSocketsIncreased"),
            ServerPacket::ItemSlotSizeChanged {
                unique_id,
                slot_size,
            },
            ServerPacket::CombineItem {
                grid,
                id_from,
                id_to,
                success: true,
                destroy: false,
            },
        ],
        CombineItemOutcome::SealSuccess {
            unique_id,
            expiry_date_binary_datetime,
            minutes,
        } => vec![
            hint_chat_key_args(
                world,
                "server.ItemSealedFor",
                [crystal_duration_label_from_minutes(minutes)],
            ),
            ServerPacket::ItemSealChanged {
                unique_id,
                expiry_date_binary_datetime,
            },
            ServerPacket::CombineItem {
                grid,
                id_from,
                id_to,
                success: true,
                destroy: false,
            },
        ],
    }
}

fn add_equipment_back_to_bag(world: &mut World, equipment: EquipmentState, preferred_slot: u8) {
    let mut resources = world.resource_mut::<SimulationResources>();
    let slot =
        find_empty_slot(&resources.inventory_items, ItemContainer::Bag1).unwrap_or(preferred_slot);
    resources.inventory_items.push(ItemState {
        key: equipment.key,
        name: equipment.name,
        icon: equipment.icon,
        slot,
        container: ItemContainer::Bag1,
        quantity: 1,
        description: equipment.description,
        durability_current: Some(equipment.durability_current),
        durability_max: Some(equipment.durability_max),
        weight: 1,
        equip_slot: Some(equipment.slot),
        grade: equipment.grade,
        added_attack: equipment.added_attack,
        added_defence: equipment.added_defence,
        added_stats: equipment.added_stats,
        cursed: equipment.cursed,
        socket_slots: equipment.socket_slots,
        sealed_expiry_time_binary_datetime: equipment.sealed_expiry_time_binary_datetime,
        sealed_next_time_binary_datetime: equipment.sealed_next_time_binary_datetime,
        attack: equipment.attack,
        defence: equipment.defence,
        heal_hp: 0,
        heal_mp: 0,
    });
}

fn equipment_slot_key(slot: EquipmentSlot) -> &'static str {
    match slot {
        EquipmentSlot::Weapon => "weapon",
        EquipmentSlot::Armour => "armour",
        EquipmentSlot::Helmet => "helmet",
        EquipmentSlot::Mount => "mount",
        EquipmentSlot::Necklace => "necklace",
        EquipmentSlot::Torch => "torch",
        EquipmentSlot::BraceletLeft => "bracelet-left",
        EquipmentSlot::BraceletRight => "bracelet-right",
        EquipmentSlot::RingLeft => "ring-left",
        EquipmentSlot::RingRight => "ring-right",
        EquipmentSlot::Amulet => "amulet",
        EquipmentSlot::Boots => "boots",
        EquipmentSlot::Belt => "belt",
        EquipmentSlot::Stone => "stone",
    }
}

fn equipment_slot_from_index(index: i32) -> Option<EquipmentSlot> {
    match index {
        0 => Some(EquipmentSlot::Weapon),
        1 => Some(EquipmentSlot::Armour),
        2 => Some(EquipmentSlot::Helmet),
        3 => Some(EquipmentSlot::Torch),
        4 => Some(EquipmentSlot::Necklace),
        5 => Some(EquipmentSlot::BraceletLeft),
        6 => Some(EquipmentSlot::BraceletRight),
        7 => Some(EquipmentSlot::RingLeft),
        8 => Some(EquipmentSlot::RingRight),
        9 => Some(EquipmentSlot::Amulet),
        10 => Some(EquipmentSlot::Belt),
        11 => Some(EquipmentSlot::Boots),
        12 => Some(EquipmentSlot::Stone),
        13 => Some(EquipmentSlot::Mount),
        _ => None,
    }
}

fn equipment_slot_from_stage5_arg(value: &str) -> Option<EquipmentSlot> {
    if let Ok(index) = value.parse::<i32>() {
        return equipment_slot_from_index(index);
    }

    match value.trim().replace('_', "-").to_ascii_lowercase().as_str() {
        "weapon" => Some(EquipmentSlot::Weapon),
        "armour" | "armor" => Some(EquipmentSlot::Armour),
        "helmet" => Some(EquipmentSlot::Helmet),
        "torch" => Some(EquipmentSlot::Torch),
        "necklace" => Some(EquipmentSlot::Necklace),
        "bracelet-left" => Some(EquipmentSlot::BraceletLeft),
        "bracelet-right" => Some(EquipmentSlot::BraceletRight),
        "ring-left" => Some(EquipmentSlot::RingLeft),
        "ring-right" => Some(EquipmentSlot::RingRight),
        "amulet" => Some(EquipmentSlot::Amulet),
        "belt" => Some(EquipmentSlot::Belt),
        "boots" => Some(EquipmentSlot::Boots),
        "stone" => Some(EquipmentSlot::Stone),
        "mount" => Some(EquipmentSlot::Mount),
        _ => None,
    }
}

fn equipment_slot_index(slot: EquipmentSlot) -> Option<usize> {
    match slot {
        EquipmentSlot::Weapon => Some(0),
        EquipmentSlot::Armour => Some(1),
        EquipmentSlot::Helmet => Some(2),
        EquipmentSlot::Torch => Some(3),
        EquipmentSlot::Necklace => Some(4),
        EquipmentSlot::BraceletLeft => Some(5),
        EquipmentSlot::BraceletRight => Some(6),
        EquipmentSlot::RingLeft => Some(7),
        EquipmentSlot::RingRight => Some(8),
        EquipmentSlot::Amulet => Some(9),
        EquipmentSlot::Belt => Some(10),
        EquipmentSlot::Boots => Some(11),
        EquipmentSlot::Stone => Some(12),
        EquipmentSlot::Mount => Some(13),
    }
}

fn equipment_slot_unique_id(slot: EquipmentSlot) -> Option<u64> {
    equipment_slot_index(slot).and_then(|index| u64::try_from(index).ok())
}

fn slugify_name(name: &str) -> String {
    name.chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() {
                ch.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect::<String>()
        .trim_matches('-')
        .split('-')
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join("-")
}

#[derive(Debug, Clone, Copy)]
enum UseItemLocation {
    Inventory(usize),
    Belt(usize),
}

fn find_use_item_location(
    resources: &SimulationResources,
    key: &str,
    packet_ack: Option<(u64, MirGridType)>,
) -> Option<UseItemLocation> {
    match packet_ack.map(|(_, grid)| grid) {
        Some(MirGridType::Belt) => resources
            .belt_items
            .iter()
            .position(|item| item.key == key)
            .map(UseItemLocation::Belt),
        _ => resources
            .inventory_items
            .iter()
            .position(|item| item.key == key)
            .map(UseItemLocation::Inventory),
    }
}

fn item_at_use_location(
    resources: &SimulationResources,
    location: UseItemLocation,
) -> Option<ItemState> {
    match location {
        UseItemLocation::Inventory(index) => resources.inventory_items.get(index),
        UseItemLocation::Belt(index) => resources.belt_items.get(index),
    }
    .cloned()
}

fn consume_item_at_use_location(world: &mut World, location: UseItemLocation) {
    let mut resources = world.resource_mut::<SimulationResources>();
    let items = match location {
        UseItemLocation::Inventory(_) => &mut resources.inventory_items,
        UseItemLocation::Belt(_) => &mut resources.belt_items,
    };
    let index = match location {
        UseItemLocation::Inventory(index) | UseItemLocation::Belt(index) => index,
    };
    if let Some(item) = items.get_mut(index) {
        if item.quantity > 1 {
            item.quantity -= 1;
        } else {
            items.remove(index);
        }
    }
}

fn use_item(
    world: &mut World,
    key: &str,
    packet_ack: Option<(u64, MirGridType)>,
) -> Vec<ServerPacket> {
    let location = {
        let resources = world.resource::<SimulationResources>();
        find_use_item_location(resources, key, packet_ack)
    };

    let Some(location) = location else {
        return prepend_optional_packet(
            use_item_ack(packet_ack, false),
            vec![system_message_key(world, "sim.itemNotFoundInBag")],
        );
    };

    let Some(item) = item_at_use_location(world.resource::<SimulationResources>(), location) else {
        return prepend_optional_packet(
            use_item_ack(packet_ack, false),
            vec![system_message_key(world, "sim.itemNotFoundInBag")],
        );
    };
    let mut packets = Vec::new();

    if let Some(slot) = item.equip_slot {
        let UseItemLocation::Inventory(index) = location else {
            packets.push(system_message(
                "That item cannot be equipped from this grid.",
            ));
            return prepend_optional_packet(use_item_ack(packet_ack, false), packets);
        };
        let replaced = equip_inventory_item(world, index, slot, &item);
        if replaced {
            packets.push(system_message_key_args(
                world,
                "sim.equippedItemAndReturnedPrevious",
                [localized_item_name(
                    current_language(world),
                    &item.key,
                    &item.name,
                )],
            ));
        } else {
            packets.push(system_message_key_args(
                world,
                "sim.equippedItem",
                [localized_item_name(
                    current_language(world),
                    &item.key,
                    &item.name,
                )],
            ));
        }
        return prepend_optional_packet(use_item_ack(packet_ack, true), packets);
    }

    if item.key == "town-teleport" {
        if let Some(player) = player_entity(world) {
            let spawn = world.resource::<SimulationResources>().config.spawn.clone();
            world
                .entity_mut(player)
                .insert((Position(spawn), Facing(MirDirection::Down)));
        }
        consume_item_at_use_location(world, location);
        packets.push(ServerPacket::UserLocation {
            location: current_location(world),
        });
        packets.push(system_message_key(world, "sim.townTeleportReturnedToSpawn"));
        return prepend_optional_packet(use_item_ack(packet_ack, true), packets);
    }

    if item.key == "repair-powder" {
        let repair_packets = repair_equipped_durability(world);
        let repaired_count = repair_packets.len();
        if repaired_count == 0 {
            packets.push(system_message_key(world, "sim.noEquipmentNeedsRepair"));
            return prepend_optional_packet(use_item_ack(packet_ack, false), packets);
        }

        consume_item_at_use_location(world, location);
        packets.extend(repair_packets);
        packets.push(system_message_key_args(
            world,
            "sim.repairedEquippedItems",
            [repaired_count.to_string()],
        ));
        return prepend_optional_packet(use_item_ack(packet_ack, true), packets);
    }

    if item.key == "benediction-oil" {
        let Some(outcome) = try_luck_weapon(world) else {
            packets.push(system_message("No equipped weapon can be blessed."));
            return prepend_optional_packet(use_item_ack(packet_ack, false), packets);
        };

        consume_item_at_use_location(world, location);
        match outcome {
            CrystalLuckWeaponOutcome::Changed {
                refresh_packet,
                message,
                chat_type,
            } => {
                packets.push(refresh_packet);
                packets.push(ServerPacket::Chat {
                    message: message.to_string(),
                    chat_type,
                });
            }
            CrystalLuckWeaponOutcome::NoEffect { message } => {
                packets.push(ServerPacket::Chat {
                    message: message.to_string(),
                    chat_type: ChatType::Hint,
                });
            }
        }
        return prepend_optional_packet(use_item_ack(packet_ack, true), packets);
    }

    if item.key == "repair-oil" || item.key == "war-god-oil" {
        let full_repair = item.key == "war-god-oil";
        let Some(repair_packet) = repair_equipped_weapon_with_oil(world, full_repair) else {
            packets.push(system_message("Your equipped weapon does not need repair."));
            return prepend_optional_packet(use_item_ack(packet_ack, false), packets);
        };

        consume_item_at_use_location(world, location);
        packets.push(repair_packet);
        packets.push(system_message("Your weapon has been repaired."));
        return prepend_optional_packet(use_item_ack(packet_ack, true), packets);
    }

    if let Some(credit) = crystal_credit_value_for_item(&item) {
        consume_item_at_use_location(world, location);
        if let Some(packet) = gain_credit(world, credit) {
            packets.push(packet);
        }
        packets.push(system_message(&format!(
            "{credit} Credits have been added to your Account."
        )));
        return prepend_optional_packet(use_item_ack(packet_ack, true), packets);
    }

    if item.heal_hp > 0 || item.heal_mp > 0 {
        if let Some(player) = player_entity(world) {
            let mut entity = world.entity_mut(player);
            let mut vitals = entity.get_mut::<PlayerVitals>().expect("player vitals");
            vitals.hp = (vitals.hp + item.heal_hp).min(vitals.max_hp);
            vitals.mp = (vitals.mp + item.heal_mp).min(100);
        }

        consume_item_at_use_location(world, location);
        packets.push(system_message_key_args(
            world,
            "sim.usedItem",
            [localized_item_name(
                current_language(world),
                &item.key,
                &item.name,
            )],
        ));
        return prepend_optional_packet(use_item_ack(packet_ack, true), packets);
    }

    packets.push(system_message_key(world, "sim.itemNoActiveUse"));
    prepend_optional_packet(use_item_ack(packet_ack, false), packets)
}

fn prepend_packet(packet: ServerPacket, mut packets: Vec<ServerPacket>) -> Vec<ServerPacket> {
    let mut result = Vec::with_capacity(packets.len() + 1);
    result.push(packet);
    result.append(&mut packets);
    result
}

fn prepend_optional_packet(
    packet: Option<ServerPacket>,
    packets: Vec<ServerPacket>,
) -> Vec<ServerPacket> {
    match packet {
        Some(packet) => prepend_packet(packet, packets),
        None => packets,
    }
}

fn use_item_ack(packet_ack: Option<(u64, MirGridType)>, success: bool) -> Option<ServerPacket> {
    packet_ack.map(|(unique_id, grid)| ServerPacket::UseItem {
        unique_id,
        success,
        grid,
    })
}

fn move_item_impl(world: &mut World, grid: MirGridType, from: i32, to: i32) -> Vec<ServerPacket> {
    if matches!(grid, MirGridType::Storage) && storage_locked(world) {
        return vec![
            ServerPacket::MoveItem {
                grid,
                from,
                to,
                success: false,
            },
            system_message("Storage is locked."),
        ];
    }
    let Some(to_slot) = u8::try_from(to).ok() else {
        return vec![
            ServerPacket::MoveItem {
                grid,
                from,
                to,
                success: false,
            },
            system_message("Invalid target item slot."),
        ];
    };
    let Some(from_slot) = u8::try_from(from).ok() else {
        return vec![
            ServerPacket::MoveItem {
                grid,
                from,
                to,
                success: false,
            },
            system_message("Invalid source item slot."),
        ];
    };

    if matches!(grid, MirGridType::Storage) {
        let resources = world.resource::<SimulationResources>();
        if !is_valid_storage_slot(&resources, from_slot)
            || !is_valid_storage_slot(&resources, to_slot)
        {
            return vec![
                ServerPacket::MoveItem {
                    grid,
                    from,
                    to,
                    success: false,
                },
                system_message("Invalid target item slot."),
            ];
        }
    }

    let mut resources = world.resource_mut::<SimulationResources>();
    let items = match grid {
        MirGridType::Belt => &mut resources.belt_items,
        MirGridType::Inventory | MirGridType::QuestInventory => &mut resources.inventory_items,
        MirGridType::Storage => &mut resources.storage_items,
        _ => {
            return vec![
                ServerPacket::MoveItem {
                    grid,
                    from,
                    to,
                    success: false,
                },
                system_message("That item grid cannot be moved yet."),
            ];
        }
    };

    let Some(index) = items.iter().position(|item| item.slot == from_slot) else {
        return vec![
            ServerPacket::MoveItem {
                grid,
                from,
                to,
                success: false,
            },
            system_message_key(world, "sim.itemNotFoundInBag"),
        ];
    };

    if let Some(other_index) = items
        .iter()
        .position(|item| item.slot == to_slot && item.container == items[index].container)
    {
        items[other_index].slot = from_slot;
    }
    items[index].slot = to_slot;

    vec![
        ServerPacket::MoveItem {
            grid,
            from,
            to,
            success: true,
        },
        system_message("Item slot updated."),
    ]
}

fn merge_item_impl(
    world: &mut World,
    grid_from: MirGridType,
    grid_to: MirGridType,
    id_from: u64,
    id_to: u64,
) -> Vec<ServerPacket> {
    if matches!(grid_from, MirGridType::Storage) && storage_locked(world) {
        return vec![
            ServerPacket::MergeItem {
                grid_from,
                grid_to,
                id_from,
                id_to,
                success: false,
            },
            system_message("Storage is locked."),
        ];
    }
    if grid_from != grid_to {
        return vec![
            ServerPacket::MergeItem {
                grid_from,
                grid_to,
                id_from,
                id_to,
                success: false,
            },
            system_message("Cross-grid item merge is not available yet."),
        ];
    }

    let Some(from_slot) = u8::try_from(id_from).ok() else {
        return vec![
            ServerPacket::MergeItem {
                grid_from,
                grid_to,
                id_from,
                id_to,
                success: false,
            },
            system_message("Invalid source item slot."),
        ];
    };
    let Some(to_slot) = u8::try_from(id_to).ok() else {
        return vec![
            ServerPacket::MergeItem {
                grid_from,
                grid_to,
                id_from,
                id_to,
                success: false,
            },
            system_message("Invalid target item slot."),
        ];
    };

    if matches!(grid_from, MirGridType::Storage) {
        let resources = world.resource::<SimulationResources>();
        if !is_valid_storage_slot(&resources, from_slot)
            || !is_valid_storage_slot(&resources, to_slot)
        {
            return vec![
                ServerPacket::MergeItem {
                    grid_from,
                    grid_to,
                    id_from,
                    id_to,
                    success: false,
                },
                system_message("Invalid target item slot."),
            ];
        }
    }

    let mut resources = world.resource_mut::<SimulationResources>();
    let items = match grid_from {
        MirGridType::Belt => &mut resources.belt_items,
        MirGridType::Inventory | MirGridType::QuestInventory => &mut resources.inventory_items,
        MirGridType::Storage => &mut resources.storage_items,
        _ => {
            return vec![
                ServerPacket::MergeItem {
                    grid_from,
                    grid_to,
                    id_from,
                    id_to,
                    success: false,
                },
                system_message("That item grid cannot be merged yet."),
            ];
        }
    };

    let Some(from_index) = items.iter().position(|item| item.slot == from_slot) else {
        return vec![
            ServerPacket::MergeItem {
                grid_from,
                grid_to,
                id_from,
                id_to,
                success: false,
            },
            system_message_key(world, "sim.itemNotFoundInBag"),
        ];
    };
    let Some(to_index) = items.iter().position(|item| item.slot == to_slot) else {
        return vec![
            ServerPacket::MergeItem {
                grid_from,
                grid_to,
                id_from,
                id_to,
                success: false,
            },
            system_message_key(world, "sim.itemNotFoundInBag"),
        ];
    };
    if from_index == to_index || items[from_index].key != items[to_index].key {
        return vec![
            ServerPacket::MergeItem {
                grid_from,
                grid_to,
                id_from,
                id_to,
                success: false,
            },
            system_message("Only matching item stacks can be merged."),
        ];
    }
    let max_stack = crystal_stack_size_for_item_key(&items[to_index].key);
    if max_stack <= 1 || items[to_index].quantity >= max_stack {
        return vec![
            ServerPacket::MergeItem {
                grid_from,
                grid_to,
                id_from,
                id_to,
                success: false,
            },
            system_message("Only matching item stacks can be merged."),
        ];
    }

    let quantity = items[from_index].quantity;
    let available_space = max_stack - items[to_index].quantity;
    if quantity <= available_space {
        items[to_index].quantity += quantity;
        items.remove(from_index);
    } else {
        items[from_index].quantity -= available_space;
        items[to_index].quantity = max_stack;
    }

    vec![
        ServerPacket::MergeItem {
            grid_from,
            grid_to,
            id_from,
            id_to,
            success: true,
        },
        system_message("Item stacks merged."),
    ]
}

fn split_item_impl(
    world: &mut World,
    grid: MirGridType,
    unique_id: u64,
    count: u16,
) -> Vec<ServerPacket> {
    if matches!(grid, MirGridType::Storage) && storage_locked(world) {
        return vec![
            ServerPacket::SplitItem1 {
                grid,
                unique_id,
                count,
                success: false,
            },
            system_message("Storage is locked."),
        ];
    }
    if count == 0 {
        return vec![
            ServerPacket::SplitItem1 {
                grid,
                unique_id,
                count,
                success: false,
            },
            system_message("Split count must be greater than zero."),
        ];
    }
    let Some(slot) = u8::try_from(unique_id).ok() else {
        return vec![
            ServerPacket::SplitItem1 {
                grid,
                unique_id,
                count,
                success: false,
            },
            system_message("Invalid item slot."),
        ];
    };

    let container = match grid {
        MirGridType::Belt => ItemContainer::Belt,
        MirGridType::QuestInventory => ItemContainer::Quest,
        MirGridType::Storage => ItemContainer::Storage,
        _ => ItemContainer::Bag1,
    };
    let mut resources = world.resource_mut::<SimulationResources>();
    if matches!(grid, MirGridType::Storage) && !is_valid_storage_slot(&resources, slot) {
        return vec![
            ServerPacket::SplitItem1 {
                grid,
                unique_id,
                count,
                success: false,
            },
            system_message("Invalid item slot."),
        ];
    }
    let storage_slot_limit = accessible_storage_size(&resources);
    let items = match grid {
        MirGridType::Belt => &mut resources.belt_items,
        MirGridType::Storage => &mut resources.storage_items,
        _ => &mut resources.inventory_items,
    };
    let Some(index) = items
        .iter()
        .position(|item| item.slot == slot && item.container == container)
    else {
        return vec![
            ServerPacket::SplitItem1 {
                grid,
                unique_id,
                count,
                success: false,
            },
            system_message_key(world, "sim.itemNotFoundInBag"),
        ];
    };
    if items[index].quantity <= u32::from(count) {
        return vec![
            ServerPacket::SplitItem1 {
                grid,
                unique_id,
                count,
                success: false,
            },
            system_message("Not enough items in that stack."),
        ];
    }
    let next_slot = if matches!(grid, MirGridType::Storage) {
        find_empty_storage_slot(items, storage_slot_limit)
    } else {
        find_empty_slot(items, container)
    };
    let Some(next_slot) = next_slot else {
        return vec![
            ServerPacket::SplitItem1 {
                grid,
                unique_id,
                count,
                success: false,
            },
            system_message("No free slot for split stack."),
        ];
    };

    items[index].quantity -= u32::from(count);
    let mut split = items[index].clone();
    split.slot = next_slot;
    split.quantity = u32::from(count);
    let split_packet_item = user_item_from_item_state(&split);
    items.push(split);

    vec![
        ServerPacket::SplitItem1 {
            grid,
            unique_id,
            count,
            success: true,
        },
        ServerPacket::SplitItem {
            item: Some(split_packet_item),
            grid,
        },
        system_message("Item stack split."),
    ]
}

fn equip_item_by_key_impl(
    world: &mut World,
    grid: MirGridType,
    unique_id: u64,
    key: &str,
    to: i32,
) -> Vec<ServerPacket> {
    let item_index = {
        let resources = world.resource::<SimulationResources>();
        resources
            .inventory_items
            .iter()
            .position(|item| item.key == key)
    };
    let Some(index) = item_index else {
        return vec![
            ServerPacket::EquipItem {
                grid,
                unique_id,
                to,
                success: false,
            },
            system_message_key(world, "sim.itemNotFoundInBag"),
        ];
    };

    let item = world.resource::<SimulationResources>().inventory_items[index].clone();
    let Some(slot) = item.equip_slot.or_else(|| equipment_slot_from_index(to)) else {
        return vec![
            ServerPacket::EquipItem {
                grid,
                unique_id,
                to,
                success: false,
            },
            system_message("That item cannot be equipped."),
        ];
    };

    let replaced = equip_inventory_item(world, index, slot, &item);
    if replaced {
        vec![
            ServerPacket::EquipItem {
                grid,
                unique_id,
                to,
                success: true,
            },
            system_message_key_args(
                world,
                "sim.equippedItemAndReturnedPrevious",
                [localized_item_name(
                    current_language(world),
                    &item.key,
                    &item.name,
                )],
            ),
        ]
    } else {
        vec![
            ServerPacket::EquipItem {
                grid,
                unique_id,
                to,
                success: true,
            },
            system_message_key_args(
                world,
                "sim.equippedItem",
                [localized_item_name(
                    current_language(world),
                    &item.key,
                    &item.name,
                )],
            ),
        ]
    }
}

fn remove_equipped_item_state(
    world: &mut World,
    unique_id: u64,
    to: i32,
) -> Result<String, ServerPacket> {
    let Some(key) = item_key_for_equipment_reference(world, unique_id) else {
        return Err(system_message("Equipped item was not found."));
    };
    let preferred_slot = u8::try_from(to).unwrap_or(0);

    let equipment = {
        let mut resources = world.resource_mut::<SimulationResources>();
        let Some(index) = resources
            .equipment_items
            .iter()
            .position(|item| item.key == key)
        else {
            return Err(system_message("Equipped item was not found."));
        };
        resources.equipment_items.remove(index)
    };
    let name = localized_item_name(current_language(world), &equipment.key, &equipment.name);
    add_equipment_back_to_bag(world, equipment, preferred_slot);

    Ok(name)
}

fn remove_equipped_item_impl(
    world: &mut World,
    grid: MirGridType,
    unique_id: u64,
    to: i32,
) -> Vec<ServerPacket> {
    match remove_equipped_item_state(world, unique_id, to) {
        Ok(name) => vec![
            ServerPacket::RemoveItem {
                grid,
                unique_id,
                to,
                success: true,
            },
            system_message(&format!("Removed {name}.")),
        ],
        Err(message) => vec![
            ServerPacket::RemoveItem {
                grid,
                unique_id,
                to,
                success: false,
            },
            message,
        ],
    }
}

fn remove_equipped_slot_item_impl(
    world: &mut World,
    grid: MirGridType,
    grid_to: MirGridType,
    unique_id: u64,
    to: i32,
) -> Vec<ServerPacket> {
    match remove_equipped_item_state(world, unique_id, to) {
        Ok(name) => vec![
            ServerPacket::RemoveSlotItem {
                grid,
                grid_to,
                unique_id,
                to,
                success: true,
            },
            system_message(&format!("Removed {name}.")),
        ],
        Err(message) => vec![
            ServerPacket::RemoveSlotItem {
                grid,
                grid_to,
                unique_id,
                to,
                success: false,
            },
            message,
        ],
    }
}

fn drop_gold_impl(world: &mut World, amount: u32) -> Vec<ServerPacket> {
    let player = player_entity(world).expect("player should exist");
    let player_position = entity_position(world, player).expect("player position");

    if world.resource::<SimulationResources>().gold < amount {
        return Vec::new();
    }

    let Some(spawned) = drop_ground_drop(
        world,
        player_position.clone(),
        CRYSTAL_PLAYER_DROP_GOLD_RANGE,
        "",
        None,
        DropLoot::Gold(amount),
        amount,
        format!("{amount} Gold"),
    ) else {
        return Vec::new();
    };

    world.resource_mut::<SimulationResources>().gold -= amount;

    vec![
        ServerPacket::ObjectGold {
            info: ObjectGoldInfo {
                object_id: spawned.object_id,
                gold: amount,
                location: spawned.position,
            },
        },
        ServerPacket::LoseGold { gold: amount },
    ]
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CrystalNpcPurchaseSource {
    Trade,
    BuyBack,
    Used,
}

struct CrystalNpcPurchaseItem {
    item: UserItem,
    source: CrystalNpcPurchaseSource,
}

fn active_crystal_buy_service(service: &ActiveNpcServiceState) -> bool {
    matches!(
        service.label_key.as_str(),
        "BUY" | "BUYSELL" | "BUYBACK" | "BUYUSED" | "PEARLBUY" | "BUYNEW" | "BUYSELLNEW"
    )
}

fn buy_item_impl(
    world: &mut World,
    item_index: u64,
    count: u16,
    panel_type: u8,
) -> Vec<ServerPacket> {
    if count == 0 || panel_type != CRYSTAL_PANEL_BUY {
        return Vec::new();
    }

    let Some(service) = world
        .resource::<SimulationResources>()
        .active_npc_service
        .clone()
    else {
        return Vec::new();
    };
    if !active_crystal_buy_service(&service) {
        return Vec::new();
    }

    process_crystal_npc_goods_expiry(world);
    let rate = crystal_npc_info_by_script_key(&service.script_key)
        .map(|npc| npc.price_rate)
        .unwrap_or(1.0);
    let Some(purchase_item) = crystal_npc_service_item_for_purchase(world, &service, item_index)
    else {
        return Vec::new();
    };
    let source_item = purchase_item.item.clone();
    let Some(template) = crystal_item_by_index(source_item.item_index) else {
        return Vec::new();
    };

    let requested_count = u32::from(count);
    let is_resale = matches!(
        purchase_item.source,
        CrystalNpcPurchaseSource::BuyBack | CrystalNpcPurchaseSource::Used
    );
    let buy_count = if is_resale {
        requested_count.min(u32::from(source_item.count.max(1)))
    } else {
        requested_count
    };
    if buy_count == 0 || buy_count > u32::from(template.stack_size.max(1)) {
        return Vec::new();
    }

    let key = crystal_item_key_for_template(&template);
    let cost = crystal_npc_purchase_cost(&template, buy_count, rate);
    {
        let resources = world.resource::<SimulationResources>();
        if resources.gold < cost {
            return Vec::new();
        }
        if !can_gain_item_quantity(&resources, ItemContainer::Bag1, &key, buy_count) {
            return Vec::new();
        }
    }

    {
        let mut resources = world.resource_mut::<SimulationResources>();
        resources.gold -= cost;
        match purchase_item.source {
            CrystalNpcPurchaseSource::BuyBack => {
                let player_name = resources
                    .selected_character
                    .as_ref()
                    .map(|character| character.name.clone())
                    .unwrap_or_default();
                remove_crystal_npc_buy_back_item(
                    &mut resources,
                    &service.script_key,
                    &player_name,
                    item_index,
                );
            }
            CrystalNpcPurchaseSource::Used => {
                remove_crystal_npc_used_good_item(&mut resources, &service.script_key, item_index);
            }
            CrystalNpcPurchaseSource::Trade => {}
        }
    }

    let (added_attack, added_defence) = user_item_added_attack_defence(&source_item);
    let gained = add_or_increment_item_with_durability_and_stats(
        world,
        ItemContainer::Bag1,
        &key,
        &template.name,
        template
            .tooltip
            .as_deref()
            .unwrap_or("Crystal NPC shop item."),
        8,
        buy_count,
        u16::from(template.weight.max(1)),
        Some(source_item.current_dura),
        Some(source_item.max_dura),
        added_attack,
        added_defence,
    );

    let mut packets = vec![
        ServerPacket::LoseGold { gold: cost },
        ServerPacket::GainedItem {
            item: user_item_from_item_state(&gained),
        },
    ];
    match purchase_item.source {
        CrystalNpcPurchaseSource::BuyBack => {
            packets.push(crystal_npc_goods_packet(
                crystal_npc_buy_back_items_for_script(world, &service.script_key),
                rate,
                CRYSTAL_PANEL_BUY,
                false,
            ));
        }
        CrystalNpcPurchaseSource::Used => {
            let script = crystal_npc_script_by_key(&service.script_key);
            let used_goods = crystal_npc_used_goods_for_script(world, &service.script_key);
            let panel_type = if service.label_key == "BUYUSED" {
                CRYSTAL_PANEL_BUY_SUB
            } else {
                CRYSTAL_PANEL_BUY
            };
            packets.push(crystal_npc_goods_packet_for_script_with_extra(
                script.as_ref(),
                &used_goods,
                panel_type,
                CRYSTAL_GOODS_HIDE_ADDED_STATS,
            ));
        }
        CrystalNpcPurchaseSource::Trade => {}
    }
    packets
}

fn crystal_npc_service_item_for_purchase(
    world: &World,
    service: &ActiveNpcServiceState,
    item_index: u64,
) -> Option<CrystalNpcPurchaseItem> {
    if service.label_key == "BUYBACK" {
        return crystal_npc_buy_back_items_for_script(world, &service.script_key)
            .into_iter()
            .find(|item| item.unique_id == item_index)
            .map(|item| CrystalNpcPurchaseItem {
                item,
                source: CrystalNpcPurchaseSource::BuyBack,
            });
    }

    if service.label_key != "BUYUSED" {
        if let Some(item) = crystal_npc_script_by_key(&service.script_key)
            .map(|script| crystal_npc_trade_goods_for_script(&script))
            .unwrap_or_default()
            .into_iter()
            .find(|item| item.unique_id == item_index)
        {
            return Some(CrystalNpcPurchaseItem {
                item,
                source: CrystalNpcPurchaseSource::Trade,
            });
        }
    }

    crystal_npc_used_goods_for_script(world, &service.script_key)
        .into_iter()
        .find(|item| item.unique_id == item_index)
        .map(|item| CrystalNpcPurchaseItem {
            item,
            source: CrystalNpcPurchaseSource::Used,
        })
}

fn crystal_npc_purchase_cost(template: &CrystalItemTemplate, count: u32, rate: f32) -> u32 {
    let base_cost = template.price.saturating_mul(count);
    ((base_cost as f32) * rate).floor() as u32
}

fn remove_crystal_npc_buy_back_item(
    resources: &mut SimulationResources,
    script_key: &str,
    player_name: &str,
    unique_id: u64,
) {
    if let Some(entry) = resources.npc_buy_back_items.iter_mut().find(|entry| {
        entry.script_key.eq_ignore_ascii_case(script_key) && entry.player_name == player_name
    }) {
        if let Some(index) = entry
            .items
            .iter()
            .position(|item| item.item.unique_id == unique_id)
        {
            entry.items.remove(index);
        }
    }
}

fn remove_crystal_npc_used_good_item(
    resources: &mut SimulationResources,
    script_key: &str,
    unique_id: u64,
) {
    if let Some(entry) = resources
        .npc_used_goods_items
        .iter_mut()
        .find(|entry| entry.script_key.eq_ignore_ascii_case(script_key))
    {
        if let Some(index) = entry
            .items
            .iter()
            .position(|item| item.unique_id == unique_id)
        {
            entry.items.remove(index);
        }
    }
}

fn active_crystal_sell_service(resources: &SimulationResources) -> bool {
    resources
        .active_npc_service
        .as_ref()
        .is_some_and(|service| matches!(service.label_key.as_str(), "SELL" | "BUYSELL"))
}

fn sell_item_impl(world: &mut World, unique_id: u64, count: u16) -> Vec<ServerPacket> {
    let failed_packet = ServerPacket::SellItem {
        unique_id,
        count,
        success: false,
    };

    if count == 0 {
        return vec![failed_packet];
    }

    let sold = {
        let mut resources = world.resource_mut::<SimulationResources>();
        if !active_crystal_sell_service(&resources) {
            return vec![failed_packet];
        }
        let Some(index) = resources.inventory_items.iter().position(|item| {
            u64::from(item.slot) == unique_id
                && matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2)
        }) else {
            return vec![failed_packet];
        };
        let requested = u32::from(count);
        let item_count = resources.inventory_items[index].quantity;
        if requested > item_count {
            return vec![failed_packet];
        }

        let mut item = resources.inventory_items[index].clone();
        item.quantity = requested;
        let template = crystal_item_template_for_item_key(&item.key);

        if template
            .as_ref()
            .is_some_and(|template| template.bind & CRYSTAL_BIND_DONT_SELL != 0)
        {
            return vec![failed_packet];
        }

        let service = resources.active_npc_service.clone();
        if let Some(script) = service
            .as_ref()
            .and_then(|service| crystal_npc_script_by_key(&service.script_key))
        {
            let sell_types = crystal_npc_script_item_types(&script);
            if !sell_types.is_empty()
                && !template
                    .as_ref()
                    .is_some_and(|template| sell_types.contains(&template.item_type))
            {
                return vec![
                    system_message_key(world, "server.CannotSellItemHere"),
                    failed_packet,
                ];
            }
        }

        let value = crystal_sell_value_for_item(&item);
        let partial_crystal_stack = template
            .as_ref()
            .is_some_and(|template| template.stack_size > 1)
            && requested != item_count;
        if partial_crystal_stack && !can_gain_gold(&resources, value) {
            return vec![failed_packet];
        }

        if requested == item_count {
            resources.inventory_items.remove(index);
        } else {
            resources.inventory_items[index].quantity -= requested;
        }

        let gained_gold = value.min(u32::MAX.saturating_sub(resources.gold));
        resources.gold = resources.gold.saturating_add(gained_gold);
        if let Some(service) =
            service.filter(|service| matches!(service.label_key.as_str(), "SELL" | "BUYSELL"))
        {
            let player_name = resources
                .selected_character
                .as_ref()
                .map(|character| character.name.clone())
                .unwrap_or_default();
            push_crystal_npc_buy_back_item(
                &mut resources,
                &service.script_key,
                &player_name,
                &item,
            );
        }
        (gained_gold, value != 0)
    };

    let mut packets = vec![ServerPacket::SellItem {
        unique_id,
        count,
        success: true,
    }];
    if sold.1 {
        packets.push(ServerPacket::GainedGold { gold: sold.0 });
    }
    packets
}

fn crystal_sell_value_for_item(item: &ItemState) -> u32 {
    crystal_item_template_for_item_key(&item.key)
        .map(|template| {
            let added_stat_count = merged_user_item_stats(
                &item.added_stats,
                item.added_defence,
                item.added_attack,
                None,
            )
            .len();
            crystal_item_current_price(item, &template, added_stat_count) / 2
        })
        .unwrap_or_else(|| u32::from(item.weight.max(1)) * item.quantity.max(1))
}

fn push_crystal_npc_buy_back_item(
    resources: &mut SimulationResources,
    script_key: &str,
    player_name: &str,
    item: &ItemState,
) {
    let buy_back_item = NpcBuyBackItemState {
        item: user_item_from_item_state(item),
        expires_at_binary_datetime: future_binary_datetime_minutes(
            CRYSTAL_GOODS_BUY_BACK_TIME_MINUTES,
        ),
    };
    let entry_index = resources
        .npc_buy_back_items
        .iter()
        .position(|entry| {
            entry.script_key.eq_ignore_ascii_case(script_key) && entry.player_name == player_name
        })
        .unwrap_or_else(|| {
            resources.npc_buy_back_items.push(NpcBuyBackState {
                script_key: script_key.to_string(),
                player_name: player_name.to_string(),
                items: Vec::new(),
            });
            resources.npc_buy_back_items.len() - 1
        });
    let entry = &mut resources.npc_buy_back_items[entry_index];
    if CRYSTAL_GOODS_BUY_BACK_MAX_STORED > 0
        && entry.items.len() >= CRYSTAL_GOODS_BUY_BACK_MAX_STORED
    {
        entry.items.remove(0);
    }
    entry.items.push(buy_back_item);
}

fn push_crystal_npc_used_good_item(
    resources: &mut SimulationResources,
    script_key: &str,
    item: UserItem,
) {
    let entry_index = resources
        .npc_used_goods_items
        .iter()
        .position(|entry| entry.script_key.eq_ignore_ascii_case(script_key))
        .unwrap_or_else(|| {
            resources.npc_used_goods_items.push(NpcUsedGoodsState {
                script_key: script_key.to_string(),
                items: Vec::new(),
            });
            resources.npc_used_goods_items.len() - 1
        });
    let entry = &mut resources.npc_used_goods_items[entry_index];
    let multi_count = entry
        .items
        .iter()
        .filter(|existing| existing.item_index == item.item_index)
        .count();
    if multi_count >= CRYSTAL_GOODS_MAX_STORED_PER_ITEM {
        if let Some(index) = entry
            .items
            .iter()
            .position(|existing| existing.added_stats.is_empty())
        {
            entry.items.remove(index);
        } else if !entry.items.is_empty() {
            entry.items.remove(0);
        }
    }
    entry.items.push(item);
}

fn delete_item_impl(
    world: &mut World,
    unique_id: u64,
    count: u16,
    _hero_inventory: bool,
) -> Vec<ServerPacket> {
    if let Some(slot) = u8::try_from(unique_id).ok() {
        let mut resources = world.resource_mut::<SimulationResources>();
        if let Some(index) = resources.inventory_items.iter().position(|item| {
            item.slot == slot && matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2)
        }) {
            let item_count = resources.inventory_items[index].quantity;
            let requested = u32::from(count);
            let delete_count = if requested == 0 || requested > item_count {
                item_count
            } else {
                requested
            };

            if delete_count >= item_count {
                resources.inventory_items.remove(index);
            } else {
                resources.inventory_items[index].quantity -= delete_count;
            }
        }
    }

    vec![ServerPacket::DeleteItem { unique_id, count }]
}

fn active_crystal_repair_service(service: &ActiveNpcServiceState, special: bool) -> bool {
    matches!(
        (special, service.label_key.as_str()),
        (false, "REPAIR") | (true, "SREPAIR")
    )
}

fn repair_item_impl(world: &mut World, unique_id: u64, special: bool) -> Vec<ServerPacket> {
    let Some(service) = world
        .resource::<SimulationResources>()
        .active_npc_service
        .clone()
    else {
        return Vec::new();
    };
    if !active_crystal_repair_service(&service, special) {
        return Vec::new();
    }

    let Some(script) = crystal_npc_script_by_key(&service.script_key) else {
        return Vec::new();
    };

    let item_index = {
        let resources = world.resource::<SimulationResources>();
        resources.inventory_items.iter().position(|item| {
            matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2)
                && u64::from(item.slot) == unique_id
        })
    };
    let Some(item_index) = item_index else {
        return Vec::new();
    };

    let item = {
        let resources = world.resource::<SimulationResources>();
        resources.inventory_items[item_index].clone()
    };
    let Some(template) = crystal_item_template_for_item_key(&item.key) else {
        return Vec::new();
    };

    if crystal_item_has_bind_flag(&item.key, CRYSTAL_BIND_DONT_REPAIR)
        || (special && crystal_item_has_bind_flag(&item.key, CRYSTAL_BIND_NO_SREPAIR))
    {
        return vec![system_message_key(world, "server.CannotRepairItem")];
    }

    let repair_types = crystal_npc_script_item_types(&script);
    if !repair_types.is_empty() && !repair_types.contains(&template.item_type) {
        return vec![system_message_key(world, "server.CannotRepairItemHere")];
    }

    let rate = crystal_npc_info_by_script_key(&service.script_key)
        .map(|npc| npc.price_rate)
        .unwrap_or(1.0);
    let cost = crystal_npc_repair_cost(&item, &template, rate, special);
    {
        let resources = world.resource::<SimulationResources>();
        if resources.gold < cost {
            return Vec::new();
        }
    }

    let (max_dura, current_dura) = {
        let mut resources = world.resource_mut::<SimulationResources>();
        resources.gold -= cost;
        let item = &mut resources.inventory_items[item_index];
        let current = item.durability_current.unwrap_or(0);
        let mut max = item.durability_max.unwrap_or(0);
        if !special {
            let loss = max.saturating_sub(current) / 30;
            max = max.saturating_sub(loss);
            item.durability_max = Some(max);
        }
        item.durability_current = Some(max);
        (max, max)
    };

    vec![
        ServerPacket::LoseGold { gold: cost },
        ServerPacket::ItemRepaired {
            unique_id,
            max_dura,
            current_dura,
        },
    ]
}

fn crystal_npc_repair_cost(
    item: &ItemState,
    template: &CrystalItemTemplate,
    rate: f32,
    special: bool,
) -> u32 {
    let repair_price = crystal_item_repair_price(item, template);
    let multiplier = if special { 3.0 } else { 1.0 };
    ((repair_price as f32) * multiplier * rate).floor() as u32
}

fn crystal_item_repair_price(item: &ItemState, template: &CrystalItemTemplate) -> u32 {
    if template.durability == 0 {
        return 0;
    }

    let added_stat_count = merged_user_item_stats(
        &item.added_stats,
        item.added_defence,
        item.added_attack,
        None,
    )
    .len();
    let count = item.quantity.max(1);
    let price_when_full = crystal_item_full_durability_price(item, template, added_stat_count);
    let current_price = crystal_item_current_price(item, template, added_stat_count);
    price_when_full
        .saturating_mul(count)
        .saturating_sub(current_price)
}

fn crystal_item_full_durability_price(
    item: &ItemState,
    template: &CrystalItemTemplate,
    added_stat_count: usize,
) -> u32 {
    let max_dura = item.durability_max.unwrap_or(0);
    let base = (f32::from(max_dura)
        * ((template.price as f32 / 2.0) / f32::from(template.durability))
        + (template.price as f32 / 2.0))
        .floor();
    crystal_apply_added_stat_price_factor(base, added_stat_count)
}

fn crystal_item_current_price(
    item: &ItemState,
    template: &CrystalItemTemplate,
    added_stat_count: usize,
) -> u32 {
    let mut price = template.price as f32;
    if template.durability > 0 {
        let max_dura = item.durability_max.unwrap_or(0);
        let current_dura = item.durability_current.unwrap_or(0);
        let per_dura = (template.price as f32 / 2.0) / f32::from(template.durability);
        let max_value = (f32::from(max_dura) * per_dura).trunc();
        let durability_ratio = if max_dura > 0 {
            f32::from(current_dura) / f32::from(max_dura)
        } else {
            0.0
        };
        price = (max_value / 2.0
            + ((max_value / 2.0) * durability_ratio)
            + (template.price as f32 / 2.0))
            .floor();
    }
    crystal_apply_added_stat_price_factor(price, added_stat_count)
        .saturating_mul(item.quantity.max(1))
}

fn crystal_apply_added_stat_price_factor(price: f32, added_stat_count: usize) -> u32 {
    (price * (1.0 + (added_stat_count as f32 * 0.1))).trunc() as u32
}

fn drop_item_packet(
    world: &mut World,
    unique_id: u64,
    count: u16,
    hero_inventory: bool,
) -> Vec<ServerPacket> {
    let failed_packet = ServerPacket::DropItem {
        unique_id,
        count,
        hero_inventory,
        success: false,
    };

    if hero_inventory {
        return vec![failed_packet];
    }

    let Some(slot) = u8::try_from(unique_id).ok() else {
        return vec![failed_packet];
    };

    let item_index = {
        let resources = world.resource::<SimulationResources>();
        resources.inventory_items.iter().position(|item| {
            item.slot == slot && matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2)
        })
    };

    let Some(index) = item_index else {
        return vec![
            failed_packet,
            system_message_key(world, "sim.itemNotFoundInBag"),
        ];
    };

    let item = world.resource::<SimulationResources>().inventory_items[index].clone();
    let requested = u32::from(count);
    if requested == 0 || requested > item.quantity {
        return vec![failed_packet];
    }

    if crystal_item_has_bind_flag(&item.key, CRYSTAL_BIND_DONT_DROP) {
        return vec![failed_packet];
    }

    let destroy_on_drop = crystal_item_has_bind_flag(&item.key, CRYSTAL_BIND_DESTROY_ON_DROP);
    let player = player_entity(world).expect("player should exist");
    let player_position = entity_position(world, player).expect("player position");
    let display_name = localized_item_name(current_language(world), &item.key, &item.name);

    if !destroy_on_drop {
        if drop_ground_drop(
            world,
            player_position,
            CRYSTAL_PLAYER_DROP_ITEM_RANGE,
            "",
            None,
            DropLoot::InventoryItem {
                key: item.key.clone(),
                name: item.name.clone(),
                description: item.description.clone(),
                weight: item.weight,
                durability_current: item.durability_current,
                durability_max: item.durability_max,
                added_attack: item.added_attack,
                added_defence: item.added_defence,
                added_stats: item.added_stats.clone(),
                cursed: item.cursed,
                socket_slots: item.socket_slots,
                show_group_pickup: crystal_item_template_for_item_key(&item.key)
                    .map(|template| template.show_group_pickup)
                    .unwrap_or(false),
            },
            requested,
            item.name.clone(),
        )
        .is_none()
        {
            return vec![failed_packet];
        }
    }

    {
        let mut resources = world.resource_mut::<SimulationResources>();
        if requested == item.quantity {
            resources.inventory_items.remove(index);
        } else {
            resources.inventory_items[index].quantity -= requested;
        }
    }

    let mut packets = vec![ServerPacket::DropItem {
        unique_id,
        count,
        hero_inventory,
        success: true,
    }];
    if !destroy_on_drop {
        packets.push(ServerPacket::Chat {
            message: format_localized_text(
                current_language(world),
                "custom.itemDropped",
                [display_name],
            ),
            chat_type: ChatType::System,
        });
    }
    packets
}

fn equipment_uses_durability(item: &EquipmentState) -> bool {
    item.durability_max > 0 && item.slot != EquipmentSlot::Amulet
}

fn equipment_can_lose_durability(item: &EquipmentState) -> bool {
    equipment_uses_durability(item) && item.durability_current > 0
}

fn crystal_weapon_durability_loss(current_tick: u64) -> u16 {
    u16::try_from(deterministic_roll(current_tick, 0, 0, 4) + 1)
        .expect("weapon durability loss should fit u16")
}

fn crystal_worn_durability_loss(_current_tick: u64) -> u16 {
    1
}

fn damage_weapon_durability(world: &mut World, current_tick: u64) -> Option<ServerPacket> {
    let amount = crystal_weapon_durability_loss(current_tick);
    let mut resources = world.resource_mut::<SimulationResources>();
    let Some(item) = resources
        .equipment_items
        .iter_mut()
        .find(|item| item.slot == EquipmentSlot::Weapon)
    else {
        return None;
    };

    if !damage_equipment_item(item, amount) {
        return None;
    }

    Some(ServerPacket::DuraChanged {
        unique_id: equipment_slot_unique_id(item.slot)?,
        current_dura: item.durability_current,
    })
}

fn damage_worn_durability(world: &mut World, current_tick: u64) -> Vec<ServerPacket> {
    let amount = crystal_worn_durability_loss(current_tick);
    let mut packets = Vec::new();
    let mut resources = world.resource_mut::<SimulationResources>();

    for item in resources
        .equipment_items
        .iter_mut()
        .filter(|item| item.slot != EquipmentSlot::Weapon)
    {
        if damage_equipment_item(item, amount) {
            if let Some(unique_id) = equipment_slot_unique_id(item.slot) {
                packets.push(ServerPacket::DuraChanged {
                    unique_id,
                    current_dura: item.durability_current,
                });
            }
        }
    }

    packets
}

fn damage_equipment_item(item: &mut EquipmentState, amount: u16) -> bool {
    if !equipment_can_lose_durability(item) {
        return false;
    }

    item.durability_current = item.durability_current.saturating_sub(amount);
    true
}

fn repair_equipped_durability(world: &mut World) -> Vec<ServerPacket> {
    let mut packets = Vec::new();
    let mut resources = world.resource_mut::<SimulationResources>();

    for item in resources.equipment_items.iter_mut() {
        if !equipment_uses_durability(item) || item.durability_current >= item.durability_max {
            continue;
        }

        item.durability_current = item.durability_max;
        if let Some(unique_id) = equipment_slot_unique_id(item.slot) {
            packets.push(ServerPacket::ItemRepaired {
                unique_id,
                max_dura: item.durability_max,
                current_dura: item.durability_current,
            });
        }
    }

    packets
}

fn repair_equipped_weapon_with_oil(world: &mut World, full_repair: bool) -> Option<ServerPacket> {
    let mut resources = world.resource_mut::<SimulationResources>();
    let weapon = resources
        .equipment_items
        .iter_mut()
        .find(|item| item.slot == EquipmentSlot::Weapon)?;
    if !equipment_uses_durability(weapon) || weapon.durability_current >= weapon.durability_max {
        return None;
    }

    if full_repair {
        weapon.durability_current = weapon.durability_max;
    } else {
        weapon.durability_current = weapon
            .durability_current
            .saturating_add(5)
            .min(weapon.durability_max);
    }

    Some(ServerPacket::ItemRepaired {
        unique_id: equipment_slot_unique_id(weapon.slot)?,
        max_dura: weapon.durability_max,
        current_dura: weapon.durability_current,
    })
}

enum CrystalLuckWeaponOutcome {
    Changed {
        refresh_packet: ServerPacket,
        message: &'static str,
        chat_type: ChatType,
    },
    NoEffect {
        message: &'static str,
    },
}

fn try_luck_weapon(world: &mut World) -> Option<CrystalLuckWeaponOutcome> {
    let player_object_id = current_player_object_id(world).unwrap_or(0);
    let current_tick = world.resource::<SimulationResources>().tick;
    let mut resources = world.resource_mut::<SimulationResources>();
    let weapon = resources
        .equipment_items
        .iter_mut()
        .find(|item| item.slot == EquipmentSlot::Weapon)?;
    if weapon.added_luck >= 7 {
        return None;
    }

    if weapon.added_luck > -10 && deterministic_chance_roll(current_tick, player_object_id, 777, 20)
    {
        weapon.added_luck -= 1;
        return Some(CrystalLuckWeaponOutcome::Changed {
            refresh_packet: ServerPacket::RefreshItem {
                item: user_item_from_equipment_state(weapon)?,
            },
            message: "Curse dwells within your weapon.",
            chat_type: ChatType::System,
        });
    }

    if weapon.added_luck <= 0
        || deterministic_chance_roll(
            current_tick,
            player_object_id,
            778,
            10 * u64::try_from(weapon.added_luck).ok()?,
        )
    {
        weapon.added_luck += 1;
        return Some(CrystalLuckWeaponOutcome::Changed {
            refresh_packet: ServerPacket::RefreshItem {
                item: user_item_from_equipment_state(weapon)?,
            },
            message: "Luck dwells within your weapon.",
            chat_type: ChatType::Hint,
        });
    }

    Some(CrystalLuckWeaponOutcome::NoEffect {
        message: "No effect.",
    })
}

fn equip_inventory_item(
    world: &mut World,
    index: usize,
    slot: EquipmentSlot,
    item: &ItemState,
) -> bool {
    let durability_current = item.durability_current.unwrap_or(10);
    let durability_max = item.durability_max.unwrap_or(durability_current);
    let next_equipment = EquipmentState {
        key: item.key.clone(),
        slot,
        name: item.name.clone(),
        icon: item.icon,
        shape: equipment_shape_for_slot_and_name(slot, &item.name),
        description: item.description.clone(),
        durability_current,
        durability_max,
        grade: item.grade,
        added_attack: item.added_attack,
        added_defence: item.added_defence,
        added_luck: 0,
        added_stats: item.added_stats.clone(),
        cursed: item.cursed,
        socket_slots: item.socket_slots,
        sealed_expiry_time_binary_datetime: item.sealed_expiry_time_binary_datetime,
        sealed_next_time_binary_datetime: item.sealed_next_time_binary_datetime,
        attack: item.attack,
        defence: item.defence,
    };
    let bag_slot = item.slot;
    let replaced = {
        let mut resources = world.resource_mut::<SimulationResources>();
        resources.inventory_items.remove(index);
        if let Some(existing_index) = resources
            .equipment_items
            .iter()
            .position(|equipped| equipped.slot == slot)
        {
            let existing = resources.equipment_items.remove(existing_index);
            resources.equipment_items.push(next_equipment);
            Some(existing)
        } else {
            resources.equipment_items.push(next_equipment);
            None
        }
    };

    if let Some(existing) = replaced {
        add_equipment_back_to_bag(world, existing, bag_slot);
        true
    } else {
        false
    }
}

fn cast_skill(world: &mut World, key: &str) -> Vec<ServerPacket> {
    let tick = world.resource::<SimulationResources>().tick;
    let skill_index = {
        let resources = world.resource::<SimulationResources>();
        resources.skills.iter().position(|skill| skill.key == key)
    };
    let Some(index) = skill_index else {
        return vec![system_message_key(world, "sim.skillNotKnown")];
    };

    let skill = world.resource::<SimulationResources>().skills[index].clone();
    if skill.cooldown_ends_at > tick {
        return vec![system_message_key(world, "sim.skillCooldown")];
    }
    let Some(definition) = skill_definition(skill.key.as_str()) else {
        return vec![system_message_key(world, "sim.skillLogicNotWired")];
    };
    let Some(player) = player_entity(world) else {
        return vec![system_message_key(world, "sim.playerNotInWorld")];
    };
    let current_mp = entity_player_vitals(world, player)
        .map(|vitals| vitals.mp)
        .unwrap_or_default();
    if current_mp < definition.mana_cost {
        return vec![system_message_key(world, "sim.notEnoughMp")];
    }

    let mut packets = Vec::new();
    {
        let mut entity = world.entity_mut(player);
        let mut vitals = entity.get_mut::<PlayerVitals>().expect("player vitals");
        vitals.mp = (vitals.mp - definition.mana_cost).max(0);
        match &definition.effect {
            SkillEffectTemplate::Heal { hp } => {
                vitals.hp = (vitals.hp + *hp).min(vitals.max_hp);
                packets.push(system_message_key_args(
                    world,
                    "sim.castSkill",
                    [localized_skill_name(
                        current_language(world),
                        &definition.key,
                        &definition.name,
                    )],
                ));
            }
            SkillEffectTemplate::Buff {
                buff_key,
                buff_name,
                buff_description,
                duration_ticks,
                attack_bonus,
                defence_bonus,
            } => {
                let (resolved_buff_name, resolved_buff_description) =
                    buff_metadata(buff_key, buff_name, buff_description);
                drop(vitals);
                drop(entity);
                apply_or_refresh_buff(
                    world,
                    BuffState {
                        key: buff_key.clone(),
                        name: resolved_buff_name,
                        description: resolved_buff_description,
                        expires_at_tick: tick + *duration_ticks,
                        attack_bonus: *attack_bonus,
                        defence_bonus: *defence_bonus,
                    },
                );
                packets.push(system_message_key_args(
                    world,
                    "sim.castSkill",
                    [localized_skill_name(
                        current_language(world),
                        &definition.key,
                        &definition.name,
                    )],
                ));
            }
            SkillEffectTemplate::Summon { spell } => {
                drop(vitals);
                drop(entity);
                packets.extend(cast_summon_skill(
                    world,
                    player,
                    &definition.key,
                    &definition.name,
                    spell,
                    skill.level,
                    tick,
                ));
            }
        }
    }

    world.resource_mut::<SimulationResources>().skills[index].cooldown_ends_at =
        tick + u64::from(skill.cooldown_ticks);
    packets
}

fn cast_summon_skill(
    world: &mut World,
    player: Entity,
    skill_key: &str,
    skill_name: &str,
    spell: &str,
    skill_level: u8,
    tick: u64,
) -> Vec<ServerPacket> {
    let packets = vec![system_message_key_args(
        world,
        "sim.castSkill",
        [localized_skill_name(
            current_language(world),
            skill_key,
            skill_name,
        )],
    )];

    let Some(player_object_id) = current_player_object_id(world) else {
        return packets;
    };
    let Some(player_position) = entity_position(world, player) else {
        return packets;
    };
    let player_direction = entity_facing(world, player).unwrap_or(MirDirection::Down);
    let near_spawn = |distance| {
        summon_spawn_position_near(
            world,
            &player_position,
            player_direction,
            distance,
            Some(player),
        )
    };

    let (monster_name, due_tick, spawn_position, summon_metadata, max_summons, unique_recall) =
        match spell {
            "SummonShinsu" => (
                "Shinsu",
                tick + combat_delay_ticks(500),
                near_spawn(1),
                Some(SummonedMonster {
                    summoner_object_id: player_object_id,
                    visible_extra: true,
                    expire_tick: None,
                    require_summoner_within: Some(15),
                    despawn_tick_after_death: None,
                    totem_master_object_id: None,
                    max_minions: Some(2),
                }),
                2,
                true,
            ),
            "SummonVampire" => (
                "VampireSpider",
                tick + ranged_attack_delay_ticks(&player_position, &near_spawn(3)),
                near_spawn(3),
                Some(SummonedMonster {
                    summoner_object_id: player_object_id,
                    visible_extra: true,
                    expire_tick: Some(
                        tick + combat_delay_ticks(15_000 + u64::from(skill_level) * 1_500),
                    ),
                    require_summoner_within: Some(15),
                    despawn_tick_after_death: None,
                    totem_master_object_id: None,
                    max_minions: Some(2),
                }),
                2,
                true,
            ),
            "SummonToad" => (
                "SpittingToad",
                tick + ranged_attack_delay_ticks(&player_position, &near_spawn(3)),
                near_spawn(3),
                Some(SummonedMonster {
                    summoner_object_id: player_object_id,
                    visible_extra: true,
                    expire_tick: Some(
                        tick + combat_delay_ticks(25_000 + u64::from(skill_level) * 2_000),
                    ),
                    require_summoner_within: Some(15),
                    despawn_tick_after_death: None,
                    totem_master_object_id: None,
                    max_minions: Some(2),
                }),
                2,
                true,
            ),
            "SummonSnakes" => (
                "SnakeTotem",
                tick + ranged_attack_delay_ticks(&player_position, &near_spawn(3)),
                near_spawn(3),
                Some(SummonedMonster {
                    summoner_object_id: player_object_id,
                    visible_extra: true,
                    expire_tick: Some(
                        tick + combat_delay_ticks(20_000 + u64::from(skill_level) * 1_500),
                    ),
                    require_summoner_within: Some(15),
                    despawn_tick_after_death: None,
                    totem_master_object_id: None,
                    max_minions: Some(usize::from(skill_level) + 1),
                }),
                2,
                true,
            ),
            "Stonetrap" => (
                "StoneTrap",
                tick + combat_delay_ticks(500),
                near_spawn(2),
                Some(SummonedMonster {
                    summoner_object_id: player_object_id,
                    visible_extra: true,
                    expire_tick: Some(tick + combat_delay_ticks(10_000)),
                    require_summoner_within: Some(15),
                    despawn_tick_after_death: None,
                    totem_master_object_id: None,
                    max_minions: Some(1),
                }),
                1,
                false,
            ),
            _ => return vec![system_message_key(world, "sim.skillLogicNotWired")],
        };

    if recall_existing_summon(
        world,
        player_object_id,
        monster_name,
        &player_position,
        unique_recall,
    ) {
        return packets;
    }

    if active_summoned_monster_count(world, player_object_id) >= max_summons {
        return packets;
    }

    let Some(template) = crystal_dynamic_monster_template(monster_name) else {
        return vec![system_message_key(world, "sim.skillLogicNotWired")];
    };

    queue_pending_monster_spawn(
        world,
        PendingMonsterSpawnAction {
            due_tick,
            summoner_entity: player,
            template: CrystalRespawnTemplate {
                location: spawn_position,
                ..template
            },
            target_entity: None,
            summon_metadata,
            hostile_to_player_override: Some(false),
        },
    );

    packets
}

fn recall_existing_summon(
    world: &mut World,
    summoner_object_id: u32,
    monster_name: &str,
    player_position: &Point,
    enabled: bool,
) -> bool {
    if !enabled {
        return false;
    }

    #[allow(deprecated)]
    let existing = world.iter_entities().find_map(|entity| {
        let summoned = entity.get::<SummonedMonster>()?;
        if summoned.summoner_object_id != summoner_object_id {
            return None;
        }
        let agent = entity.get::<MonsterAgent>()?;
        if agent.dead {
            return None;
        }
        let name = entity.get::<DisplayName>()?;
        (name.value == monster_name).then_some(entity.id())
    });

    let Some(existing) = existing else {
        return false;
    };
    world
        .entity_mut(existing)
        .insert(Position(player_position.clone()));
    true
}

fn skill_definition(key: &str) -> Option<SkillTemplate> {
    starter_server_data()
        .skills
        .into_iter()
        .find(|skill| skill.key == key)
}

fn schedule_monster_respawn(world: &mut World, spawn_ref: SpawnSlotRef, current_tick: u64) {
    let mut spawn_table = world.resource_mut::<MonsterSpawnTable>();
    let Some(rule) = spawn_table.rules.get_mut(spawn_ref.rule_index) else {
        return;
    };
    let Some(slot) = rule.slots.get_mut(spawn_ref.slot_index) else {
        return;
    };
    slot.next_respawn_tick = Some(respawn_tick_for_schedule(
        &rule.respawn_schedule,
        current_tick,
        spawn_ref.rule_index,
        spawn_ref.slot_index,
    ));
}

fn apply_or_refresh_buff(world: &mut World, next: BuffState) {
    let mut resources = world.resource_mut::<SimulationResources>();
    if let Some(existing) = resources.buffs.iter_mut().find(|buff| buff.key == next.key) {
        *existing = next;
    } else {
        resources.buffs.push(next);
    }
}

fn tick_buffs(world: &mut World) {
    let tick = world.resource::<SimulationResources>().tick;
    world
        .resource_mut::<SimulationResources>()
        .buffs
        .retain(|buff| buff.expires_at_tick > tick);
}

fn tick_ground_drop_expiry(world: &mut World, tick: u64) {
    let expired_entities: Vec<Entity> = world
        .query_filtered::<(Entity, &DropExpiry), bevy_ecs::query::With<GroundDrop>>()
        .iter(world)
        .filter_map(|(entity, expiry)| (tick > expiry.expires_at_tick).then_some(entity))
        .collect();

    for entity in expired_entities {
        let _ = world.despawn(entity);
    }
}

#[allow(deprecated)]
fn tick_respawns(world: &mut World) -> Vec<Entity> {
    let tick = world.resource::<SimulationResources>().tick;
    let mut due_respawns = Vec::new();
    {
        let mut spawn_table = world.resource_mut::<MonsterSpawnTable>();
        for (rule_index, rule) in spawn_table.rules.iter_mut().enumerate() {
            for (slot_index, slot) in rule.slots.iter_mut().enumerate() {
                let Some(respawn_tick) = slot.next_respawn_tick else {
                    continue;
                };
                if tick < respawn_tick {
                    continue;
                }
                let Some(entity) = slot.entity else {
                    continue;
                };
                slot.next_respawn_tick = None;
                due_respawns.push((
                    entity,
                    rule_index,
                    slot_index,
                    slot.object_id,
                    slot.spawn_position.clone(),
                    rule.direction,
                    rule.ai,
                    rule.disposition,
                    rule.hostile_to_player,
                    rule.view_range,
                    rule.max_hp,
                    rule.image,
                    rule.can_wander,
                    rule.move_interval_ticks,
                    rule.attack_interval_ticks,
                    rule.route.clone(),
                ));
            }
        }
    }

    let mut revived_entities = Vec::with_capacity(due_respawns.len());

    for (
        entity,
        rule_index,
        slot_index,
        object_id,
        spawn_position,
        direction,
        ai,
        disposition,
        hostile_to_player,
        view_range,
        max_hp,
        image,
        can_wander,
        move_interval_ticks,
        attack_interval_ticks,
        route,
    ) in due_respawns
    {
        world.entity_mut(entity).insert((
            Position(spawn_position.clone()),
            Facing(direction),
            MonsterVitals { hp: max_hp, max_hp },
            MonsterAgent {
                image,
                dead: false,
                patrol_origin: spawn_position,
                ai,
                disposition,
                hostile_to_player,
                tracking_player: false,
                view_range,
                can_wander,
                move_interval_ticks,
                attack_interval_ticks,
                next_move_tick: tick,
                next_attack_tick: tick,
                route,
                route_index: 0,
                route_waiting: false,
                next_route_tick: tick,
            },
            initial_monster_ai_state_for_object(ai, tick, object_id),
            SpawnSlotRef {
                rule_index,
                slot_index,
            },
        ));
        if ai == 11 {
            world.entity_mut(entity).insert(initial_wooma_taurus_state(
                tick,
                move_interval_ticks,
                attack_interval_ticks,
            ));
        }
        if ai == 123 {
            world
                .entity_mut(entity)
                .insert(initial_general_meow_meow_state(tick));
        }
        if ai == 36 {
            world.entity_mut(entity).insert(initial_yimoogi_state(tick));
        }
        world.entity_mut(entity).remove::<PendingHarvestDrops>();
        world.entity_mut(entity).remove::<HarvestOwnership>();
        if let Some(state) = initial_harvest_monster_state(ai) {
            world.entity_mut(entity).insert(state);
        }
        revived_entities.push(entity);
    }

    revived_entities
}

fn total_attack_bonus(resources: &SimulationResources) -> i32 {
    resources
        .equipment_items
        .iter()
        .filter(|item| !item.is_broken())
        .map(EquipmentState::total_attack)
        .sum::<i32>()
        + resources
            .buffs
            .iter()
            .map(|buff| buff.attack_bonus)
            .sum::<i32>()
}

fn total_defence_bonus(resources: &SimulationResources) -> i32 {
    resources
        .equipment_items
        .iter()
        .filter(|item| !item.is_broken())
        .map(EquipmentState::total_defence)
        .sum::<i32>()
        + resources
            .buffs
            .iter()
            .map(|buff| buff.defence_bonus)
            .sum::<i32>()
}

fn monster_route_target(agent: &mut MonsterAgent, position: &Point, tick: u64) -> Option<Point> {
    if agent.route.is_empty() || tick < agent.next_route_tick {
        return None;
    }

    loop {
        let route_index = agent.route_index % agent.route.len();
        let step = &agent.route[route_index];

        if *position != step.location {
            agent.route_waiting = false;
            return Some(step.location.clone());
        }

        if step.delay_ticks > 0 && !agent.route_waiting {
            agent.route_waiting = true;
            agent.next_route_tick = tick + step.delay_ticks;
            return None;
        }

        agent.route_waiting = false;
        agent.route_index = (route_index + 1) % agent.route.len();

        if agent.route.len() == 1 {
            return Some(step.location.clone());
        }
    }
}

fn patrol_target(origin: &Point, tick: u64, salt: u32) -> Point {
    let pattern = [
        Point {
            x: origin.x + 1,
            y: origin.y,
        },
        Point {
            x: origin.x,
            y: origin.y - 1,
        },
        Point {
            x: origin.x - 1,
            y: origin.y,
        },
        Point {
            x: origin.x,
            y: origin.y + 1,
        },
    ];
    pattern[((tick + u64::from(salt)) as usize / 2) % pattern.len()].clone()
}

fn build_user_information(
    config: &SimulationConfig,
    character: &CharacterRecord,
    position: &Point,
    direction: MirDirection,
    vitals: PlayerVitals,
    experience: i64,
    max_experience: i64,
    gold: u32,
    credit: u32,
    storage_size: u16,
    has_expanded_storage: bool,
    storage_has_password: bool,
    require_storage_password: bool,
    storage_password_last_set_binary_datetime: i64,
    expanded_storage_expiry_time_binary_datetime: i64,
    hair: u8,
    inventory_section_present: bool,
    equipment_section_present: bool,
    quest_inventory_section_present: bool,
) -> UserInformation {
    UserInformation {
        object_id: config.object_id,
        real_id: config.real_id,
        name: character.name.clone(),
        guild_name: String::new(),
        guild_rank: String::new(),
        name_colour_argb: -1,
        class: character.class,
        gender: character.gender,
        level: character.level,
        location: position.clone(),
        direction,
        hair,
        hp: vitals.hp,
        mp: vitals.mp,
        experience,
        max_experience,
        level_effects: 0,
        has_hero: false,
        hero_behaviour: 0,
        inventory_section_present,
        equipment_section_present,
        quest_inventory_section_present,
        gold,
        credit,
        has_expanded_storage,
        has_storage_password: storage_has_password,
        require_storage_password,
        storage_password_last_set_binary_datetime,
        expanded_storage_expiry_time_binary_datetime: if has_expanded_storage
            || expanded_storage_expiry_time_binary_datetime != 0
            || storage_size != BASE_STORAGE_SLOTS
        {
            expanded_storage_expiry_time_binary_datetime
        } else {
            0
        },
        magic_count: 0,
        intelligent_creature_count: 0,
        summoned_creature_type: 0,
        creature_summoned: false,
        allow_observe: false,
        observer: false,
    }
}

