    #[test]
    fn start_game_emits_bootstrap_sequence() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        let packets = session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        assert!(matches!(
            packets[0],
            ServerPacket::StartGame { result: 4, .. }
        ));
        assert!(matches!(packets[1], ServerPacket::MapInformation { .. }));
        assert!(matches!(packets[2], ServerPacket::UserInformation { .. }));
        assert!(matches!(packets[3], ServerPacket::UserLocation { .. }));
        assert!(matches!(
            packets[4],
            ServerPacket::Chat {
                chat_type: ChatType::System,
                ..
            }
        ));
    }

    #[test]
    fn start_game_packet_trace_matches_bootstrap_order() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        let packets = session.handle_packet(ClientPacket::StartGame { character_index: 0 });
        let trace = trace_server_packets(&packets);
        let names = trace
            .iter()
            .take(5)
            .map(|entry| entry.packet)
            .collect::<Vec<_>>();

        assert_eq!(
            names,
            vec![
                "StartGame",
                "MapInformation",
                "UserInformation",
                "UserLocation",
                "Chat",
            ]
        );
        assert_eq!(
            trace[0].packet_id,
            mir2_protocol::ServerPacketId::StartGame as i16
        );
        assert_eq!(
            trace[1].packet_id,
            mir2_protocol::ServerPacketId::MapInformation as i16
        );
    }

