    #[test]
    fn change_password_updates_login_password() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        let packets = session.handle_packet(ClientPacket::ChangePassword {
            account_id: "demo".to_string(),
            current_password: "demo".to_string(),
            new_password: "new-demo".to_string(),
        });

        assert!(matches!(
            packets[0],
            ServerPacket::ChangePassword { result: 6 }
        ));

        let old_login = session.handle_packet(ClientPacket::Login {
            account_id: "demo".to_string(),
            password: "demo".to_string(),
        });
        assert!(matches!(old_login[0], ServerPacket::Login { result: 4 }));

        let new_login = session.handle_packet(ClientPacket::Login {
            account_id: "demo".to_string(),
            password: "new-demo".to_string(),
        });
        assert!(matches!(new_login[0], ServerPacket::LoginSuccess { .. }));
    }

