    #[test]
    fn crystal_respawn_schedule_uses_minute_window_semantics() {
        let without_random = respawn_tick_for_schedule(
            &MonsterRespawnSchedule::CrystalMinutes {
                delay_minutes: 5,
                random_delay_minutes: 0,
            },
            10,
            0,
            0,
        );
        assert_eq!(without_random, 310);

        let with_random = respawn_tick_for_schedule(
            &MonsterRespawnSchedule::CrystalMinutes {
                delay_minutes: 5,
                random_delay_minutes: 2,
            },
            42,
            3,
            1,
        );
        let delta = with_random - 42;
        assert!((180..=360).contains(&delta));
        assert_eq!(delta % 60, 0);
    }

