    #[test]
    fn sand_worm_line_attack_fans_out_to_forward_targets() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let worm_position = Point {
            x: player_origin.x + 2,
            y: player_origin.y,
        };
        let ally_position = Point {
            x: player_origin.x + 1,
            y: player_origin.y,
        };
        let worm_object_id = 98_952_u32;
        let ally_object_id = 98_953_u32;
        set_player_position(&mut session, player_origin);
        let worm = spawn_crystal_monster_for_test(
            &mut session,
            worm_object_id,
            "SandWorm",
            worm_position,
            MirDirection::Left,
            true,
        );
        let ally = spawn_crystal_monster_for_test(
            &mut session,
            ally_object_id,
            "BugBat",
            ally_position,
            MirDirection::Left,
            false,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(worm);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("sand worm agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 20;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        {
            let mut entry = session.app.world_mut().entity_mut(ally);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
            agent.can_wander = false;
            agent.tracking_player = false;
        }
        let ally_hp_before = session
            .app
            .world()
            .entity(ally)
            .get::<MonsterVitals>()
            .expect("ally vitals")
            .hp;
        sync_visible_objects(&mut session);

        let attack_packets = session.tick();
        assert!(attack_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectAttack { info } if info.object_id == worm_object_id
        )));

        let hit_packets = session.tick();
        assert!(hit_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == worm_object_id
        )));
        assert!(hit_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectStruck { info }
                if info.object_id == ally_object_id && info.attacker_id == worm_object_id
        )));
        let ally_hp_after = session
            .app
            .world()
            .entity(ally)
            .get::<MonsterVitals>()
            .expect("ally vitals")
            .hp;
        assert!(ally_hp_after < ally_hp_before);
    }

