    #[test]
    fn tucson_egg_is_immobile_and_loses_one_hp_per_hit() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let egg_object_id = 98_893_u32;
        let egg_origin = Point {
            x: player_origin.x + 1,
            y: player_origin.y,
        };
        set_player_position(&mut session, player_origin);
        let egg = spawn_crystal_monster_for_test(
            &mut session,
            egg_object_id,
            "TucsonEgg",
            egg_origin.clone(),
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(egg);
            entry.insert(MonsterVitals { hp: 3, max_hp: 3 });
            let mut agent = entry.get_mut::<MonsterAgent>().expect("tucson egg agent");
            agent.can_wander = true;
            agent.tracking_player = true;
            agent.hostile_to_player = true;
            agent.next_move_tick = current_tick;
            agent.next_attack_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        for _ in 0..3 {
            let packets = session.tick();
            assert_eq!(
                entity_position(session.app.world(), egg).expect("tucson egg position"),
                egg_origin
            );
            assert!(!packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectWalk { movement } if movement.object_id == egg_object_id
                )
            }));
            assert!(!packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectAttack { info } if info.object_id == egg_object_id
                )
            }));
        }

        let mut packets = Vec::new();
        let tick = session.app.world().resource::<SimulationResources>().tick;
        assert!(!super::damage_monster_entity(
            session.app.world_mut(),
            egg,
            999,
            tick,
            &mut packets,
        ));
        assert!(packet_has_object_health(&packets, egg_object_id));
        assert_eq!(
            session
                .app
                .world()
                .entity(egg)
                .get::<MonsterVitals>()
                .expect("tucson egg vitals")
                .hp,
            2
        );

        let tick = session.app.world().resource::<SimulationResources>().tick;
        assert!(!super::damage_monster_entity(
            session.app.world_mut(),
            egg,
            999,
            tick,
            &mut packets,
        ));
        assert_eq!(
            session
                .app
                .world()
                .entity(egg)
                .get::<MonsterVitals>()
                .expect("tucson egg vitals")
                .hp,
            1
        );

        let tick = session.app.world().resource::<SimulationResources>().tick;
        assert!(super::damage_monster_entity(
            session.app.world_mut(),
            egg,
            999,
            tick,
            &mut packets,
        ));
        assert!(packet_has_object_died(&packets, egg_object_id));
        assert_eq!(
            session
                .app
                .world()
                .entity(egg)
                .get::<MonsterVitals>()
                .expect("tucson egg vitals")
                .hp,
            0
        );
    }

