    #[test]
    fn dark_beast_secondary_branch_is_data_gated_by_zero_mc_effect() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let beast_object_id = 98_891_u32;
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        set_player_position(&mut session, player_origin.clone());
        let beast = spawn_crystal_monster_for_test(
            &mut session,
            beast_object_id,
            "CatWidow",
            Point {
                x: player_origin.x + 1,
                y: player_origin.y,
            },
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        let mut branch_tick = current_tick + 1;
        while branch_tick % 5 != 0 {
            branch_tick += 1;
        }
        {
            let mut entry = session.app.world_mut().entity_mut(beast);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("dark beast agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 100;
            agent.next_attack_tick = branch_tick;
        }
        sync_visible_objects(&mut session);

        let mut branch_packets = Vec::new();
        while session.app.world().resource::<SimulationResources>().tick < branch_tick {
            branch_packets = session.tick();
        }
        assert!(branch_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectAttack { info }
                if info.object_id == beast_object_id && info.attack_type == 1
        )));

        let followup_packets = session.tick();
        assert!(!followup_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == beast_object_id
        )));
        assert_eq!(
            session.world_snapshot().player_hp.expect("player hp"),
            before_hp
        );
        assert!(!session
            .world_snapshot()
            .active_buffs
            .iter()
            .any(|buff| buff.key == super::FROST_TIGER_BLEEDING_BUFF_KEY));
    }

