    #[test]
    fn jar1_is_static_and_spawns_regular_slave_on_death() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let (player_origin, jar_position) = (240..460)
            .find_map(|y| {
                (240..460).find_map(|x| {
                    let player = Point { x, y };
                    let jar = Point { x: x + 4, y };
                    (can_occupy(session.app.world(), player.clone(), None)
                        && can_occupy(session.app.world(), jar.clone(), None))
                    .then_some((player, jar))
                })
            })
            .expect("test should find an occupiable line");

        let jar_object_id = 98_907_u32;
        set_player_position(&mut session, player_origin);
        let jar = spawn_crystal_monster_for_test(
            &mut session,
            jar_object_id,
            "Jar1",
            jar_position.clone(),
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(jar);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("jar1 agent");
            agent.can_wander = true;
            agent.tracking_player = true;
            agent.next_move_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        for _ in 0..3 {
            let packets = session.tick();
            assert!(!packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectWalk { movement }
                        if movement.object_id == jar_object_id
                )
            }));
        }
        assert_eq!(
            entity_position(session.app.world(), jar).expect("jar1 position"),
            jar_position
        );

        let death_tick = session.app.world().resource::<SimulationResources>().tick;
        let mut death_packets = Vec::new();
        assert!(super::damage_monster_entity(
            session.app.world_mut(),
            jar,
            i32::MAX,
            death_tick,
            &mut death_packets,
        ));
        assert!(packet_has_object_died(&death_packets, jar_object_id));

        let mut spawned_object_id = None;
        for _ in 0..=super::JAR1_DEATH_SPAWN_DELAY_TICKS + 2 {
            let packets = session.tick();
            spawned_object_id = packets.iter().find_map(|packet| match packet {
                ServerPacket::ObjectMonster { info }
                    if info.object_id != jar_object_id && info.location == jar_position =>
                {
                    Some(info.object_id)
                }
                _ => None,
            });
            if spawned_object_id.is_some() {
                break;
            }
        }
        let spawned_object_id = spawned_object_id.expect("jar1 should spawn a slave monster");

        let spawned_entity = {
            let world = session.app.world_mut();
            let mut query = world.query_filtered::<
                (Entity, &ObjectId, &MonsterAgent, &Position),
                bevy_ecs::query::With<Monster>,
            >();
            query
                .iter(world)
                .find_map(|(entity, object_id, agent, position)| {
                    (object_id.0 == spawned_object_id && !agent.dead && position.0 == jar_position)
                        .then_some(entity)
                })
                .expect("spawned slave entity should exist")
        };
        let spawned_entry = session.app.world().entity(spawned_entity);
        let spawned_agent = spawned_entry
            .get::<MonsterAgent>()
            .expect("spawned slave agent");
        let spawned_name = spawned_entry
            .get::<DisplayName>()
            .expect("spawned slave name")
            .value
            .clone();
        let spawned_template =
            crystal_monster_by_name(&spawned_name).expect("spawned slave crystal monster");

        assert!(spawned_entry.get::<SummonedMonster>().is_none());
        assert!(spawned_agent.hostile_to_player);
        assert!(spawned_agent.tracking_player);
        assert!(!spawned_template.is_boss);
        assert!(!matches!(spawned_template.ai, 72 | 73 | 80 | 81 | 82));
        assert!((50_u16..=60_u16).contains(&spawned_template.level));
    }

    #[test]
    fn wooma_taurus_uses_crystal_damage_and_mad_speed_phase() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let wooma_object_id = 98_891_u32;
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        set_player_position(&mut session, player_origin.clone());
        let wooma = spawn_crystal_monster_for_test(
            &mut session,
            wooma_object_id,
            "WoomaTaurus",
            Point {
                x: player_origin.x + 1,
                y: player_origin.y,
            },
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(wooma);
            let max_hp = entry.get::<MonsterVitals>().expect("wooma vitals").max_hp;
            entry.insert(MonsterVitals {
                hp: max_hp - (max_hp / i32::from(super::WOOMA_TAURUS_STAGE_COUNT)) - 1,
                max_hp,
            });
            let mut agent = entry.get_mut::<MonsterAgent>().expect("wooma agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.next_attack_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        let mut saw_attack = false;
        let mut saw_struck = false;
        for _ in 0..8 {
            let packets = session.tick();
            saw_attack |= packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectAttack { info } if info.object_id == wooma_object_id
                )
            });
            saw_struck |= packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::Struck { info } if info.attacker_id == wooma_object_id
                )
            });
            if saw_attack && saw_struck {
                break;
            }
        }

        let after_hp = session.world_snapshot().player_hp.expect("player hp");
        let entry = session.app.world().entity(wooma);
        let agent = entry.get::<MonsterAgent>().expect("wooma agent");
        let state = entry.get::<WoomaTaurusState>().expect("wooma taurus state");
        assert!(saw_attack);
        assert!(saw_struck);
        assert!(before_hp - after_hp > 7);
        assert!(state.stage < super::WOOMA_TAURUS_STAGE_COUNT);
        assert!(state.mad_until_tick > current_tick);
        assert_eq!(
            agent.move_interval_ticks,
            super::WOOMA_TAURUS_MAD_MOVE_INTERVAL_TICKS
        );
        assert_eq!(
            agent.attack_interval_ticks,
            super::WOOMA_TAURUS_MAD_ATTACK_INTERVAL_TICKS
        );
    }

    #[test]
    fn wooma_taurus_teleports_when_surrounded() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 330, y: 270 };
        let wooma_origin = Point { x: 333, y: 270 };
        let wooma_object_id = 98_892_u32;
        set_player_position(&mut session, player_origin);
        let wooma = spawn_crystal_monster_for_test(
            &mut session,
            wooma_object_id,
            "WoomaTaurus",
            wooma_origin.clone(),
            MirDirection::Left,
            true,
        );
        for (index, direction) in [
            MirDirection::Up,
            MirDirection::UpRight,
            MirDirection::Right,
            MirDirection::DownRight,
            MirDirection::Down,
        ]
        .into_iter()
        .enumerate()
        {
            let blocker = spawn_crystal_monster_for_test(
                &mut session,
                98_900_u32 + u32::try_from(index).expect("blocker index fits u32"),
                "Hen",
                offset_point(&wooma_origin, direction, 1),
                MirDirection::Down,
                false,
            );
            let mut entry = session.app.world_mut().entity_mut(blocker);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("blocker agent");
            agent.can_wander = false;
            agent.next_move_tick = u64::MAX;
        }

        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(wooma);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("wooma agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            let move_interval_ticks = agent.move_interval_ticks;
            let attack_interval_ticks = agent.attack_interval_ticks;
            drop(agent);
            entry.insert(WoomaTaurusState {
                next_teleport_tick: current_tick,
                ..initial_wooma_taurus_state(
                    current_tick,
                    move_interval_ticks,
                    attack_interval_ticks,
                )
            });
        }
        sync_visible_objects(&mut session);

        assert_eq!(
            session
                .app
                .world()
                .entity(wooma)
                .get::<MonsterAgent>()
                .expect("wooma agent")
                .ai,
            11
        );
        assert!(
            super::wooma_taurus_blocked_neighbor_count(session.app.world(), wooma, &wooma_origin)
                >= super::WOOMA_TAURUS_BLOCKED_NEIGHBOR_THRESHOLD
        );
        assert!(super::wooma_taurus_teleport_destination(
            session.app.world(),
            wooma,
            &wooma_origin,
            current_tick,
        )
        .is_some());

        let packets = session.tick();
        assert!(
            session
                .app
                .world()
                .entity(wooma)
                .get::<WoomaTaurusState>()
                .expect("wooma state")
                .next_teleport_tick
                > current_tick
        );
        assert_ne!(
            entity_position(session.app.world(), wooma).expect("wooma position"),
            wooma_origin
        );
        let teleport_movement = packets.iter().find_map(|packet| match packet {
            ServerPacket::ObjectWalk { movement } if movement.object_id == wooma_object_id => {
                Some(movement)
            }
            _ => None,
        });

        let movement = teleport_movement.expect("wooma teleport movement packet");
        assert!(tile_distance(&wooma_origin, &movement.position) > 1);
        assert!(packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectTeleportOut { object_id, effect_type }
                    if *object_id == wooma_object_id && *effect_type == 0
            )
        }));
        assert!(packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectTeleportIn { object_id, effect_type }
                    if *object_id == wooma_object_id && *effect_type == 0
            )
        }));
        assert_eq!(
            entity_position(session.app.world(), wooma).expect("wooma position"),
            movement.position.clone()
        );
        assert!(
            !session
                .app
                .world()
                .entity(wooma)
                .get::<MonsterAgent>()
                .expect("wooma agent")
                .tracking_player
        );
    }

