    #[test]
    fn zuma_taurus_hp_stage_spawns_crystal_slave_wave_without_skipping_attack() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let taurus_position = Point {
            x: player_origin.x + 1,
            y: player_origin.y,
        };
        let taurus_object_id = 98_925_u32;
        set_player_position(&mut session, player_origin.clone());
        let taurus = spawn_crystal_monster_for_test(
            &mut session,
            taurus_object_id,
            "ZumaTaurus",
            taurus_position,
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(taurus);
            let max_hp = entry
                .get::<MonsterVitals>()
                .expect("zuma taurus vitals")
                .max_hp;
            entry.insert(MonsterVitals {
                hp: (max_hp / i32::from(super::ZUMA_TAURUS_STAGE_COUNT)).max(1),
                max_hp,
            });
            let mut ai_state = entry
                .get_mut::<MonsterAiState>()
                .expect("zuma taurus ai state");
            assert_eq!(ai_state.extra_byte, super::ZUMA_TAURUS_STAGE_COUNT);
            ai_state.extra = false;

            let mut agent = entry.get_mut::<MonsterAgent>().expect("zuma taurus agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 1;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        let packets = session.tick();
        assert!(packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectAttack { info }
                if info.object_id == taurus_object_id && info.attack_type == 0
        )));
        assert!(packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectMonster { info }
                if info.master_object_id == taurus_object_id
                    && super::ZUMA_TAURUS_SLAVE_NAMES.contains(&info.name.as_str())
        )));

        let mut summoned_names = Vec::new();
        #[allow(deprecated)]
        for entity in session.app.world().iter_entities() {
            if !entity
                .get::<SummonedMonster>()
                .map(|summoned| summoned.summoner_object_id == taurus_object_id)
                .unwrap_or(false)
            {
                continue;
            }
            let agent = entity.get::<MonsterAgent>().expect("summoned zuma agent");
            assert!(agent.tracking_player);
            assert!(agent.next_attack_tick > current_tick);
            let name = entity
                .get::<DisplayName>()
                .expect("summoned zuma name")
                .value
                .clone();
            assert!(super::ZUMA_TAURUS_SLAVE_NAMES.contains(&name.as_str()));
            summoned_names.push(name);
        }
        assert_eq!(summoned_names.len(), super::ZUMA_TAURUS_SPAWN_BATCH_SIZE);
        assert_eq!(
            session
                .app
                .world()
                .entity(taurus)
                .get::<MonsterAiState>()
                .expect("zuma taurus ai state")
                .extra_byte,
            1
        );
    }

