    #[test]
    fn dark_devil_range_branch_uses_forward_fanout_and_cooldown() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player = player_entity(session.app.world()).expect("player entity");
        let player_object_id =
            entity_object_id(session.app.world(), player).expect("player object id");
        let player_origin = Point { x: 900, y: 900 };
        let devil_position = Point {
            x: player_origin.x + 3,
            y: player_origin.y,
        };
        let ally_position = Point {
            x: player_origin.x + 1,
            y: player_origin.y + 1,
        };
        let devil_object_id = 99_960_u32;
        let ally_object_id = 99_961_u32;
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        set_player_position(&mut session, player_origin);
        let devil = spawn_crystal_monster_for_test(
            &mut session,
            devil_object_id,
            "DarkDevil",
            devil_position,
            MirDirection::Left,
            true,
        );
        let ally = spawn_crystal_monster_for_test(
            &mut session,
            ally_object_id,
            "BugBat",
            ally_position,
            MirDirection::Left,
            false,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(devil);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("dark devil agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 1;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        {
            let mut entry = session.app.world_mut().entity_mut(ally);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
            agent.can_wander = false;
            agent.tracking_player = false;
        }
        let ally_hp_before = session
            .app
            .world()
            .entity(ally)
            .get::<MonsterVitals>()
            .expect("ally vitals")
            .hp;
        sync_visible_objects(&mut session);

        let attack_packets = session.tick();
        assert!(attack_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectRangeAttack { info }
                if info.object_id == devil_object_id
                    && info.target_id == player_object_id
                    && info.direction == MirDirection::Left
        )));
        assert!(
            session
                .app
                .world()
                .entity(devil)
                .get::<MonsterAiState>()
                .expect("dark devil ai state")
                .next_state_tick
                > current_tick
        );

        let hit_packets = session.tick();
        assert!(hit_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == devil_object_id
        )));
        assert!(hit_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectStruck { info }
                if info.object_id == ally_object_id && info.attacker_id == devil_object_id
        )));
        assert!(!hit_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectRangeAttack { info } if info.object_id == devil_object_id
        )));
        assert!(
            before_hp - session.world_snapshot().player_hp.expect("player hp") > 90,
            "DarkDevil forward fanout should preserve imported Crystal DC*3 damage"
        );
        let ally_hp_after = session
            .app
            .world()
            .entity(ally)
            .get::<MonsterVitals>()
            .expect("ally vitals")
            .hp;
        assert!(ally_hp_after < ally_hp_before);
    }

