    #[test]
    fn bone_lord_hp_stage_spawns_crystal_slave_wave() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let lord_position = Point {
            x: player_origin.x + 4,
            y: player_origin.y,
        };
        let lord_object_id = 98_926_u32;
        set_player_position(&mut session, player_origin.clone());
        let lord = spawn_crystal_monster_for_test(
            &mut session,
            lord_object_id,
            "BoneLord",
            lord_position,
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(lord);
            let max_hp = entry
                .get::<MonsterVitals>()
                .expect("bone lord vitals")
                .max_hp;
            entry.insert(MonsterVitals {
                hp: (max_hp / 3).max(1),
                max_hp,
            });
            let mut agent = entry.get_mut::<MonsterAgent>().expect("bone lord agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 1;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        let packets = session.tick();
        assert!(packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectAttack { info }
                if info.object_id == lord_object_id && info.attack_type == 1
        )));
        assert!(!packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectRangeAttack { info } if info.object_id == lord_object_id
        )));
        assert!(packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectMonster { info }
                if info.master_object_id == lord_object_id
                    && super::BONE_LORD_SLAVE_NAMES.contains(&info.name.as_str())
        )));

        let mut summoned_names = Vec::new();
        #[allow(deprecated)]
        for entity in session.app.world().iter_entities() {
            if !entity
                .get::<SummonedMonster>()
                .map(|summoned| summoned.summoner_object_id == lord_object_id)
                .unwrap_or(false)
            {
                continue;
            }
            let agent = entity.get::<MonsterAgent>().expect("summoned bone agent");
            assert!(agent.tracking_player);
            assert!(agent.next_attack_tick > current_tick);
            let name = entity
                .get::<DisplayName>()
                .expect("summoned bone name")
                .value
                .clone();
            assert!(super::BONE_LORD_SLAVE_NAMES.contains(&name.as_str()));
            summoned_names.push(name);
        }
        assert_eq!(summoned_names.len(), super::BONE_LORD_SPAWN_BATCH_SIZE);
        assert_eq!(
            session
                .app
                .world()
                .entity(lord)
                .get::<MonsterAiState>()
                .expect("bone lord ai state")
                .extra_byte,
            1
        );
    }

