    #[test]
    fn king_scorpion_adjacent_random_range_override_uses_mc_line() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let scorpion_position = Point {
            x: player_origin.x + 1,
            y: player_origin.y,
        };
        let scorpion_object_id = 98_961_u32;
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        set_player_position(&mut session, player_origin);
        let scorpion = spawn_crystal_monster_for_test(
            &mut session,
            scorpion_object_id,
            "KingScorpion",
            scorpion_position,
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        let mut branch_tick = current_tick + 1;
        while branch_tick % 5 != 0 {
            branch_tick += 1;
        }
        {
            let mut entry = session.app.world_mut().entity_mut(scorpion);
            let mut agent = entry
                .get_mut::<MonsterAgent>()
                .expect("king scorpion agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 20;
            agent.next_attack_tick = branch_tick;
            agent.next_move_tick = branch_tick;
        }
        sync_visible_objects(&mut session);

        let mut branch_packets = Vec::new();
        while session.app.world().resource::<SimulationResources>().tick < branch_tick {
            branch_packets = session.tick();
        }
        assert!(branch_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectRangeAttack { info } if info.object_id == scorpion_object_id
        )));
        assert!(!branch_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectAttack { info } if info.object_id == scorpion_object_id
        )));

        let hit_packets = session.tick();
        assert!(hit_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == scorpion_object_id
        )));
        assert!(
            before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
            "KingScorpion adjacent range override should use imported Crystal MC damage"
        );
    }

    #[test]
    fn mir_statue_is_static_and_broadcasts_delayed_range_attack() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let statue_position = Point {
            x: player_origin.x + 5,
            y: player_origin.y,
        };
        let statue_object_id = 98_930_u32;
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        set_player_position(&mut session, player_origin.clone());
        let statue = spawn_crystal_monster_for_test(
            &mut session,
            statue_object_id,
            "MirStatue",
            statue_position.clone(),
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(statue);
            let agent = entry.get::<MonsterAgent>().expect("mir statue agent");
            assert!(super::monster_in_attack_range(
                agent,
                &statue_position,
                &player_origin
            ));
            assert!(!super::monster_can_chase_player(agent));
            assert!(!super::monster_can_follow_route(agent));
            let mut agent = entry.get_mut::<MonsterAgent>().expect("mir statue agent");
            agent.can_wander = true;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 1;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        let mut saw_range_attack = false;
        let mut saw_struck = false;
        for _ in 0..8 {
            let packets = session.tick();
            saw_range_attack |= packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectRangeAttack { info }
                        if info.object_id == statue_object_id
                            && info.direction == MirDirection::Left
                )
            });
            saw_struck |= packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::Struck { info } if info.attacker_id == statue_object_id
                )
            });
            assert!(!packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectAttack { info } if info.object_id == statue_object_id
                )
            }));
            assert!(!packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectWalk { movement }
                        if movement.object_id == statue_object_id
                )
            }));
            if saw_range_attack && saw_struck {
                break;
            }
        }

        assert_eq!(
            entity_position(session.app.world(), statue).expect("statue position"),
            statue_position
        );
        assert!(saw_range_attack);
        assert!(saw_struck);
        assert!(
            before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
            "MirStatue delayed range attack should use imported Crystal DC damage"
        );
    }

