    #[test]
    fn lamia_kirin_nonzero_mc_ice_thrust_uses_type_two_cone_and_slow() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let lamia_position = Point {
            x: player_origin.x + 3,
            y: player_origin.y,
        };
        let ally_position = Point {
            x: player_origin.x + 1,
            y: player_origin.y - 1,
        };
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        let mut attack_tick = current_tick + 1;
        while attack_tick % 5 != 0 {
            attack_tick += 1;
        }
        let damage_tick = attack_tick + combat_delay_ticks(500);
        let lamia_object_id = (98_910_u32..99_500_u32)
            .find(|object_id| super::deterministic_chance_roll(damage_tick, *object_id, 186, 5))
            .expect("test object id should satisfy deterministic Kirin slow roll");
        let ally_object_id = 98_909_u32;
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        set_player_position(&mut session, player_origin);
        let lamia = spawn_crystal_monster_for_test(
            &mut session,
            lamia_object_id,
            "Lamia",
            lamia_position,
            MirDirection::Left,
            true,
        );
        let ally = spawn_crystal_monster_for_test(
            &mut session,
            ally_object_id,
            "BugBat",
            ally_position,
            MirDirection::Left,
            false,
        );
        {
            let mut entry = session.app.world_mut().entity_mut(lamia);
            entry.insert(DisplayName::literal("TucsonGeneral"));
            let mut agent = entry.get_mut::<MonsterAgent>().expect("lamia agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 20;
            agent.next_attack_tick = attack_tick;
            agent.next_move_tick = attack_tick;
        }
        {
            let mut entry = session.app.world_mut().entity_mut(ally);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
            agent.can_wander = false;
            agent.tracking_player = false;
        }
        let ally_hp_before = session
            .app
            .world()
            .entity(ally)
            .get::<MonsterVitals>()
            .expect("ally vitals")
            .hp;
        sync_visible_objects(&mut session);

        let mut attack_packets = Vec::new();
        while session.app.world().resource::<SimulationResources>().tick < attack_tick {
            attack_packets = session.tick();
        }
        assert!(attack_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectAttack { info }
                if info.object_id == lamia_object_id
                    && info.attack_type == 2
                    && info.direction == MirDirection::Left
        )));
        assert!(!attack_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectRangeAttack { info } if info.object_id == lamia_object_id
        )));

        let damage_packets = session.tick();
        assert!(damage_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == lamia_object_id
        )));
        assert!(damage_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectStruck { info }
                if info.object_id == ally_object_id && info.attacker_id == lamia_object_id
        )));
        assert!(
            before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
            "Lamia/Kirin IceThrust should use imported Crystal MC damage when nonzero"
        );
        assert!(session
            .world_snapshot()
            .active_buffs
            .iter()
            .any(|buff| buff.key == super::ICE_GUARD_SLOW_BUFF_KEY));
        let ally_hp_after = session
            .app
            .world()
            .entity(ally)
            .get::<MonsterVitals>()
            .expect("ally vitals")
            .hp;
        assert!(ally_hp_after < ally_hp_before);
    }

    #[test]
    fn khazard_uses_crystal_four_tile_pull_packet_without_damage() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player = player_entity(session.app.world()).expect("player entity");
        let player_object_id =
            entity_object_id(session.app.world(), player).expect("player object id");
        let player_origin = (320..380)
            .flat_map(|x| (250..310).map(move |y| Point { x, y }))
            .find(|point| {
                let khazard_position = Point {
                    x: point.x + 4,
                    y: point.y,
                };
                can_occupy(session.app.world(), point.clone(), Some(player))
                    && can_occupy(session.app.world(), khazard_position, None)
                    && (1..=3).all(|amount| {
                        can_occupy(
                            session.app.world(),
                            Point {
                                x: point.x + amount,
                                y: point.y,
                            },
                            Some(player),
                        )
                    })
            })
            .expect("test should find an open Khazard pull lane");
        let khazard_position = Point {
            x: player_origin.x + 4,
            y: player_origin.y,
        };
        let khazard_object_id = 98_936_u32;
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        set_player_position(&mut session, player_origin.clone());
        let khazard = spawn_crystal_monster_for_test(
            &mut session,
            khazard_object_id,
            "Khazard",
            khazard_position.clone(),
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(khazard);
            let agent = entry.get::<MonsterAgent>().expect("khazard agent");
            assert!(super::monster_in_attack_range(
                agent,
                &khazard_position,
                &player_origin
            ));
            assert!(!super::monster_in_attack_range(
                agent,
                &khazard_position,
                &Point {
                    x: khazard_position.x - 3,
                    y: khazard_position.y + 2,
                }
            ));
            let mut agent = entry.get_mut::<MonsterAgent>().expect("khazard agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 1;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        let packets = session.tick();
        assert!(packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == khazard_object_id
                        && info.direction == MirDirection::Left
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == khazard_object_id
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == khazard_object_id
            )
        }));
        assert!(packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectWalk { movement }
                    if movement.object_id == player_object_id
                        && movement.position == (Point {
                            x: player_origin.x + 3,
                            y: player_origin.y,
                        })
                        && movement.direction == MirDirection::Right
            )
        }));
        assert_eq!(
            session.world_snapshot().player_hp.expect("player hp"),
            before_hp
        );
        assert!(
            session
                .app
                .world()
                .entity(khazard)
                .get::<MonsterAiState>()
                .expect("khazard ai state")
                .next_state_tick
                > current_tick
        );
    }

