    #[test]
    fn manectric_claw_range_thrust_can_step_toward_target_instead_of_attacking() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player = player_entity(session.app.world()).expect("player entity");
        let player_origin = (320..380)
            .flat_map(|x| (250..310).map(move |y| Point { x, y }))
            .find(|point| {
                (0..=3).all(|offset| {
                    can_occupy(
                        session.app.world(),
                        Point {
                            x: point.x + offset,
                            y: point.y,
                        },
                        if offset == 0 { Some(player) } else { None },
                    )
                })
            })
            .expect("test should find an open ManectricClaw thrust lane");
        let priest_position = Point {
            x: player_origin.x + 3,
            y: player_origin.y,
        };
        let expected_position = Point {
            x: player_origin.x + 2,
            y: player_origin.y,
        };
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        let attack_tick = current_tick + 1;
        let priest_object_id = (100_510_u32..100_900_u32)
            .find(|object_id| super::deterministic_chance_roll(attack_tick, *object_id, 862, 2))
            .expect("test object id should take ManectricClaw movement branch");
        set_player_position(&mut session, player_origin);
        let priest = spawn_crystal_monster_for_test(
            &mut session,
            priest_object_id,
            "Chieftain_Priest",
            priest_position,
            MirDirection::Left,
            true,
        );
        {
            let mut entry = session.app.world_mut().entity_mut(priest);
            let mut agent = entry
                .get_mut::<MonsterAgent>()
                .expect("manectric claw agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 20;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        let packets = session.tick();
        assert!(packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectWalk { movement }
                if movement.object_id == priest_object_id
                    && movement.position == expected_position
                    && movement.direction == MirDirection::Left
        )));
        assert!(!packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectRangeAttack { info } if info.object_id == priest_object_id
        )));
        assert_eq!(
            entity_position(session.app.world(), priest).expect("manectric claw position"),
            expected_position
        );
    }

    #[test]
    fn manectric_king_uses_three_tile_line_magic_attack() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let king_position = Point {
            x: player_origin.x + 3,
            y: player_origin.y,
        };
        let king_object_id = 98_943_u32;
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        set_player_position(&mut session, player_origin.clone());
        let king = spawn_crystal_monster_for_test(
            &mut session,
            king_object_id,
            "Master_DragonYang",
            king_position.clone(),
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(king);
            let agent = entry.get::<MonsterAgent>().expect("manectric king agent");
            assert!(super::monster_in_attack_range(
                agent,
                &king_position,
                &player_origin
            ));
            assert!(super::monster_in_attack_range(
                agent,
                &king_position,
                &Point {
                    x: king_position.x - 3,
                    y: king_position.y + 3,
                }
            ));
            assert!(!super::monster_in_attack_range(
                agent,
                &king_position,
                &Point {
                    x: king_position.x - 2,
                    y: king_position.y + 3,
                }
            ));
            let mut agent = entry
                .get_mut::<MonsterAgent>()
                .expect("manectric king agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 1;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        let mut saw_attack = false;
        let mut saw_struck = false;
        for _ in 0..8 {
            let packets = session.tick();
            saw_attack |= packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectAttack { info }
                        if info.object_id == king_object_id
                            && info.attack_type == 0
                            && info.direction == MirDirection::Left
                )
            });
            saw_struck |= packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::Struck { info } if info.attacker_id == king_object_id
                )
            });
            assert!(!packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectRangeAttack { info } if info.object_id == king_object_id
                )
            }));
            if saw_attack && saw_struck {
                break;
            }
        }

        assert!(saw_attack);
        assert!(saw_struck);
        assert!(
            before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
            "ManectricKing line branch should use imported Crystal MC damage"
        );
    }

    #[test]
    fn manectric_king_close_push_line_uses_type_one_dc() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player = player_entity(session.app.world()).expect("player entity");
        let player_object_id =
            entity_object_id(session.app.world(), player).expect("player object id");
        let player_origin = (320..380)
            .flat_map(|x| (250..310).map(move |y| Point { x, y }))
            .find(|point| {
                can_occupy(session.app.world(), point.clone(), Some(player))
                    && can_occupy(
                        session.app.world(),
                        Point {
                            x: point.x - 1,
                            y: point.y,
                        },
                        Some(player),
                    )
                    && can_occupy(
                        session.app.world(),
                        Point {
                            x: point.x - 2,
                            y: point.y,
                        },
                        Some(player),
                    )
                    && can_occupy(
                        session.app.world(),
                        Point {
                            x: point.x + 1,
                            y: point.y,
                        },
                        None,
                    )
            })
            .expect("test should find an open ManectricKing push lane");
        let king_object_id = 98_982_u32;
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        set_player_position(&mut session, player_origin.clone());
        let king = spawn_crystal_monster_for_test(
            &mut session,
            king_object_id,
            "Master_DragonYang",
            Point {
                x: player_origin.x + 1,
                y: player_origin.y,
            },
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        let mut branch_tick = current_tick + 1;
        while branch_tick % 3 != 0 {
            branch_tick += 1;
        }
        {
            let mut entry = session.app.world_mut().entity_mut(king);
            let mut agent = entry
                .get_mut::<MonsterAgent>()
                .expect("manectric king agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 20;
            agent.next_attack_tick = branch_tick;
            agent.next_move_tick = branch_tick;
        }
        sync_visible_objects(&mut session);

        let mut branch_packets = Vec::new();
        while session.app.world().resource::<SimulationResources>().tick < branch_tick {
            branch_packets = session.tick();
        }
        assert!(branch_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectAttack { info }
                if info.object_id == king_object_id
                    && info.attack_type == 1
                    && info.direction == MirDirection::Left
        )));
        assert_eq!(
            branch_packets.iter().find_map(|packet| match packet {
                ServerPacket::ObjectWalk { movement } if movement.object_id == player_object_id => {
                    Some(movement.position.clone())
                }
                _ => None,
            }),
            Some(Point {
                x: player_origin.x - 2,
                y: player_origin.y,
            })
        );

        let hit_packets = session.tick();
        assert!(hit_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == king_object_id
        )));
        assert!(session.world_snapshot().player_hp.expect("player hp") < before_hp);
    }

    #[test]
    fn manectric_king_low_hp_mass_attack_hits_nearby_targets() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player = player_entity(session.app.world()).expect("player entity");
        let player_object_id =
            entity_object_id(session.app.world(), player).expect("player object id");
        let player_origin = Point { x: 900, y: 900 };
        let king_position = Point {
            x: player_origin.x + 3,
            y: player_origin.y,
        };
        let ally_position = Point {
            x: king_position.x,
            y: king_position.y + 1,
        };
        let king_object_id = 98_983_u32;
        let ally_object_id = 98_984_u32;
        set_player_position(&mut session, player_origin.clone());
        session
            .app
            .world_mut()
            .entity_mut(player)
            .insert(super::PlayerVitals {
                hp: 500,
                max_hp: 500,
                mp: 100,
            });
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        let expected_damage = {
            let resources = session.app.world().resource::<SimulationResources>();
            (super::crystal_monster_magic_damage("Master_DragonYang")
                - super::total_defence_bonus(resources))
            .max(1)
        };
        let king = spawn_crystal_monster_for_test(
            &mut session,
            king_object_id,
            "Master_DragonYang",
            king_position.clone(),
            MirDirection::Left,
            true,
        );
        let ally = spawn_crystal_monster_for_test(
            &mut session,
            ally_object_id,
            "BugBat",
            ally_position,
            MirDirection::Left,
            false,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(king);
            {
                let mut vitals = entry.get_mut::<MonsterVitals>().expect("king vitals");
                vitals.hp = (vitals.max_hp / 10).max(1);
            }
            let mut agent = entry
                .get_mut::<MonsterAgent>()
                .expect("manectric king agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 20;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        {
            let mut entry = session.app.world_mut().entity_mut(ally);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
            agent.can_wander = false;
            agent.tracking_player = false;
        }
        let ally_hp_before = session
            .app
            .world()
            .entity(ally)
            .get::<MonsterVitals>()
            .expect("ally vitals")
            .hp;
        sync_visible_objects(&mut session);

        let attack_packets = session.tick();
        assert!(attack_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == king_object_id
                        && info.target_id == player_object_id
                        && info.attack_type == 0
                        && info.direction == MirDirection::Left
            )
        }));
        assert!(!attack_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == king_object_id
            )
        }));

        let damage_packets = session.tick();
        assert!(damage_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == king_object_id
            )
        }));
        assert!(damage_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectStruck { info }
                    if info.object_id == ally_object_id && info.attacker_id == king_object_id
            )
        }));
        assert_eq!(
            before_hp - session.world_snapshot().player_hp.expect("player hp"),
            expected_damage
        );
        assert!(
            session
                .app
                .world()
                .entity(ally)
                .get::<MonsterVitals>()
                .expect("ally vitals")
                .hp
                < ally_hp_before
        );
    }

