    #[test]
    fn snow_wolf_type_one_nonzero_mc_slow_frozen_and_fanout() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player = player_entity(session.app.world()).expect("player entity");
        let player_origin = Point { x: 900, y: 900 };
        let wolf_position = Point {
            x: player_origin.x + 1,
            y: player_origin.y,
        };
        let ally_position = Point {
            x: wolf_position.x,
            y: wolf_position.y + 1,
        };
        let attack_tick = 1;
        let damage_tick = attack_tick + super::combat_delay_ticks(450);
        let wolf_object_id = (99_000_u32..100_000_u32)
            .find(|object_id| {
                super::deterministic_chance_roll(
                    damage_tick,
                    *object_id,
                    179,
                    super::SNOW_WOLF_SLOW_CHANCE_DENOMINATOR,
                ) && super::deterministic_chance_roll(
                    damage_tick,
                    *object_id,
                    179,
                    super::SNOW_WOLF_FROZEN_CHANCE_DENOMINATOR,
                )
            })
            .expect("test object id should satisfy deterministic SnowWolf slow/frozen rolls");
        let ally_object_id = 100_001_u32;
        set_player_position(&mut session, player_origin);
        session
            .app
            .world_mut()
            .entity_mut(player)
            .insert(super::PlayerVitals {
                hp: 500,
                max_hp: 500,
                mp: 100,
            });
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        let expected_damage = {
            let resources = session.app.world().resource::<SimulationResources>();
            (super::crystal_monster_raw_magic_damage("Master_DragonYang")
                - super::total_defence_bonus(resources))
            .max(1)
        };
        let wolf = spawn_crystal_monster_for_test(
            &mut session,
            wolf_object_id,
            "Master_DragonYang",
            wolf_position,
            MirDirection::Left,
            true,
        );
        let ally = spawn_crystal_monster_for_test(
            &mut session,
            ally_object_id,
            "BugBat",
            ally_position,
            MirDirection::Left,
            false,
        );
        {
            let mut entry = session.app.world_mut().entity_mut(wolf);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("snow wolf agent");
            agent.ai = 179;
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 20;
            agent.next_attack_tick = attack_tick;
            agent.next_move_tick = attack_tick;
        }
        {
            let mut entry = session.app.world_mut().entity_mut(ally);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
            agent.can_wander = false;
            agent.tracking_player = false;
        }
        let ally_hp_before = session
            .app
            .world()
            .entity(ally)
            .get::<MonsterVitals>()
            .expect("ally vitals")
            .hp;
        sync_visible_objects(&mut session);

        let attack_packets = session.tick();
        assert!(attack_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == wolf_object_id
                        && info.attack_type == 1
                        && info.direction == MirDirection::Left
            )
        }));

        let damage_packets = session.tick();
        assert!(damage_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == wolf_object_id
            )
        }));
        assert!(damage_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectStruck { info }
                    if info.object_id == ally_object_id && info.attacker_id == wolf_object_id
            )
        }));
        assert_eq!(
            before_hp - session.world_snapshot().player_hp.expect("player hp"),
            expected_damage
        );
        let snapshot = session.world_snapshot();
        assert!(snapshot
            .active_buffs
            .iter()
            .any(|buff| buff.key == super::ICE_GUARD_SLOW_BUFF_KEY));
        assert!(snapshot
            .active_buffs
            .iter()
            .any(|buff| buff.key == super::ICE_GUARD_FROZEN_BUFF_KEY));
        assert!(
            session
                .app
                .world()
                .entity(ally)
                .get::<MonsterVitals>()
                .expect("ally vitals")
                .hp
                < ally_hp_before
        );
    }

