    #[test]
    fn frozen_warewolf_hp_branch_spawns_snow_wolf_slaves() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 333, y: 267 };
        let wolf_object_id = 98_931_u32;
        set_player_position(&mut session, player_origin.clone());
        let player = player_entity(session.app.world()).expect("player entity");
        session
            .app
            .world_mut()
            .entity_mut(player)
            .insert(PlayerVitals {
                hp: 1_000,
                max_hp: 1_000,
                mp: 200,
            });
        let wolf = spawn_crystal_monster_for_test(
            &mut session,
            wolf_object_id,
            "FrozenWarewolf",
            Point {
                x: player_origin.x + 1,
                y: player_origin.y,
            },
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(wolf);
            let max_hp = entry
                .get::<MonsterVitals>()
                .expect("frozen warewolf vitals")
                .max_hp;
            entry.insert(MonsterVitals {
                hp: max_hp / 2,
                max_hp,
            });
            let mut agent = entry
                .get_mut::<MonsterAgent>()
                .expect("frozen warewolf agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 1;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        let mut saw_type_two = false;
        let mut saw_spawn = false;
        for _ in 0..20 {
            let packets = session.tick();
            saw_type_two |= packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectAttack { info }
                        if info.object_id == wolf_object_id && info.attack_type == 2
                )
            });
            saw_spawn |= packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectMonster { info }
                        if info.master_object_id == wolf_object_id && info.name == "SnowWolf"
                )
            });
            if saw_type_two && saw_spawn {
                break;
            }
        }

        assert!(saw_type_two);
        assert!(saw_spawn);
        assert!(
            session
                .app
                .world()
                .entity(wolf)
                .get::<MonsterAiState>()
                .expect("frozen warewolf ai state")
                .mode
        );
        let mut slave_count = 0;
        #[allow(deprecated)]
        for entity in session.app.world().iter_entities() {
            if entity
                .get::<SummonedMonster>()
                .map(|summoned| summoned.summoner_object_id == wolf_object_id)
                .unwrap_or(false)
                && entity
                    .get::<DisplayName>()
                    .map(|name| name.value == "SnowWolf")
                    .unwrap_or(false)
            {
                slave_count += 1;
            }
        }
        assert_eq!(slave_count, super::SNOW_WOLF_KING_SLAVE_COUNT);
    }

    #[test]
    fn frozen_warewolf_death_explosion_hits_adjacent_player() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 333, y: 267 };
        let wolf_object_id = 98_930_u32;
        set_player_position(&mut session, player_origin.clone());
        let player = player_entity(session.app.world()).expect("player entity");
        session
            .app
            .world_mut()
            .entity_mut(player)
            .insert(PlayerVitals {
                hp: 1_000,
                max_hp: 1_000,
                mp: 200,
            });
        let wolf = spawn_crystal_monster_for_test(
            &mut session,
            wolf_object_id,
            "FrozenWarewolf",
            Point {
                x: player_origin.x + 1,
                y: player_origin.y,
            },
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(wolf);
            entry.insert(MonsterVitals { hp: 1, max_hp: 1 });
            let mut agent = entry
                .get_mut::<MonsterAgent>()
                .expect("frozen warewolf agent");
            agent.can_wander = false;
            agent.tracking_player = false;
            agent.next_attack_tick = current_tick + 100;
            agent.next_move_tick = current_tick + 100;
        }
        sync_visible_objects(&mut session);

        let death_packets = attack_until_monster_dies(&mut session, wolf_object_id, 4);
        assert!(packet_has_object_died(&death_packets, wolf_object_id));
        let before_explosion_hp = session.world_snapshot().player_hp.expect("player hp");
        let mut saw_explosion_struck = false;
        for _ in 0..3 {
            let packets = session.tick();
            saw_explosion_struck |= packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::Struck { info } if info.attacker_id == wolf_object_id
                )
            });
            if saw_explosion_struck {
                break;
            }
        }

        assert!(saw_explosion_struck);
        assert!(session.world_snapshot().player_hp.expect("player hp") < before_explosion_hp);
    }

    #[test]
    fn tucson_mage_uses_crystal_type_one_packet_without_zero_mc_damage() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let mage_position = Point {
            x: player_origin.x + 3,
            y: player_origin.y,
        };
        let mage_object_id = 98_921_u32;
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        set_player_position(&mut session, player_origin.clone());
        let mage = spawn_crystal_monster_for_test(
            &mut session,
            mage_object_id,
            "TucsonMage",
            mage_position.clone(),
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(mage);
            let agent = entry.get::<MonsterAgent>().expect("tucson mage agent");
            assert!(super::monster_in_attack_range(
                agent,
                &mage_position,
                &player_origin
            ));
            assert!(!super::monster_in_attack_range(
                agent,
                &mage_position,
                &Point {
                    x: mage_position.x - 4,
                    y: mage_position.y,
                }
            ));
            let mut agent = entry.get_mut::<MonsterAgent>().expect("tucson mage agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 1;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        let mut saw_attack = false;
        for _ in 0..6 {
            let packets = session.tick();
            saw_attack |= packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectAttack { info }
                        if info.object_id == mage_object_id && info.attack_type == 1
                )
            });
            assert!(!packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectRangeAttack { info } if info.object_id == mage_object_id
                )
            }));
            assert!(!packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::Struck { info } if info.attacker_id == mage_object_id
                )
            }));
            if saw_attack {
                break;
            }
        }

        assert!(saw_attack);
        assert_eq!(
            session.world_snapshot().player_hp.expect("player hp"),
            before_hp
        );
    }

    #[test]
    fn tucson_mage_wide_line_fans_out_when_mc_is_available() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player = player_entity(session.app.world()).expect("player entity");
        let player_origin = Point { x: 900, y: 900 };
        let mage_position = Point {
            x: player_origin.x + 3,
            y: player_origin.y,
        };
        let ally_position = Point {
            x: player_origin.x + 1,
            y: player_origin.y - 1,
        };
        let mage_object_id = 98_985_u32;
        let ally_object_id = 98_986_u32;
        set_player_position(&mut session, player_origin);
        session
            .app
            .world_mut()
            .entity_mut(player)
            .insert(super::PlayerVitals {
                hp: 500,
                max_hp: 500,
                mp: 100,
            });
        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        let expected_damage = {
            let resources = session.app.world().resource::<SimulationResources>();
            (super::crystal_monster_raw_magic_damage("Master_DragonYang")
                - super::total_defence_bonus(resources))
            .max(1)
        };
        let mage = spawn_crystal_monster_for_test(
            &mut session,
            mage_object_id,
            "Master_DragonYang",
            mage_position,
            MirDirection::Left,
            true,
        );
        let ally = spawn_crystal_monster_for_test(
            &mut session,
            ally_object_id,
            "BugBat",
            ally_position,
            MirDirection::Left,
            false,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(mage);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("tucson mage agent");
            agent.ai = 126;
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.view_range = 3;
            agent.attack_interval_ticks = 20;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        {
            let mut entry = session.app.world_mut().entity_mut(ally);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
            agent.can_wander = false;
            agent.tracking_player = false;
        }
        let ally_hp_before = session
            .app
            .world()
            .entity(ally)
            .get::<MonsterVitals>()
            .expect("ally vitals")
            .hp;
        sync_visible_objects(&mut session);

        let attack_packets = session.tick();
        assert!(attack_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == mage_object_id
                        && info.attack_type == 1
                        && info.direction == MirDirection::Left
            )
        }));
        assert!(!attack_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info } if info.object_id == mage_object_id
            )
        }));

        let damage_packets = session.tick();
        assert!(damage_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == mage_object_id
            )
        }));
        assert!(damage_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectStruck { info }
                    if info.object_id == ally_object_id && info.attacker_id == mage_object_id
            )
        }));
        assert_eq!(
            before_hp - session.world_snapshot().player_hp.expect("player hp"),
            expected_damage
        );
        assert!(
            session
                .app
                .world()
                .entity(ally)
                .get::<MonsterVitals>()
                .expect("ally vitals")
                .hp
                < ally_hp_before
        );
    }

