    #[test]
    fn dark_wraith_line_branch_fans_out_and_sets_cooldown() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let wraith_position = Point {
            x: player_origin.x + 4,
            y: player_origin.y,
        };
        let ally_position = Point {
            x: player_origin.x + 2,
            y: player_origin.y,
        };
        let wraith_object_id = 98_946_u32;
        let ally_object_id = 98_947_u32;
        set_player_position(&mut session, player_origin);
        let wraith = spawn_crystal_monster_for_test(
            &mut session,
            wraith_object_id,
            "DarkWraith",
            wraith_position,
            MirDirection::Left,
            true,
        );
        let ally = spawn_crystal_monster_for_test(
            &mut session,
            ally_object_id,
            "BugBat",
            ally_position,
            MirDirection::Left,
            false,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(wraith);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("dark wraith agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 1;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        {
            let mut entry = session.app.world_mut().entity_mut(ally);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
            agent.can_wander = false;
            agent.tracking_player = false;
        }
        let ally_hp_before = session
            .app
            .world()
            .entity(ally)
            .get::<MonsterVitals>()
            .expect("ally vitals")
            .hp;
        sync_visible_objects(&mut session);

        let attack_packets = session.tick();
        assert!(attack_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectAttack { info }
                if info.object_id == wraith_object_id && info.attack_type == 2
        )));
        let cooldown_until = session
            .app
            .world()
            .entity(wraith)
            .get::<MonsterAiState>()
            .expect("dark wraith ai state")
            .next_state_tick;
        assert!(cooldown_until > session.app.world().resource::<SimulationResources>().tick);

        let damage_packets = session.tick();
        assert!(damage_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == wraith_object_id
        )));
        assert!(damage_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectStruck { info }
                if info.object_id == ally_object_id && info.attacker_id == wraith_object_id
        )));
        assert!(!damage_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectAttack { info }
                if info.object_id == wraith_object_id && info.attack_type == 2
        )));
        let ally_hp_after = session
            .app
            .world()
            .entity(ally)
            .get::<MonsterVitals>()
            .expect("ally vitals")
            .hp;
        assert!(ally_hp_after < ally_hp_before);
    }

