        let player_origin = Point { x: 333, y: 267 };
        let fox_position = Point {
            x: player_origin.x + 3,
            y: player_origin.y,
        };
        let kite_position = Point {
            x: fox_position.x + 1,
            y: fox_position.y,
        };
        let fox_object_id = 98_980_u32;
