    fn red_foxman_adjacent_fear_window_teleports_with_effect_two() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 333, y: 267 };
        let fox_position = Point {
            x: player_origin.x + 1,
            y: player_origin.y,
        };
        let fox_object_id = 98_981_u32;
        set_player_position(&mut session, player_origin);
        let fox = spawn_crystal_monster_for_test(
            &mut session,
            fox_object_id,
            "RedFoxMan",
            fox_position.clone(),
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(fox);
            {
                let mut ai_state = entry
                    .get_mut::<MonsterAiState>()
                    .expect("red foxman ai state");
                ai_state.next_state_tick = current_tick + super::FOXMAN_FEAR_DURATION_TICKS;
            }
            let mut agent = entry.get_mut::<MonsterAgent>().expect("red foxman agent");
            agent.can_wander = true;
            agent.tracking_player = true;
            agent.next_route_tick = current_tick;
            agent.next_attack_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        let packets = session.tick();
        assert!(packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectTeleportOut { object_id, effect_type }
                    if *object_id == fox_object_id
                        && *effect_type == super::RED_FOXMAN_TELEPORT_EFFECT
            )
        }));
        assert!(packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectTeleportIn { object_id, effect_type }
                    if *object_id == fox_object_id
                        && *effect_type == super::RED_FOXMAN_TELEPORT_EFFECT
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info } if info.object_id == fox_object_id
            )
        }));
        assert!(
            tile_distance(
                &fox_position,
                &entity_position(session.app.world(), fox).expect("red foxman position")
            ) > 1
        );
    }

