    #[test]
    fn hell_bomb_ignores_damage_and_explodes_after_timeout() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 333, y: 267 };
        let bomb_object_id = 98_947;
        set_player_position(&mut session, player_origin.clone());
        let bomb = spawn_crystal_monster_for_test(
            &mut session,
            bomb_object_id,
            "HellBomb1",
            Point {
                x: player_origin.x + 1,
                y: player_origin.y,
            },
            MirDirection::Up,
            true,
        );
        sync_visible_objects(&mut session);

        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        let mut ignored_damage_packets = Vec::new();
        assert!(!super::damage_monster_entity(
            session.app.world_mut(),
            bomb,
            i32::MAX,
            current_tick,
            &mut ignored_damage_packets,
        ));
        let vitals = session
            .app
            .world()
            .entity(bomb)
            .get::<MonsterVitals>()
            .expect("hell bomb vitals");
        assert_eq!(vitals.hp, vitals.max_hp);

        let before_hp = session.world_snapshot().player_hp.expect("player hp");
        let mut explosion_packets = Vec::new();
        for _ in 0..=super::HELL_BOMB_EXPLOSION_LIFETIME_TICKS {
            let packets = session.tick();
            if packet_has_object_died(&packets, bomb_object_id) {
                explosion_packets = packets;
                break;
            }
        }

        assert!(explosion_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectAttack { info } if info.object_id == bomb_object_id
        )));
        assert!(packet_has_object_died(&explosion_packets, bomb_object_id));

        let hit_packets = session.tick();
        assert!(hit_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == bomb_object_id
        )));
        assert!(session.world_snapshot().player_hp.expect("player hp") < before_hp);
    }

    #[test]
    fn hell_bomb_explosion_applies_poison_variant() {
        for (index, bomb_name, buff_key) in [
            (0_u32, "HellBomb1", super::ICE_GUARD_FROZEN_BUFF_KEY),
            (1, "HellBomb2", super::HELL_KEEPER_DAZED_BUFF_KEY),
            (2, "HellBomb3", super::FROST_TIGER_BLEEDING_BUFF_KEY),
        ] {
            let mut session = SimulationSession::new(SimulationConfig::default());
            session.handle_packet(ClientPacket::StartGame { character_index: 0 });

            let player_origin = Point { x: 333, y: 267 };
            let bomb_object_id = 98_981 + index;
            set_player_position(&mut session, player_origin.clone());
            let bomb = spawn_crystal_monster_for_test(
                &mut session,
                bomb_object_id,
                bomb_name,
                Point {
                    x: player_origin.x + 1,
                    y: player_origin.y,
                },
                MirDirection::Up,
                true,
            );
            let current_tick = session.app.world().resource::<SimulationResources>().tick;
            {
                let mut entry = session.app.world_mut().entity_mut(bomb);
                entry
                    .get_mut::<MonsterAiState>()
                    .expect("hell bomb ai state")
                    .next_state_tick = current_tick + 1;
            }
            sync_visible_objects(&mut session);

            let explosion_packets = session.tick();
            assert!(packet_has_object_died(&explosion_packets, bomb_object_id));

            let hit_packets = session.tick();
            assert!(hit_packets.iter().any(|packet| matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == bomb_object_id
            )));
            assert!(
                session
                    .world_snapshot()
                    .active_buffs
                    .iter()
                    .any(|buff| buff.key == buff_key),
                "{bomb_name} should apply its Crystal poison variant"
            );
        }
    }

    #[test]
    fn hell_lord_spawns_minions_and_advances_stage_when_knight_dies() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 333, y: 267 };
        let lord_object_id = 98_948;
        set_player_position(&mut session, player_origin.clone());
        let hell_lord = spawn_crystal_monster_for_test(
            &mut session,
            lord_object_id,
            "HellLord",
            Point {
                x: player_origin.x + 5,
                y: player_origin.y,
            },
            MirDirection::Up,
            true,
        );
        sync_visible_objects(&mut session);

        let attack_packets = session.tick();
        assert!(attack_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectAttack { info } if info.object_id == lord_object_id
        )));

        let spawn_packets = session.tick();
        let hell_knight = find_monster_entity_by(&session, |name, agent, _| {
            name == "HellKnight1" && agent.ai == 97
        });
        let knight_bundle = super::visible_object_bundle_for_entity(
            session.app.world(),
            hell_knight,
            mir2_game_data::LanguageCode::English,
        )
        .expect("hell knight visible bundle");
        assert!(matches!(
            knight_bundle.1.spawn_packet,
            ServerPacket::ObjectMonster { info }
                if info.name == "HellKnight1"
                    && info.ai == 97
                    && info.extra
                    && info.master_object_id == lord_object_id
        ));
        assert!(
            spawn_packets.iter().any(|packet| matches!(
                packet,
                ServerPacket::ObjectMonster { info } if info.name.starts_with("HellBomb") && info.ai == 99
            )) || {
                #[allow(deprecated)]
                session.app.world().iter_entities().any(|entity| {
                    entity
                        .get::<MonsterAgent>()
                        .map(|agent| agent.ai == 99)
                        .unwrap_or(false)
                        && entity
                            .get::<DisplayName>()
                            .map(|name| name.value.starts_with("HellBomb"))
                            .unwrap_or(false)
                })
            }
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        let mut death_packets = Vec::new();
        assert!(super::damage_monster_entity(
            session.app.world_mut(),
            hell_knight,
            i32::MAX,
            current_tick,
            &mut death_packets,
        ));
        assert!(death_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectMonster { info }
                if info.object_id == lord_object_id && info.extra_byte == 1
        )));

        let lord_hp = session
            .app
            .world()
            .entity(hell_lord)
            .get::<MonsterVitals>()
            .expect("hell lord vitals")
            .hp;
        let mut ignored_damage_packets = Vec::new();
        assert!(!super::damage_monster_entity(
            session.app.world_mut(),
            hell_lord,
            i32::MAX,
            current_tick,
            &mut ignored_damage_packets,
        ));
        assert_eq!(
            session
                .app
                .world()
                .entity(hell_lord)
                .get::<MonsterVitals>()
                .expect("hell lord vitals")
                .hp,
            lord_hp
        );
    }

