    #[test]
    fn holy_deva_uses_crystal_six_tile_range_attack_and_extra_state() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let deva_object_id = 98_913_u32;
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        let before_hp = session.world_snapshot().player_hp.expect("player hp");

        set_player_position(&mut session, player_origin.clone());
        let deva = spawn_crystal_monster_for_test(
            &mut session,
            deva_object_id,
            "HolyDeva",
            Point {
                x: player_origin.x + 6,
                y: player_origin.y,
            },
            MirDirection::Left,
            true,
        );
        {
            let mut entry = session.app.world_mut().entity_mut(deva);
            assert!(
                entry
                    .get::<MonsterAiState>()
                    .expect("holy deva ai state")
                    .extra
            );
            {
                let mut ai_state = entry
                    .get_mut::<MonsterAiState>()
                    .expect("holy deva ai state");
                ai_state.next_state_tick = current_tick + 10;
            }
            let mut agent = entry.get_mut::<MonsterAgent>().expect("holy deva agent");
            agent.tracking_player = true;
            agent.attack_interval_ticks = 1;
            agent.next_attack_tick = current_tick;
            agent.next_move_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        let attack_packets = session.tick();
        assert_eq!(
            entity_position(session.app.world(), deva).expect("holy deva position"),
            Point {
                x: player_origin.x + 6,
                y: player_origin.y,
            }
        );
        assert!(attack_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectRangeAttack { info }
                if info.object_id == deva_object_id && info.target_id == 1000
        )));
        assert!(!attack_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectWalk { movement } if movement.object_id == deva_object_id
        )));
        assert_eq!(
            session.world_snapshot().player_hp.expect("player hp"),
            before_hp
        );

        let hit_packets = session.tick();
        assert!(hit_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == deva_object_id
        )));
        assert!(
            before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
            "HolyDeva should use imported Crystal DC damage"
        );
    }

    #[test]
    fn holy_deva_kites_before_fear_window_then_attacks() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player = player_entity(session.app.world()).expect("player entity");
        let player_object_id =
            entity_object_id(session.app.world(), player).expect("player object id");
        let player_origin = Point { x: 333, y: 267 };
        let deva_position = Point {
            x: player_origin.x + 3,
            y: player_origin.y,
        };
        let kite_position = Point {
            x: deva_position.x + 1,
            y: deva_position.y,
        };
        let deva_object_id = 98_914_u32;
        set_player_position(&mut session, player_origin);
        let deva = spawn_crystal_monster_for_test(
            &mut session,
            deva_object_id,
            "HolyDeva",
            deva_position,
            MirDirection::Left,
            true,
        );
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        {
            let mut entry = session.app.world_mut().entity_mut(deva);
            let mut agent = entry.get_mut::<MonsterAgent>().expect("holy deva agent");
            agent.can_wander = true;
            agent.tracking_player = true;
            agent.move_interval_ticks = 1;
            agent.attack_interval_ticks = 20;
            agent.next_move_tick = current_tick;
            agent.next_attack_tick = current_tick;
        }
        sync_visible_objects(&mut session);

        let kite_packets = session.tick();
        assert!(kite_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectWalk { movement }
                    if movement.object_id == deva_object_id
                        && movement.position == kite_position
                        && movement.direction == MirDirection::Right
            )
        }));
        assert!(!kite_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info } if info.object_id == deva_object_id
            )
        }));

        let attack_packets = session.tick();
        assert!(attack_packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == deva_object_id && info.target_id == player_object_id
            )
        }));
    }

    #[test]
    fn ranged_monster_damage_uses_distance_scaled_delay() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let player_origin = Point { x: 900, y: 900 };
        let monster_object_id = 98_773_u32;
        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        let before_hp = session.world_snapshot().player_hp.expect("player hp");

        set_player_position(&mut session, player_origin.clone());
        let _monster_entity = session
            .app
            .world_mut()
            .spawn((
                ObjectId(monster_object_id),
                DisplayName::literal("Archer Delay Test"),
                Position(Point {
                    x: player_origin.x + 12,
                    y: player_origin.y,
                }),
                Facing(MirDirection::Left),
                Monster,
                MonsterVitals { hp: 50, max_hp: 50 },
                MonsterAgent {
                    image: 43,
                    dead: false,
                    patrol_origin: player_origin.clone(),
                    ai: 113,
                    disposition: WorldEntityDisposition::Neutral,
                    hostile_to_player: true,
                    tracking_player: true,
                    view_range: 12,
                    can_wander: false,
                    move_interval_ticks: 1,
                    attack_interval_ticks: 1,
                    next_move_tick: current_tick,
                    next_attack_tick: current_tick,
                    route: Vec::new(),
                    route_index: 0,
                    route_waiting: false,
                    next_route_tick: current_tick,
                },
            ))
            .id();
        sync_visible_objects(&mut session);

        let launch_packets = session.tick();
        assert!(launch_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectRangeAttack { info } if info.object_id == monster_object_id
        )));
        assert!(!launch_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == monster_object_id
        )));
        assert_eq!(
            session.world_snapshot().player_hp.expect("player hp"),
            before_hp
        );

        let middle_packets = session.tick();
        assert!(!middle_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == monster_object_id
        )));
        assert_eq!(
            session.world_snapshot().player_hp.expect("player hp"),
            before_hp
        );

        let hit_packets = session.tick();
        assert!(hit_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == monster_object_id
        )));
        assert!(session.world_snapshot().player_hp.expect("player hp") < before_hp);
    }

