    #[test]
    fn crystal_npc_goto_loop_stops_at_section_hop_limit() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });
        let script = CrystalNpcScript {
            script_key: "Test/Loop".to_string(),
            relative_path: "Test/Loop.txt".to_string(),
            raw_text: String::new(),
            lines: Vec::new(),
            line_count: 0,
            non_empty_line_count: 0,
            label_count: 1,
            insert_count: 0,
            command_directives: Vec::new(),
            labels: Vec::new(),
            sections: vec![CrystalNpcSection {
                label: "@Main".to_string(),
                line_number: 1,
                lines: vec!["#ACT".to_string(), "GOTO @Main".to_string()],
            }],
            inserts: Vec::new(),
        };
        let context = NpcInteractionContext {
            object_id: 4990,
            name: "Loop Tester".to_string(),
            name_key: None,
            position: Point { x: 331, y: 270 },
            quest_ids: Vec::new(),
            script_key: Some("Test/Loop".to_string()),
            args: Vec::new(),
            input: None,
        };

        let result =
            super::run_crystal_npc_script_impl(session.app.world_mut(), &context, &script, "@Main")
                .expect("looping script should return a diagnostic result");

        assert!(result.dialog.is_none());
        let diagnostics = &session
            .app
            .world()
            .resource::<SimulationResources>()
            .npc_script_diagnostics;
        assert!(diagnostics.iter().any(|diagnostic| {
            diagnostic.script_key == "Test/Loop"
                && diagnostic.command == "GOTO"
                && diagnostic.message.contains("section hop limit")
        }));
    }

    #[test]
    fn crystal_npc_reserved_service_labels_map_to_crystal_packets() {
        let buy =
            super::crystal_npc_service_packets_for_label(None, "[@Buy]").expect("buy packets");
        assert!(matches!(
            buy.as_slice(),
            [ServerPacket::NPCGoods {
                panel_type: 0,
                rate: 1.0,
                hide_added_stats: true,
                ..
            }]
        ));

        let buy_used = super::crystal_npc_service_packets_for_label(None, "@BuyUsed")
            .expect("buy used packets");
        assert!(matches!(
            buy_used.as_slice(),
            [ServerPacket::NPCGoods {
                panel_type: 1,
                rate: 1.0,
                hide_added_stats: true,
                ..
            }]
        ));

        let buy_back = super::crystal_npc_service_packets_for_label(None, "@BuyBack")
            .expect("buy back packets");
        assert!(matches!(
            buy_back.as_slice(),
            [ServerPacket::NPCGoods {
                panel_type: 0,
                rate: 1.0,
                hide_added_stats: false,
                list,
            }] if list.is_empty()
        ));

        let buy_sell = super::crystal_npc_service_packets_for_label(None, "@BuySell")
            .expect("buy/sell packets");
        assert!(matches!(
            buy_sell.as_slice(),
            [
                ServerPacket::NPCGoods {
                    panel_type: 0,
                    rate: 1.0,
                    hide_added_stats: true,
                    ..
                },
                ServerPacket::NPCSell
            ]
        ));

        let craft =
            super::crystal_npc_service_packets_for_label(None, "@Craft").expect("craft packets");
        assert!(matches!(
            craft.as_slice(),
            [ServerPacket::NPCGoods {
                panel_type: 2,
                rate: 1.0,
                ..
            }]
        ));

        assert!(matches!(
            super::crystal_npc_service_packets_for_label(None, "@Repair").as_deref(),
            Some([ServerPacket::NPCRepair { rate: 1.0 }])
        ));
        assert!(matches!(
            super::crystal_npc_service_packets_for_label(None, "@SRepair").as_deref(),
            Some([ServerPacket::NPCSRepair { rate: 1.0 }])
        ));
        assert!(matches!(
            super::crystal_npc_service_packets_for_label(None, "@Refine").as_deref(),
            Some([ServerPacket::NPCRefine {
                rate: 1.0,
                refining: false
            }])
        ));
        assert!(matches!(
            super::crystal_npc_service_packets_for_label(None, "@RefineCheck").as_deref(),
            Some([ServerPacket::NPCCheckRefine])
        ));
        assert!(matches!(
            super::crystal_npc_service_packets_for_label(None, "@ReplaceWeddingRing").as_deref(),
            Some([ServerPacket::NPCReplaceWedRing { rate: 1.0 }])
        ));
        assert!(matches!(
            super::crystal_npc_service_packets_for_label(None, "@Storage").as_deref(),
            Some([ServerPacket::NPCStorage])
        ));
        assert!(super::crystal_npc_service_packets_for_label(None, "@Main").is_none());
    }

    #[test]
    fn crystal_npc_service_links_emit_packets_and_close_dialog() {
        let mut config = SimulationConfig::default();
        config.visible_npcs.push(crate::VisibleNpcRecord {
            object_id: 4991,
            name: "Warehouse Keeper".to_string(),
            image: 5,
            colour_argb: -1,
            position: Point { x: 331, y: 270 },
            direction: MirDirection::Left,
            quest_ids: Vec::new(),
            script_key: Some("BichonProvince/Warehouse-D002".to_string()),
        });
        config.visible_npcs.push(crate::VisibleNpcRecord {
            object_id: 4990,
            name: "Wicked Trader".to_string(),
            image: 5,
            colour_argb: -1,
            position: Point { x: 331, y: 271 },
            direction: MirDirection::Left,
            quest_ids: Vec::new(),
            script_key: Some("BichonProvince/NaturalCave/WickedTrader".to_string()),
        });
        config.visible_npcs.push(crate::VisibleNpcRecord {
            object_id: 4989,
            name: "Craft Lady".to_string(),
            image: 5,
            colour_argb: -1,
            position: Point { x: 329, y: 270 },
            direction: MirDirection::Right,
            quest_ids: Vec::new(),
            script_key: Some("BichonProvince/BichonWall/CraftsLady".to_string()),
        });
        let mut session = SimulationSession::new(config);
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let _ = session.interact(4991);
        let storage_packets = session.select_npc_dialog_target("@Storage");
        assert!(matches!(
            storage_packets.as_slice(),
            [ServerPacket::NPCStorage]
        ));
        assert!(session.world_snapshot().active_npc_dialog.is_none());
        assert!(session
            .app
            .world()
            .resource::<SimulationResources>()
            .active_npc_service
            .as_ref()
            .is_some_and(|service| service.label_key == "STORAGE"));

        let _ = session.interact(4990);
        let buy_sell_packets = session.select_npc_dialog_target("@BuySell");
        assert!(
            matches!(
                buy_sell_packets.as_slice(),
                [
                    ServerPacket::NPCGoods {
                        panel_type: 0,
                        rate: 2.0,
                        hide_added_stats: true,
                        ..
                    },
                    ServerPacket::NPCSell
                ]
            ),
            "unexpected buy/sell packets: {buy_sell_packets:?}"
        );
        let ServerPacket::NPCGoods { list, .. } = &buy_sell_packets[0] else {
            panic!("first buy/sell packet should be NPCGoods");
        };
        assert!(list
            .iter()
            .any(|item| { item.item_index == 658 && item.count == 1 && item.is_shop_item }));
        assert!(list
            .iter()
            .any(|item| item.item_index == 658 && item.count == 5));
        assert!(session.world_snapshot().active_npc_dialog.is_none());

        let _ = session.interact(4990);
        let repair_packets = session.select_npc_dialog_target("@repair");
        assert!(matches!(
            repair_packets.as_slice(),
            [ServerPacket::NPCRepair { rate: 2.0 }]
        ));
        assert!(session.world_snapshot().active_npc_dialog.is_none());

        let _ = session.interact(4989);
        let craft_packets = session.select_npc_dialog_target("@Craft");
        assert!(matches!(
            craft_packets.as_slice(),
            [ServerPacket::NPCGoods {
                panel_type: 2,
                rate: 1.0,
                ..
            }]
        ));
        let ServerPacket::NPCGoods { list, .. } = &craft_packets[0] else {
            panic!("craft packet should be NPCGoods");
        };
        assert!(list
            .iter()
            .any(|item| item.item_index == 664 && item.count == 1 && item.is_shop_item));
        assert!(session.world_snapshot().active_npc_dialog.is_none());
    }

    #[test]
    fn crystal_npc_storage_service_context_allows_store_and_take_back_without_helper() {
        let mut config = SimulationConfig::default();
        config.visible_npcs.push(crate::VisibleNpcRecord {
            object_id: 4991,
            name: "Warehouse Keeper".to_string(),
            image: 5,
            colour_argb: -1,
            position: Point { x: 331, y: 270 },
            direction: MirDirection::Left,
            quest_ids: Vec::new(),
            script_key: Some("BichonProvince/Warehouse-D002".to_string()),
        });
        let mut session = SimulationSession::new(config);
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let bag_item = session
            .world_snapshot()
            .inventory_items
            .into_iter()
            .find(|item| matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2))
            .expect("bag item");

        let _ = session.interact(4991);
        let storage_packets = session.select_npc_dialog_target("@Storage");
        assert!(matches!(
            storage_packets.as_slice(),
            [ServerPacket::NPCStorage]
        ));
        assert!(session
            .app
            .world()
            .resource::<SimulationResources>()
            .active_npc_service
            .as_ref()
            .is_some_and(|service| service.label_key == "STORAGE"));

        let store_packets = session.handle_packet(ClientPacket::StoreItem {
            from: i32::from(bag_item.slot),
            to: 4,
        });
        assert_eq!(
            store_packets,
            vec![ServerPacket::StoreItem {
                from: i32::from(bag_item.slot),
                to: 4,
                success: true
            }]
        );

        let take_back_packets = session.handle_packet(ClientPacket::TakeBackItem {
            from: 4,
            to: i32::from(bag_item.slot),
        });
        assert_eq!(
            take_back_packets,
            vec![ServerPacket::TakeBackItem {
                from: 4,
                to: i32::from(bag_item.slot),
                success: true
            }]
        );

        let snapshot = session.world_snapshot();
        assert!(snapshot
            .inventory_items
            .iter()
            .any(|item| item.key == bag_item.key
                && item.slot == bag_item.slot
                && item.container == ItemContainer::Bag1));
        assert!(!snapshot
            .storage_items
            .iter()
            .any(|item| item.key == bag_item.key && item.slot == 4));
    }

