    #[test]
    fn crystal_npc_buy_back_expiry_moves_items_to_used_goods() {
        let mut session = SimulationSession::new(wicked_trader_config());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let _ = session.interact(4990);
        let _ = session.select_npc_dialog_target("@BuySell");
        let sell_packets = session.handle_packet(ClientPacket::SellItem {
            unique_id: 4,
            count: 1,
        });
        assert!(sell_packets
            .iter()
            .any(|packet| matches!(packet, ServerPacket::SellItem { success: true, .. })));

        {
            let mut resources = session
                .app
                .world_mut()
                .resource_mut::<SimulationResources>();
            let entry = resources
                .npc_buy_back_items
                .iter_mut()
                .find(|entry| entry.script_key.ends_with("WickedTrader"))
                .expect("buy-back entry should exist");
            for item in &mut entry.items {
                item.expires_at_binary_datetime = 0;
            }
        }

        let _ = session.tick();

        let context = NpcInteractionContext {
            object_id: 4990,
            name: "Wicked Trader".to_string(),
            name_key: None,
            position: Point { x: 331, y: 271 },
            quest_ids: Vec::new(),
            script_key: Some("BichonProvince/NaturalCave/WickedTrader".to_string()),
            args: Vec::new(),
            input: None,
        };
        let buy_back = super::run_crystal_npc_script(
            session.app.world_mut(),
            &context,
            "BichonProvince/NaturalCave/WickedTrader",
            "@BuyBack",
        )
        .expect("buy-back service should run");
        assert!(buy_back.packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::NPCGoods { list, .. } if list.is_empty()
        )));

        let buy_sell = super::run_crystal_npc_script(
            session.app.world_mut(),
            &context,
            "BichonProvince/NaturalCave/WickedTrader",
            "@BuySell",
        )
        .expect("buy-sell service should run");
        let used_item = buy_sell.packets.iter().find_map(|packet| match packet {
            ServerPacket::NPCGoods { list, .. } => list
                .iter()
                .find(|item| item.item_index == 222 && item.count == 1 && !item.is_shop_item),
            _ => None,
        });
        let used_unique_id = used_item
            .expect("expired item should become used goods")
            .unique_id;

        let buy_packets = session.handle_packet(ClientPacket::BuyItem {
            item_index: used_unique_id,
            count: 1,
            panel_type: 0,
        });

        assert!(buy_packets
            .iter()
            .any(|packet| matches!(packet, ServerPacket::LoseGold { gold: 1000 })));
        assert!(buy_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::GainedItem { item } if item.item_index == 222 && item.count == 1
        )));
        assert!(buy_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::NPCGoods { list, .. }
                if !list.iter().any(|item| item.unique_id == used_unique_id)
        )));
    }

