    #[test]
    fn crystal_npc_param_and_mongen_spawn_runtime_monsters_on_current_map() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });
        let mut packets = Vec::new();
        let mut execution_state = CrystalNpcExecutionState::default();

        assert_eq!(
            execute_crystal_npc_action_line(
                session.app.world_mut(),
                "PARAM1 0 1",
                &mut packets,
                &mut execution_state,
            ),
            CrystalNpcActionControl::Continue
        );
        assert_eq!(
            execute_crystal_npc_action_line(
                session.app.world_mut(),
                "PARAM2 333",
                &mut packets,
                &mut execution_state,
            ),
            CrystalNpcActionControl::Continue
        );
        assert_eq!(
            execute_crystal_npc_action_line(
                session.app.world_mut(),
                "PARAM3 267",
                &mut packets,
                &mut execution_state,
            ),
            CrystalNpcActionControl::Continue
        );
        assert_eq!(
            execute_crystal_npc_action_line(
                session.app.world_mut(),
                "MONGEN Hen 2",
                &mut packets,
                &mut execution_state,
            ),
            CrystalNpcActionControl::Continue
        );

        let spawned_hens = session
            .world_snapshot()
            .entities
            .into_iter()
            .filter(|entity| {
                entity.kind == crate::WorldEntityKind::Monster
                    && entity.name == "Hen"
                    && entity.x >= 333
                    && entity.x <= 334
                    && entity.y >= 267
                    && entity.y <= 268
            })
            .count();
        assert!(packets.is_empty());
        assert!(spawned_hens >= 2);
    }

