    #[test]
    fn crystal_npc_checkmon_becomes_true_after_param_and_mongen() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });
        let mut packets = Vec::new();
        let mut execution_state = CrystalNpcExecutionState::default();
        let baseline_count = session
            .world_snapshot()
            .entities
            .into_iter()
            .filter(|entity| entity.kind == crate::WorldEntityKind::Monster)
            .count();

        assert!(!evaluate_crystal_npc_condition(
            session.app.world_mut(),
            &format!("CHECKMON > {baseline_count} 0 1")
        ));

        assert_eq!(
            execute_crystal_npc_action_line(
                session.app.world_mut(),
                "PARAM1 0 1",
                &mut packets,
                &mut execution_state,
            ),
            CrystalNpcActionControl::Continue
        );
        assert_eq!(
            execute_crystal_npc_action_line(
                session.app.world_mut(),
                "PARAM2 333",
                &mut packets,
                &mut execution_state,
            ),
            CrystalNpcActionControl::Continue
        );
        assert_eq!(
            execute_crystal_npc_action_line(
                session.app.world_mut(),
                "PARAM3 267",
                &mut packets,
                &mut execution_state,
            ),
            CrystalNpcActionControl::Continue
        );
        assert_eq!(
            execute_crystal_npc_action_line(
                session.app.world_mut(),
                "MONGEN Hen 2",
                &mut packets,
                &mut execution_state,
            ),
            CrystalNpcActionControl::Continue
        );

        let after_count = session
            .world_snapshot()
            .entities
            .into_iter()
            .filter(|entity| entity.kind == crate::WorldEntityKind::Monster)
            .count();

        assert!(after_count >= baseline_count + 2);
        assert!(evaluate_crystal_npc_condition(
            session.app.world_mut(),
            &format!("CHECKMON >= {} 0 1", baseline_count + 2)
        ));
    }

