    #[test]
    fn crystal_drop_table_gold_entry_spawns_pickup_gold_for_monster_death() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });
        let monster_position = Point { x: 342, y: 270 };
        let monster_object_id = 98_917_u32;
        let monster = spawn_crystal_monster_for_test(
            &mut session,
            monster_object_id,
            "OmaFighter",
            monster_position.clone(),
            MirDirection::Left,
            true,
        );

        let current_tick = session.app.world().resource::<SimulationResources>().tick;
        let mut packets = Vec::new();
        assert!(super::damage_monster_entity(
            session.app.world_mut(),
            monster,
            i32::MAX,
            current_tick,
            &mut packets,
        ));
        super::handle_monster_defeat(
            session.app.world_mut(),
            monster_object_id,
            "OmaFighter",
            &mut packets,
        );

        let expected_gold =
            super::crystal_drop_gold_amount(2000, current_tick, monster_object_id, 0);
        let expected_chunks = super::crystal_ground_gold_chunks(expected_gold);
        let drops = session
            .world_snapshot()
            .ground_drops
            .into_iter()
            .filter(|drop| drop.name == "Gold" && drop.quantity == 1)
            .collect::<Vec<_>>();
        assert_eq!(
            drops.len(),
            expected_chunks.len(),
            "OmaFighter should spawn Crystal MaxDropGold chunks"
        );

        assert!((1000..3000).contains(&expected_gold));
        let mut picked_gold = Vec::new();
        for drop in drops {
            set_player_position(
                &mut session,
                Point {
                    x: drop.x,
                    y: drop.y,
                },
            );
            let pickup_packets = session.pick_up(drop.object_id);
            picked_gold.extend(
                pickup_packets
                    .into_iter()
                    .filter_map(|packet| match packet {
                        ServerPacket::GainedGold { gold } => Some(gold),
                        _ => None,
                    }),
            );
        }
        assert_eq!(picked_gold, expected_chunks);
        assert_eq!(picked_gold.into_iter().sum::<u32>(), expected_gold);
    }

    fn crystal_test_drop_entry(
        raw_line: &str,
        chance_raw: &str,
        item_name: &str,
        amount: Option<u32>,
        group: Option<mir2_game_data::CrystalDropGroup>,
    ) -> mir2_game_data::CrystalDropEntry {
        mir2_game_data::CrystalDropEntry {
            raw_line: raw_line.to_string(),
            chance_raw: chance_raw.to_string(),
            chance_numerator: None,
            chance_denominator: None,
            item_name: item_name.to_string(),
            amount,
            modifiers: Vec::new(),
            group,
        }
    }

    fn crystal_test_item_drop(item_name: &str) -> mir2_game_data::CrystalDropEntry {
        crystal_test_drop_entry(&format!("0 {item_name}"), "0", item_name, Some(1), None)
    }

    fn crystal_test_gold_drop(amount: u32) -> mir2_game_data::CrystalDropEntry {
        crystal_test_drop_entry(&format!("0 Gold {amount}"), "0", "Gold", Some(amount), None)
    }

    fn crystal_test_group_drop(
        raw_line: &str,
        random: bool,
        first: bool,
        entries: Vec<mir2_game_data::CrystalDropEntry>,
    ) -> mir2_game_data::CrystalDropEntry {
        crystal_test_drop_entry(
            raw_line,
            "0",
            "GROUP",
            None,
            Some(mir2_game_data::CrystalDropGroup {
                random,
                first,
                entries,
            }),
        )
    }

    fn resolved_item_names(drops: &[super::ResolvedDropTemplate]) -> Vec<String> {
        drops
            .iter()
            .filter_map(|drop| match drop {
                super::ResolvedDropTemplate::Item { name, .. } => Some(name.clone()),
                super::ResolvedDropTemplate::Gold { .. } => None,
            })
            .collect()
    }

    #[test]
    fn crystal_group_random_keeps_gold_and_selects_one_successful_item() {
        let entry = crystal_test_group_drop(
            "0 GROUP*",
            true,
            false,
            vec![
                crystal_test_gold_drop(1_000),
                crystal_test_item_drop("(HP)DrugSmall"),
                crystal_test_item_drop("(MP)DrugSmall"),
            ],
        );

        let drops =
            super::crystal_attempt_drop_entry(&entry, 0, 91, 0).expect("group parent should pass");
        let gold = drops
            .iter()
            .filter_map(|drop| match drop {
                super::ResolvedDropTemplate::Gold { amount, .. } => Some(*amount),
                super::ResolvedDropTemplate::Item { .. } => None,
            })
            .collect::<Vec<_>>();
        let item_names = resolved_item_names(&drops);

        assert_eq!(gold.len(), 1, "GROUP* should keep successful child gold");
        assert!((500..1500).contains(&gold[0]));
        assert_eq!(item_names.len(), 1, "GROUP* should choose one item");
        assert!(item_names[0] == "(HP)DrugSmall" || item_names[0] == "(MP)DrugSmall");
    }

