    #[test]
    fn delete_character_removes_saved_entry_from_account() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        let _ = session.handle_packet(ClientPacket::Login {
            account_id: "demo".to_string(),
            password: "demo".to_string(),
        });
        let _ = session.handle_packet(ClientPacket::NewCharacter {
            name: "Blade".to_string(),
            gender: MirGender::Female,
            class: MirClass::Wizard,
        });

        let packets = session.delete_character(1);

        assert!(matches!(
            packets[0],
            ServerPacket::DeleteCharacterSuccess { character_index: 1 }
        ));
        let characters = session
            .handle_packet(ClientPacket::Login {
                account_id: "demo".to_string(),
                password: "demo".to_string(),
            })
            .into_iter()
            .find_map(|packet| match packet {
                ServerPacket::LoginSuccess { characters } => Some(characters),
                _ => None,
            })
            .expect("login success after delete");
        assert!(!characters.iter().any(|character| character.name == "Blade"));
    }

