    #[test]
    fn pickup_can_stack_into_full_inventory_when_stack_has_room() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });
        fill_all_bag_slots(&mut session);
        {
            let mut resources = session
                .app
                .world_mut()
                .resource_mut::<SimulationResources>();
            let item = resources
                .inventory_items
                .iter_mut()
                .find(|item| item.container == ItemContainer::Bag1 && item.slot == 0)
                .expect("slot 0 item should exist");
            item.key = "red-potion".to_string();
            item.name = "Red Potion".to_string();
            item.quantity = 19;
            item.description = "Nearly full Crystal potion stack.".to_string();
            item.weight = 1;
        }
        set_player_position(&mut session, Point { x: 330, y: 270 });

        super::spawn_ground_drop(
            session.app.world_mut(),
            Point { x: 330, y: 270 },
            "",
            None,
            super::DropLoot::InventoryItem {
                key: "red-potion".to_string(),
                name: "Red Potion".to_string(),
                description: "Stackable full bag pickup test item.".to_string(),
                weight: 1,
                durability_current: None,
                durability_max: None,
                added_attack: 0,
                added_defence: 0,
                added_stats: Vec::new(),
                cursed: false,
                socket_slots: 0,
                show_group_pickup: false,
            },
            1,
            "Red Potion".to_string(),
        );
        let drop_object_id = session
            .app
            .world()
            .resource::<SimulationResources>()
            .next_drop_object_id
            .saturating_sub(1);

        let packets = session.handle_packet(ClientPacket::PickUp);
        let snapshot = session.world_snapshot();

        assert!(packets
            .iter()
            .any(|packet| matches!(packet, ServerPacket::GainedItem { item } if item.count == 20)));
        assert!(!snapshot
            .ground_drops
            .iter()
            .any(|drop| drop.object_id == drop_object_id));
        assert!(snapshot.inventory_items.iter().any(|item| {
            item.key == "red-potion"
                && item.container == ItemContainer::Bag1
                && item.slot == 0
                && item.quantity == 20
        }));
    }

