    #[test]
    fn addstorage_chat_command_extends_existing_expiry() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let first_packets = session.handle_packet(ClientPacket::Chat {
            message: "@ADDSTORAGE".to_string(),
        });
        let first_expiry = first_packets
            .iter()
            .find_map(|packet| match packet {
                ServerPacket::ResizeStorage {
                    expiry_time_binary_datetime,
                    ..
                } => Some(*expiry_time_binary_datetime),
                _ => None,
            })
            .expect("first resize storage packet");

        let second_packets = session.handle_packet(ClientPacket::Chat {
            message: "@ADDSTORAGE".to_string(),
        });
        let second_expiry = second_packets
            .iter()
            .find_map(|packet| match packet {
                ServerPacket::ResizeStorage {
                    expiry_time_binary_datetime,
                    ..
                } => Some(*expiry_time_binary_datetime),
                _ => None,
            })
            .expect("second resize storage packet");

        assert!(second_expiry > first_expiry);
    }

    #[test]
    fn storage_rejects_slots_outside_accessible_capacity() {
        let mut session = SimulationSession::new(SimulationConfig::default());
        session.handle_packet(ClientPacket::StartGame { character_index: 0 });

        let bag_item = session
            .world_snapshot()
            .inventory_items
            .into_iter()
            .find(|item| matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2))
            .expect("bag item");

        activate_storage_service(&mut session);
        let invalid_packets = session.handle_packet(ClientPacket::StoreItem {
            from: i32::from(bag_item.slot),
            to: i32::from(BASE_STORAGE_SLOTS),
        });
        assert_eq!(
            invalid_packets,
            vec![ServerPacket::StoreItem {
                from: i32::from(bag_item.slot),
                to: i32::from(BASE_STORAGE_SLOTS),
                success: false
            }]
        );

        let expanded_config = SimulationConfig::default();
        {
            let mut store = expanded_config
                .account_store
                .lock()
                .expect("account store mutex should not be poisoned");
            let account = store.accounts.get_mut("demo").expect("demo account");
            account.storage_size = EXPANDED_STORAGE_SLOTS;
            account.has_expanded_storage = true;
        }
        let mut expanded_session = SimulationSession::new(expanded_config);
        expanded_session.handle_packet(ClientPacket::StartGame { character_index: 0 });
        let expanded_bag_item = expanded_session
            .world_snapshot()
            .inventory_items
            .into_iter()
            .find(|item| matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2))
            .expect("expanded bag item");

        activate_storage_service(&mut expanded_session);
        let valid_packets = expanded_session.handle_packet(ClientPacket::StoreItem {
            from: i32::from(expanded_bag_item.slot),
            to: i32::from(EXPANDED_STORAGE_SLOTS - 1),
        });
        assert!(valid_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::StoreItem {
                from,
                to,
                success: true
            } if *from == i32::from(expanded_bag_item.slot)
                && *to == i32::from(EXPANDED_STORAGE_SLOTS - 1)
        )));
        assert!(expanded_session
            .world_snapshot()
            .storage_items
            .iter()
            .any(|item| {
                item.slot
                    == u8::try_from(EXPANDED_STORAGE_SLOTS - 1)
                        .expect("expanded slot should fit in u8")
            }));
    }

